vec3 rectColor = vec3(0.01, 0.26, 0.57);

//noise background
const float noiseIntensity = 2.8;
const float noiseDefinition = 0.6;
const vec2 glowPos = vec2(-2., 0.);

//rectangles
const float total = 60.;//number of rectangles
const float minSize = 0.03;//rectangle min size
const float maxSize = 0.08-minSize;//rectangle max size
const float yDistribution = 0.5;


float random(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

float noise( in vec2 p )
{
    p*=noiseIntensity;
    vec2 i = floor( p );
    vec2 f = fract( p );
	vec2 u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ), 
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ), 
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}

float fbm( in vec2 uv )
{	
	uv *= 5.0;
    mat2 m = mat2( 1.6,  1.2, -1.2,  1.6 );
    float f  = 0.5000*noise( uv ); uv = m*uv;
    f += 0.2500*noise( uv ); uv = m*uv;
    f += 0.1250*noise( uv ); uv = m*uv;
    f += 0.0625*noise( uv ); uv = m*uv;

	f = 0.5 + 0.5*f;
    return f;
}

vec3 bg(vec2 uv )
{
    float velocity = iTime/1.6;
    float intensity = sin(uv.x*3.+velocity*2.)*1.1+1.5;
    uv.y -= 2.;
    vec2 bp = uv+glowPos;
    uv *= noiseDefinition;

    //ripple
    float rb = fbm(vec2(uv.x*.5-velocity*.03, uv.y))*.1;
    //rb = sqrt(rb); 
    uv += rb;

    //coloring
    float rz = fbm(uv*.9+vec2(velocity*.35, 0.0));
    rz *= dot(bp*intensity,bp)+1.2;

    //bazooca line
    //rz *= sin(uv.x*.5+velocity*.8);


    vec3 col = bgColor/(.1-rz);
    return sqrt(abs(col));
}


float rectangle(vec2 uv, vec2 pos, float width, float height, float blur) {

    pos = (vec2(width, height) + .01)/2. - abs(uv - pos);
    pos = smoothstep(0., blur , pos);
    return pos.x * pos.y; 

}

mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.xy * 2. - 1.;
    uv.x *= iResolution.x/iResolution.y;

    //bg
    vec3 color = bg(uv)*(2.-abs(uv.y*2.));

    //rectangles
    float velX = -iTime/8.;
    float velY = iTime/10.;
    for(float i=0.; i<total; i++){
        float index = i/total;
        float rnd = random(vec2(index));
        vec3 pos = vec3(0, 0., 0.);
        pos.x = fract(velX*rnd+index)*4.-2.0;
        pos.y = sin(index*rnd*1000.+velY) * yDistribution;
        pos.z = maxSize*rnd+minSize;
        vec2 uvRot = uv - pos.xy + pos.z/2.;
    	uvRot = rotate2d( i+iTime/2. ) * uvRot;
        uvRot += pos.xy+pos.z/2.;
        float rect = rectangle(uvRot, pos.xy, pos.z, pos.z, (maxSize+minSize-pos.z)/2.);
	    color += rectColor * rect * pos.z/maxSize;
    }

	fragColor = vec4(color, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // orig color
    fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
    // add bloom on top
    fragColor += 1.f * texelFetch(iChannel1, ivec2(fragCoord), 0);

    // gamma correct
    // I like the much more "contrasty" look without it too though...
    fragColor.rgb = pow(fragColor.rgb, vec3(1.f/2.2f));
}

/****************************************************************************************************************************
* Wanted to do a looping water shader for a phone background video
* Nothing fancy and most of the work is done by jaybird's caustics (https://www.shadertoy.com/view/ssfBDf) 
* Uncommend 'CHANGING_HUES' for a more colorful version :)
*****************************************************************************************************************************/


// WAVE GEO PARAMS
const int numWaves = 60;
const float oceanHeight = 0.f;
const float waveBaseHeight = 0.5; // how high the water must minimally be (min dist from floor)
const float waveMaxAmplitude = 0.5f;

// LIGHTING/SHADING
//#define CHANGING_HUES
const vec3 sunDir = normalize(vec3(0.25f,-0.05f, 0.25f));
const vec3 groundCol = vec3(0.85f, 0.755f, 0.65f); 
const vec3 waterColor_Static = vec3(0.12f, 0.6f, 0.9f); // only used if NOT using 'CHANGING_HUES'...
const float waterOpacity = 1.1;
const int bloomWidth = 20;
const float bloomBlurSigma = 2.f;
const float bloomThreshold = 1.f;

// UTILITY
#define LOOPING
const float PI = 3.1415927f;
float saturate(float v) { return clamp(v, 0., 1.); }
const float repeatDur = 8.0;
#ifdef LOOPING
#define iRepeatTime mod(iTime, repeatDur)
#else
#define iRepeatTime iTime
#endif
void RORD(vec2 uv, out vec3 ro, out vec3 rd) {
    ro = vec3(0.f, 2.f, 0.f);
    vec3 lookAt = vec3(0,0,0);

    vec3 cf = normalize(lookAt - ro);
    vec3 cr = normalize(cross(cf, vec3(0,0,1)));
    vec3 cu = normalize(cross(cr, cf));

#if 0 // ortho
    rd = cf;
    const float orthoSize = 2.0;
    ro += orthoSize * (uv.x * cr + uv.y * cu);
#else // perspective
    const float fl = 1.f; // focal length
    rd = normalize(uv.x * cr + uv.y * cu + fl * cf); 
#endif
}



// **********************************************************
// HELPER:
// - RAND/HASH from https://www.shadertoy.com/view/ttc3zr
// - HSV -> RGB from https://www.shadertoy.com/view/MsS3Wc
// - CAUSTIC STUFF from https://www.shadertoy.com/view/ssfBDf
// **********************************************************
// nojima - https://www.shadertoy.com/view/ttc3zr
uint murmurHash11(uint src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}
float hash11(float src) {
    uint h = murmurHash11(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}

// iq - https://www.shadertoy.com/view/MsS3Wc
vec3 hsv2rgb_smooth( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );

	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	

	return c.z * mix( vec3(1.0), rgb, c.y);
}

// jaybird - https://www.shadertoy.com/view/ssfBDf
vec4 mod289(vec4 x)
{
    return x - floor(x / 289.0) * 289.0;
}
vec4 permute(vec4 x)
{
    return mod289((x * 34.0 + 1.0) * x);
}
float causticNoiseBlur;
vec4 snoise(vec3 v)
{
    const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);

    // First corner
    vec3 i  = floor(v + dot(v, vec3(C.y)));
    vec3 x0 = v   - i + dot(i, vec3(C.x));

    // Other corners
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);

    vec3 x1 = x0 - i1 + C.x;
    vec3 x2 = x0 - i2 + C.y;
    vec3 x3 = x0 - 0.5;

    // Permutations
    vec4 p =
      permute(permute(permute(i.z + vec4(0.0, i1.z, i2.z, 1.0))
                            + i.y + vec4(0.0, i1.y, i2.y, 1.0))
                            + i.x + vec4(0.0, i1.x, i2.x, 1.0));

    // Gradients: 7x7 points over a square, mapped onto an octahedron.
    // The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
    vec4 j = p - 49.0 * floor(p / 49.0);  // mod(p,7*7)

    vec4 x_ = floor(j / 7.0);
    vec4 y_ = floor(j - 7.0 * x_); 

    vec4 x = (x_ * 2.0 + 0.5) / 7.0 - 1.0;
    vec4 y = (y_ * 2.0 + 0.5) / 7.0 - 1.0;

    vec4 h = 1.0 - abs(x) - abs(y);

    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);

    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));

    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;

    vec3 g0 = vec3(a0.xy, h.x);
    vec3 g1 = vec3(a0.zw, h.y);
    vec3 g2 = vec3(a1.xy, h.z);
    vec3 g3 = vec3(a1.zw, h.w);

    // Compute noise and gradient at P
    vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    vec4 m2 = m * m;
    vec4 m3 = m2 * m;
    vec4 m4 = m2 * m2;
    vec3 grad =
      -6.0 * m3.x * x0 * dot(x0, g0) + m4.x * g0 +
      -6.0 * m3.y * x1 * dot(x1, g1) + m4.y * g1 +
      -6.0 * m3.z * x2 * dot(x2, g2) + m4.z * g2 +
      -6.0 * m3.w * x3 * dot(x3, g3) + m4.w * g3;
    vec4 px = vec4(dot(x0, g0), dot(x1, g1), dot(x2, g2), dot(x3, g3));
    return mix(42.0, 0., causticNoiseBlur) * vec4(grad, dot(m4, px));
}


// **********************************************************
// Water Funcs
// **********************************************************
float SingleWaveHeight(vec2 uv, vec2 dir, float speed, float ampl, float time)
{
    float d = dot(uv,dir);
    const float loopFactor = 2.0 * PI / repeatDur; // we want a multiple of 2PI over 'repeatDur'
    speed = round(speed * loopFactor) / loopFactor; // round to closest multiple of 'loopFactor' so we get a multiple of 2*PI over the entire 'repeatDur'
    float ph = d * 10.f + time * speed; //sin(uv.x * 4.f + iTime) * sin(uv.y * 3.f + iTime);
    float h = (sin(ph) * 0.5f + 0.5f); // [0,1]
    h = pow(h, 2.f); // apply some steepness
    h = h * 2. - 1.; // [-1,1]
    return h * ampl;
}

float WaveHeight(vec2 uv, float time, int num)
{
    //uv *= .5f;
    uv *= 4.6f;

    float tRepeat = mod(time, repeatDur);

    float h = 0.f;
    float w = 1.f;
    float tw = 0.f;
    float s = 1.f;
    const float phBase = 0.2f;
    float deriv1 = 0.f; float deriv2 = 0.f;
    for(int i = 0; i < num; i++) {
        float rand = hash11(float(i)) * 2.f - 1.f;
        float dirMaxDiffer = float(i) / float(numWaves-1);
        dirMaxDiffer = clamp(dirMaxDiffer + 0.15f, 0.0, 1.0);
        dirMaxDiffer = pow(dirMaxDiffer, 1.f) * 2.f * PI;
        //float ph = phBase + rand * 0.75 * PI;
        float ph = phBase + (rand * dirMaxDiffer);
        vec2 dir = vec2(sin(ph), cos(ph));
        float h1 = SingleWaveHeight(uv, dir,(1.f + s * 0.05f), w, tRepeat);
        float h2 = SingleWaveHeight(uv, dir,(1.f + s * 0.05f), w, tRepeat - repeatDur);
        h += mix(h1, h2, clamp(tRepeat / repeatDur, 0.0, 1.0));
        //h += SingleWaveHeight(uv, dir, 1.f + s * 0.05f, w, time);
        tw += w;
        const float scale = 1.028f;
        //float scale = floor(float(i) / 20.0) + 1.0;
        w /= scale;
        uv *= scale;
        s *= scale;
    }

    h /= tw; // [0,1]
    h = waveBaseHeight + waveMaxAmplitude * h;
    return h;
}


vec3 WaterAbsorption(float t)
{
#ifdef CHANGING_HUES
   const float speed = 1.0 / repeatDur; // so that speed * repeatDur is whole num -> looping 
   t *= speed;
   t = fract(t);
   vec3 col = hsv2rgb_smooth(vec3(t, 0.7, 1.0));
   return waterOpacity/col;
#else
   return waterOpacity / waterColor_Static;
#endif
}

// 1D Gaussian Blur
vec4 BlurPass(ivec2 pixel, ivec2 size, sampler2D samp, bool horiz, float thresholdValue) 
{
    ivec2 dir = horiz ? ivec2(1,0) : ivec2(0,1);
    vec4 col = vec4(0.f);

    const float gaussScalar = 1.f / (bloomBlurSigma * sqrt(2.f * PI));
    const float gaussExp = 0.5f / (bloomBlurSigma * bloomBlurSigma);

    for(int i = -bloomWidth; i <= bloomWidth; i++) {
        ivec2 p = pixel + i * dir;
        if(min(p.x, p.y) < 0 || p.x >= size.x || p.y >= size.y) continue; // OOB
        vec4 c = texelFetch(samp, p, 0);
        c = max(vec4(0.f), c - vec4(thresholdValue));
        float w = gaussScalar * exp(-float(i*i) * gaussExp);
        col += w * c;
    }
    return col;
}

// Time dependent water height at p
float WaterHeight(vec3 p)
{
    float h = WaveHeight(p.xz * .1, iRepeatTime, numWaves) + oceanHeight;
    h += 0.05 * WaveHeight(p.xz * 0.6, iRepeatTime * 1.0, 20);
    return h;
}

// approx. sdf (only y dist)
float map(vec3 p)
{
    float d = p.y - WaterHeight(p);
    return d;
}

// from: https://iquilezles.org/articles/normalsSDF/
vec3 Normal( vec3 p)
{
    const float h = 0.001f;
    const vec2 k = vec2(1,-1);
    return normalize( k.xyy*map( p + k.xyy*h) + 
                      k.yyx*map( p + k.yyx*h ) + 
                      k.yxy*map( p + k.yxy*h ) + 
                      k.xxx*map( p + k.xxx*h ) );
}

// from: https://www.shadertoy.com/view/ssfBDf
float water_caustics(vec3 pos) {
    vec4 n = snoise( pos );

    pos -= 0.07*n.xyz;
    pos *= 1.62;
    n = snoise( pos );

    pos -= 0.07*n.xyz;
    n = snoise( pos );

    pos -= 0.07*n.xyz;
    n = snoise( pos );
    return n.w;
}

// RGB Caustics, slightly shifted per channel
vec3 Caustics(vec3 causticPos)
{
    vec3 caustics;
    vec3 o = vec3(1.0, 0.0, 1.0)*0.02;
    caustics.x = mix(water_caustics(causticPos + o    ), water_caustics(causticPos + o + 1.), 0.5);
    caustics.y = mix(water_caustics(causticPos + o*4.0), water_caustics(causticPos + o + 1.), 0.5);
    caustics.z = mix(water_caustics(causticPos + o*6.0), water_caustics(causticPos + o + 1.), 0.5);
    caustics = exp(caustics*4. - 1.);
    return caustics;
}

// NOTE: *Not* doing a classic ray march because this is a top down effect. 
// => Instead just assume the intersection point lies on a plane of at y == 'oceanHeight'
//        Then just calc normal at that point and use it to shade... 
//        Works in this perspective but would not work when looking at shallow angle...
vec3 Render(vec3 ro, vec3 rd)
{
    // Calc the alpha to make the looping work
    // NOTE: This is super basic. Simply blends back to the initial time state over the 'repeatDur'
    //       Works as the blend is slow and the wave patterns are not super recognizable from this perspective...
    // [0,1] based on how far into the current looping cycle we are
    float repeatAlpha = iRepeatTime / repeatDur;

    // Trace point on plane
    float t = 0.f;
    t = (oceanHeight - ro.y) / rd.y;
    vec3 p = ro + t * rd;

    // Calc Normal at that point and derive reflection & refraction vectors...
    vec3 n = Normal(p);
    vec3 n2 = normalize(n * vec3(1,0.25,1)); // artifically use less "upright" normal for more spread out specular reflections...
    vec3 refl = reflect(rd, n2);
    const float ior = 1.f / 1.2f;
    vec3 refr = refract(rd, n, ior);
    if(refr == vec3(0.f)) refr = refl; // total internal reflection

    // Calc some ground depth below water
    // NOTE: Don't get confused by the 'WaveHeight(...)' call 
    // -> has nothing to do with the waves, but simply reuses the func with static time param to get a smooth "bumpy" ground
    float hGround = 1.8f * WaveHeight(p.xz * 0.025f + vec2(0.05, 0.05), -10.f, 8);
    hGround += 1.f * WaveHeight(p.xz * 0.1f + vec2(1.05, 0.05), -10.f, 8);
    float groundDepth = -0.1f + hGround;
    float tGround = groundDepth / abs(refr.y);
    vec3 pGround = p + refr * tGround;

    // Calculate the caustic pattern on the ground
    const float causticSpeed = 0.25;
    float tCaustic = iRepeatTime * causticSpeed; // the time to use for caustic anim, loops in [0, repeatDur]
    float causticYMod = repeatDur * causticSpeed; // how far the caustic position offsets of the repeat time interval ('repeatDur')
    vec3 causticPos = pGround * 1.5 + vec3(0, tCaustic, 0); // move caustic position over time (animate)
    vec3 causticPos2 = causticPos + vec3(0, -causticYMod, 0); // secondary position progressing towards the initial state -> causticPos2 at time =='repeatDur' will be the same as causticPos at time == 0
    float causticAlpha = 1. - saturate(exp(-tGround * 2.)); // how visible the caustics are
    causticNoiseBlur = 1. - min(1., causticAlpha * 2.); // Make caustics blurrier based on depth. Sets param for Caustic calculations (see Common tab)
    vec3 caustics = Caustics(causticPos); 
    #ifdef LOOPING
    caustics = mix(caustics, Caustics(causticPos2), repeatAlpha); // blend back to initial caustics over 'repeatDur'
    #endif
    caustics *= causticAlpha;
    caustics *= 1.5f; // boost

    // Water Color/Absorption factor
    vec3 absorpColor = WaterAbsorption(iRepeatTime);

    // Specular reflections
    float spec = max(0.f, dot(refl, sunDir));
    spec = pow(spec, 512.f);

    // COMPOSE
    vec3 col = groundCol + caustics;
    col *= exp(-tGround * absorpColor);
    col += vec3(spec) * 2.f;

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.f * fragCoord - iResolution.xy) / iResolution.y;
    vec3 ro, rd;
    RORD(uv, ro, rd);

    vec3 col = Render(ro, rd);

    // Output to screen
    fragColor = vec4(col,1.0);
}

// BLOOM BLUR PASS X

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = BlurPass(ivec2(fragCoord), ivec2(iChannelResolution[0].xy), iChannel0, true, bloomThreshold);
}

// BLOOM BLUR PASS Y

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = BlurPass(ivec2(fragCoord), ivec2(iChannelResolution[0].xy), iChannel0, false, 0.f);
}

/*

    WASD flight over clouds/ocean ☁️
    ================================

    A flight over a field of cumulus at about 5 km, in somewhat real colours of the sky: the
    light comes from a physical atmosphere, the clouds cast their shadows on the sea below and
    stand in its mirror, the sea glitters where it mirrors the sun. It starts in the night
    under the stars and lets the sun rise. Fly yourself with the WASD keys, or let the
    autopilot weave over the heaps. i hope you don't experience too many hiccups during the
    flight...

    👉 drag the bar at the bottom for the sun's height, from the astronomical night to a
    high afternoon sun; the bar on the right for the cloud cover

    👉 keyboard A / D bank and turn, but roughtly keep the course,
    keyboard W / S climb and descend, don't fly too high, sorry lol; after two seconds
    without a key the autopilot flies again

    👉 drag the mouse in the frame to look around -- let go and the view glides back to the front

    👉 the options are at the top of the Common tab


    CLOUDS     a volume of heaps and lobes with fine bumps, marched with light from the sun
               through the cloud, forward scattering and two softer scattering octaves.

    TRACE      Buffer B marches one pixel in sixteen per frame; Buffer C keeps the full
               picture as a history, reprojected along the flight, with a Catmull-Rom fetch
               and a gentler treatment for the near clouds.

    SKY        Rayleigh, Mie and ozone, single scattering plus a multiple-scattering term,
               kept as a sky-view table in Buffer A and made again only while the sun moves;
               twilight, airglow and the stars below -6 deg, night vision in the dark.

    SEA        the statistics of the waves (Cox & Munk) with swell and wind-sea trains
               filtered by the pixel, the sun's glints in world measures, whitecaps by the
               wind, the sky and the clouds in the mirror, the clouds' shadows from a map
               of the cloud tops (Buffer D) -- drawn at full resolution in the Image.

    EYE        the eye's adaptation to the light's colour and brightness, the glare around
               the sun, a hue-keeping tonemap with a path to white, six lens ghosts.

    base: claude clouds by freeeborn, hash33 by Dave Hoskins (MIT), smin and ROT by Inigo Quilez,
    stars after Xor's efficient chaos, Cox & Munk 1954, Bruneton, Neyret & Holzschuch 2010,
    Monahan & O'Muircheartaigh 1980


    features:
    ---------

    - a flight over cumulus at about 5 km: steer with the keys (A / D bank and turn, W / S
      climb, Shift faster) or let the autopilot weave; it never flies into a cloud
    - a sunrise at the start: from the night's stars to a 5 deg sun in 10 s, then the bar
    - the sun bar from -18 to 60 deg, the cover bar from 33 to 95 %; the sun glides to it
    - real colours: a physical sky (Rayleigh, Mie, ozone, multiple scattering), twilight,
      airglow, about 7000 stars at night, night vision
    - the sea: waves filtered by the pixel, glints in world measures that twinkle, whitecaps,
      the sky and the clouds in its mirror, the clouds' shadows, past 60 km the sky mirrored
    - the eye: adaptation to colour and brightness, glare around the sun, six lens ghosts
    - many optimizations: multipass, the clouds traced for one pixel in sixteen per frame,
      TAA with a full-resolution history reprojected along the flight (clamped 5-tap
      Catmull-Rom, a Gaussian near zone, soft moving edges), empty-space skipping, lobe
      octaves reused in the march, light lookups skipped where they provably add nothing,
      a per-cell cache (desktop GL), coarser volume steps, the sky and the light as tables
      remade only while the sun moves, a cloud-top map marched once per world texel and
      scrolled, the open sea at full resolution without history, LEAN-filtered waves
      instead of supersampling, stars only at night, the lens ghosts written out

    this was done with claude code/opus 5.5 and my shader skillsystem + shadertoy desktop app
    and runner (benchmarks). many many many runs, fixes and so on, not at all a one prompter.

*/


// Image -- the history plus sea, sun, glare, ghosts, stars, eye, tonemap, UI. iChannel0 = Buffer C, iChannel1 = Buffer A.
// Options: top of the Common tab.

#define EXPOSURE 1.0

// sRGB encoding extended above 1 (values > 1 are brighter than SDR white on HDR canvases).
vec3 linearToSrgb(vec3 c) {
    return mix(12.92 * c, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}

// Hue-keeping SDR tonemap toward the display's white (a peak above 1 clips into a flat patch on SDR),
// with a path to white: light beyond the display loses its colour toward white at the same brightness,
// as on film and in the eye. TONE_SHOULDER: above white g = 1 + ln m (same value and slope at m = 1),
// so a glint's core at 5 .. 50 x white keeps a gradient instead of one flat white.
vec3 tonemapReal(vec3 l) {
    float m = max(max(l.r, l.g), max(l.b, 1e-6));
    float g = EXPOSURE * m;
#if TONE_SHOULDER
    g = g > 1.0 ? 1.0 + log(g) : g;
#endif
    float y = 1.0 - exp(-g);
    float w = 1.0 - exp(-0.5 * max(g - 1.5, 0.0));   // from 1.5 x the display's white on
    return y * mix(l / m, vec3(1.0), w);
}

#define SUN_R 0.004654          // the sun's angular radius (0.2666 deg), radians
#define SUN_SR 6.804e-5         // its solid angle, pi * SUN_R^2

// Area of (disc of radius r at the origin) inside the triangle (origin, a, b), signed by the
// turn a -> b; summed over a polygon's edges it gives the area of disc and polygon.
float discWedge(vec2 a, vec2 b, float r) {
    vec2 d = b - a;
    float dd = dot(d, d);
    float ad = dot(a, d);
    float h = ad * ad - dd * (dot(a, a) - r * r);
    if (h <= 0.0) return 0.5 * r * r * atan(a.x * b.y - a.y * b.x, dot(a, b) + 1e-30);   // the edge's line misses the disc
    h = sqrt(h);
    vec2 p0 = a + clamp((-ad - h) / dd, 0.0, 1.0) * d;   // the part of the edge inside the disc
    vec2 p1 = a + clamp((-ad + h) / dd, 0.0, 1.0) * d;
    return 0.5 * r * r * (atan(a.x * p0.y - a.y * p0.x, dot(a, p0) + 1e-30)    // sector before it
                        + atan(p1.x * b.y - p1.y * b.x, dot(p1, b) + 1e-30))   // sector after it
         + 0.5 * (p0.x * p1.y - p0.y * p1.x);                                  // triangle under it
}

// The sun disc's exact share of this pixel. On screen it is an ellipse: offset d (uv) is inside when
// |E d|^2 <= t^2 (FOCAL/lz + lxy.d)^2 (E d: d's ray across the sun, t = tan SUN_R; no 1 - cos(SUN_R)).
// An affine map makes it the unit circle and the pixel a parallelogram (area shares stay), then Green's
// theorem over the edges; within 0.03/255 of 384^2 rays per pixel.
float sunCover(vec2 fc, vec3 rtb, vec3 upb, vec3 fw, vec3 L) {
    vec3 lc = vec3(dot(L, rtb), dot(L, upb), dot(L, fw));          // the sun in camera axes
    vec3 e1 = normalize(cross(lc, vec3(0.0, 1.0, 0.0)));           // two axes across it
    vec3 e2 = cross(lc, e1);
    float t2 = tan(SUN_R) * tan(SUN_R), w0 = FOCAL / lc.z;
    float a = e1.x * e1.x + e2.x * e2.x - t2 * lc.x * lc.x;        // the form's 2x2 matrix
    float b = e1.x * e1.y + e2.x * e2.y - t2 * lc.x * lc.y;
    float c = e1.y * e1.y + e2.y * e2.y - t2 * lc.y * lc.y;
    vec2 lin = t2 * w0 * lc.xy;
    vec2 d0 = vec2(c * lin.x - b * lin.y, a * lin.y - b * lin.x) / (a * c - b * b);   // the centre's shift
    float R = sqrt(t2 * w0 * w0 + dot(lin, d0));
    vec2 ctr = w0 * lc.xy + d0;                                    // the ellipse's centre, uv units
    float sa = sqrt(a), sc = sqrt(c - b * b / a);                  // Cholesky: the map to the unit circle
    vec2 d;
    d = (fc + vec2(-0.5, -0.5) - 0.5 * iResolution.xy) / iResolution.y - ctr;
    vec2 q0 = vec2(sa * d.x + b / sa * d.y, sc * d.y) / R;
    d = (fc + vec2(0.5, -0.5) - 0.5 * iResolution.xy) / iResolution.y - ctr;
    vec2 q1 = vec2(sa * d.x + b / sa * d.y, sc * d.y) / R;
    d = (fc + vec2(0.5, 0.5) - 0.5 * iResolution.xy) / iResolution.y - ctr;
    vec2 q2 = vec2(sa * d.x + b / sa * d.y, sc * d.y) / R;
    d = (fc + vec2(-0.5, 0.5) - 0.5 * iResolution.xy) / iResolution.y - ctr;
    vec2 q3 = vec2(sa * d.x + b / sa * d.y, sc * d.y) / R;
    float area = 0.5 * ((q0.x * q1.y - q0.y * q1.x) + (q1.x * q2.y - q1.y * q2.x)
                      + (q2.x * q3.y - q2.y * q3.x) + (q3.x * q0.y - q3.y * q0.x));
    float disc = discWedge(q0, q1, 1.0) + discWedge(q1, q2, 1.0) + discWedge(q2, q3, 1.0) + discWedge(q3, q0, 1.0);
    return clamp(disc / area, 0.0, 1.0);
}

// The eye's veil: CIE 146:2002 general disability glare, veiling luminance per illuminance at the eye
// (1/sr) th deg from the light (0.1 .. 100), age 25, pigmentation 0.5; inside the disc the disc outshines it.
float glare(float th) {
    th = max(th, 0.2666);
    return 10.0 / (th * th * th) + (5.0 / (th * th) + 0.05 / th) * 1.0256 + 0.00125;
}

// ---------- the stars ----------
// Xor's "Efficient Chaos" (mini.gmshaders.com): layers of cells turned by the golden angle and warped by
// sines, one star per kept cell, on a Lambert equal-area map from the zenith, at the sky's real count and
// flux relative to the sun, dimmed by STAR_EXT per airmass: a star shows once it outshines the sky, so
// they appear one by one as the sun sinks. To 3 mag with the eye's glare (CIE 146).
uint starHash(uvec3 v) {                                               // pcg3d (Jarzynski & Olano 2020)
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return v.x;
}
vec2 starMap(vec3 d) { return d.xz * sqrt(2.0 / (1.0 + d.y)); }        // equal area: |P| <= 1.414 at the horizon
vec2 starWarp(vec2 P, mat2 orient, float cs, float fi) {
    vec2 p = (orient * P) * (2.0 / cs) + vec2(7.31, 3.17) * fi;       // Xor's cells of 2 units, shifted per layer
    return p + 0.6 * sin(p.yx);                                        // Xor's sine warp: irregular places
}
// The stars' radiance at rd (above the horizon; rdX, rdY = the next pixels' right and above) relative to
// the sun's irradiance; px = one pixel's angle (rad), sky = the sky's luma behind it in the same units.
vec3 starLight(vec3 rd, vec3 rdX, vec3 rdY, float px, float sky) {
    vec2 P = starMap(rd), PX = starMap(rdX), PY = starMap(rdY);
    const mat2 gold = mat2(-0.73736888, -0.67549029, 0.67549029, -0.73736888);   // the golden angle
    mat2 orient = mat2(1.0);
    float airT = pow(10.0, -0.4 * STAR_EXT / max(rd.y, 0.035));
    float peak = airT * STAR_GAIN / max(px * px, radians(STAR_SIZE) * radians(STAR_SIZE));   // a star's brightest pixel per flux
    float wpx = radians(STAR_SIZE) / px;                               // a star's size, pixels
    // the faintest magnitude still reaching 3 % of the sky: fainter layers are skipped, the cost follows what shows
    float mLim = min(-2.5 * log(max(0.03 * sky / peak, 1e-30)) * 0.4342945 - 26.74, STAR_MAG);
    int nL = mLim < -1.0 ? 0 : mLim < 1.0 ? 1 : mLim < 3.0 ? 2 : mLim < 5.0 ? 3 : 4;
    vec3 sum = vec3(0.0);
    // Four layers of two magnitudes, -1 .. 7 (seven of one cost 1.4 ms a frame): 7.5, 77.5, 716, 6200 stars
    // per hemisphere, cell side sqrt(pi / N), half the cells kept; ~3.1 x more stars per fainter magnitude
    // (u uniform -> m0 + log_3.1(1 + u (3.1^2 - 1))).
    for (int i = 0; i < 4; i++) {
        if (i >= nL) break;
        float fi = float(i);
        orient *= gold;
        float cs = i == 0 ? 0.6472 : i == 1 ? 0.2013 : i == 2 ? 0.06624 : 0.02251;
        vec2 p = starWarp(P, orient, cs, fi);
        vec2 cell = floor(p * 0.5);
        uint h = starHash(uvec3(ivec3(ivec2(cell) + 4096, i)));
        if ((h & 1023u) >= 512u) continue;                             // a hole: half the cells hold no star
        float u = float((h >> 10) & 1023u) / 1023.0;
        float m = i == 0 ? -1.0 + 2.0 * u : 2.0 * fi - 1.0 + log(1.0 + u * 8.61) * 0.8838;   // 1 / ln 3.1
        if (m > STAR_MAG) continue;
        vec2 sub = mod(p, 2.0) - 1.0;                                  // from the star (the warped cell's centre)
        // a lower bound of the distance in pixels (the map stretches at most ~2.3): a cell is 9 .. 300 px, a star
        // ~1, so the Jacobian below is skipped on nearly every pixel (on all it cost 1.4 ms a frame)
        float ang = length(sub) * 0.5 * cs;                            // ~ the angle to the star, radians
        bool near = ang * 0.43 / px < 1.0 + wpx;
        // the brightest layers' glare: within ~2 deg, faded out (no ring); further the pixel is done
        float gw = i < 2 ? (1.0 - smoothstep(0.02, 0.035, ang)) : 0.0;
        if (!near && gw <= 0.0) continue;
        float cov = 0.0;
        if (near) {
            // in pixels through the local Jacobian: the warp stretches cells up to +-60 %, the map up to 2:1
            // near the horizon -- one fixed scale drew a star as a 2 .. 3 px dash
            mat2 J = mat2(starWarp(PX, orient, cs, fi) - p, starWarp(PY, orient, cs, fi) - p);
            vec2 dpx = inverse(J) * sub;
            // the exact share of a STAR_SIZE square (a sky size, not a pixel) in the pixel box; its light is kept at any size
            vec2 ov = max(min(0.5 * wpx - dpx, vec2(0.5)) - max(-0.5 * wpx - dpx, vec2(-0.5)), 0.0);
            cov = ov.x * ov.y / (wpx * wpx);
        }
        float F = pow(10.0, -0.4 * (m + 26.74)) * airT * STAR_GAIN;   // the star's flux / the sun's
        float tc = float((h >> 20) & 255u) / 255.0;                    // its colour: blue-white .. orange
        vec3 col = mix(vec3(0.80, 0.93, 1.25), vec3(1.25, 0.95, 0.62), tc * tc);
        col /= dot(col, vec3(0.2126, 0.7152, 0.0722));
        float g = gw > 0.0 ? gw * GLARE * glare(degrees(ang)) : 0.0;
        sum += col * F * (cov / (px * px) + g);
    }
    return sum;
}

// Night vision (Purkinje): below ~3 cd/m2 the colours fade toward the rods' blue-green, fully below ~0.01.
// c = linear, after the white balance; k = the light's scale (trace units per physical radiance / RAD_K).
vec3 nightVision(vec3 c, float k) {
    float cd = max(dot(c, vec3(0.2126, 0.7152, 0.0722)), 1e-12) / (RAD_K * k) * 1.33e5;   // ~ cd/m2
    float s = NIGHT_VISION * (1.0 - smoothstep(-2.0, 0.477, log(cd) * 0.4342945));
    vec3 rods = vec3(dot(c, vec3(0.05, 0.50, 0.45))) * vec3(0.88, 0.99, 1.24);   // luma ~1 tint
    return mix(c, rods, s);
}

// ---------- the lens flare ----------
// A ghost = the sun reflected by one pair of lens surfaces, out of focus, on the line from the sun through
// the centre; six of a coated Cooke triplet (after aladiN's tetrahedron spectral rays), fixed, not traced,
// lit by the sun at the eye (TX_SUN) so they are as warm as the sun. Written out: a table loop cost 0.52 ms.
// A = place (x the sun's offset), R = radius (screen heights), F = share of the sun's light, CI / CO = the
// coating's colour inside / at the rim (luma 1); radiance = F / (pi (R / FOCAL)^2).
#define GHOST(A, R, F, CI, CO) { \
    vec2 q = (uv - (A) * s) * (1.0 / (R)); \
    float dd = dot(q, q); \
    if (dd < 1.69) { \
        vec2 h = abs(q); \
        float d = mix(max(dot(h, vec2(0.8660254, 0.5)), h.y), sqrt(dd), FLARE_ROUND) - 1.0; \
        float e = max(px / (R), 0.04); \
        float t = (d + 0.5 * e) * 12.5; \
        float w = max(1.0 - 0.5 * t * t, 0.0); \
        sum += mix(CI, CO, smoothstep(0.04, 1.0, dd)) * (clamp(0.5 - d / e, 0.0, 1.0) * (1.0 + 0.6 * w * w) \
             * ((F) * FOCAL * FOCAL / (pi * (R) * (R)))); \
    } }
// The ghosts' radiance at uv for the sun at screen point s (uv) with light sunE at the eye; px = a pixel in uv.
// Each: a hexagon (apothem 1) rounded by FLARE_ROUND, an edge of max(1 px, 4 % of R), a diffraction rim.
vec3 lensGhosts(vec2 uv, vec2 s, float px, vec3 sunE) {
    vec3 sum = vec3(0.0);
    GHOST(-0.42, 0.075, 1.2e-3, vec3(0.2424, 1.2120, 1.1312), vec3(0.2101, 1.1555, 1.7857))   // 1-2 teal
    GHOST( 0.30, 0.035, 2.5e-4, vec3(0.4237, 1.1501, 1.2107), vec3(0.2912, 1.1647, 1.4558))   // 0-1 cyan
    GHOST(-0.85, 0.110, 2.5e-4, vec3(1.3624, 0.7431, 2.4771), vec3(2.0467, 0.6140, 1.7397))   // 2-4 violet -> magenta
    GHOST(-1.25, 0.050, 4.0e-4, vec3(1.7097, 0.7694, 1.1968), vec3(1.5662, 0.8614, 0.7048))   // 4-5 pink -> salmon
    GHOST( 0.65, 0.022, 1.2e-4, vec3(0.6731, 1.0471, 1.4959), vec3(0.7224, 1.0508, 1.3135))   // 0-5 sky blue
    GHOST(-1.70, 0.160, 3.0e-4, vec3(1.5156, 0.9094, 0.3789), vec3(1.8222, 0.8200, 0.3644))   // 3-5 orange
    return sum * sunE * FLARE_GAIN;
}

// Von Kries in Bradford's cone space (linear sRGB -> XYZ -> Bradford), each cone WB_AMOUNT of the way
// toward the white point's; scaling the sRGB channels instead tinted the sky teal.
const mat3 RGB2LMS = mat3(0.422725, 0.055700, 0.021383, 0.491345, 0.961534, 0.087642, 0.027358, 0.023184, 0.980508);
const mat3 LMS2RGB = mat3(2.538045, -0.146004, -0.042299, -1.293277, 1.116648, -0.071607, -0.040237, -0.022329, 1.022753);

// Oklab (Bjorn Ottosson, 2020, public domain): lightness, green-red, blue-yellow.
vec3 rgbToOklab(vec3 c) {
    vec3 lms = mat3(0.4122214708, 0.2119034982, 0.0883024619, 0.5363325363, 0.6806995451, 0.2817188376,
                    0.0514459929, 0.1073969566, 0.6299787005) * max(c, 0.0);
    lms = pow(lms, vec3(1.0 / 3.0));
    return mat3(0.2104542553, 1.9779984951, 0.0259040371, 0.7936177850, -2.4285922050, 0.7827717662,
                -0.0040720468, 0.4505937099, -0.8086757660) * lms;
}
vec3 oklabToRgb(vec3 c) {
    vec3 lms = mat3(1.0, 1.0, 1.0, 0.3963377774, -0.1055613458, -0.0894841775,
                    0.2158037573, -0.0638541728, -1.2914855480) * c;
    lms = lms * lms * lms;
    return mat3(4.0767416621, -1.2684380046, -0.0041960863, -3.3077115913, 2.6097574011, -0.7034186147,
                0.2309699292, -0.3413193965, 1.7076147010) * lms;
}

// The eye's adaptation toward the white point wp. WB_MODE 0: von Kries per cone (Bradford). WB_MODE 1:
// only wp's blue-yellow goes (Oklab b, scaled with lightness): the twilight band is pale green in the
// physics already (Rayleigh of reddened sunlight), per-cone adaptation to the orange sun overdoes it.
vec3 adaptEye(vec3 c, vec3 wp) {
#if WB_MODE == 1
    vec3 lab = rgbToOklab(c), w = rgbToOklab(wp);
    lab.z -= WB_AMOUNT * w.z * lab.x / w.x;
    return max(oklabToRgb(lab), 0.0);
#else
    vec3 g = mix(vec3(1.0), (RGB2LMS * vec3(1.0)) / (RGB2LMS * wp), WB_AMOUNT);
    return max(LMS2RGB * (g * (RGB2LMS * c)), 0.0);
#endif
}

// the exact share of the pixel at p (its centre) inside the rectangle r = (x0, y0, x1, y1), px
float boxCover(vec2 p, vec4 r) {
    vec2 o = max(min(p + 0.5, r.zw) - max(p - 0.5, r.xy), 0.0);
    return o.x * o.y;
}

// ---------- the warnings ----------
// Letters in the bars' 5x7 font (rows packed as glyphRow below, no array): codes 0-9 = T U R N L E F I G H,
// 10 = a space, 11-14 = M A X D.
int warnGlyph(int c, int r) {
    int a = c == 0 ? 135327 : c == 1 ? 575025 : c == 2 ? 1001022 : c == 3 ? 644913 : c == 4 ? 541200 :
            c == 5 ? 999967 : c == 6 ? 999967 : c == 7 ? 135310 : c == 8 ? 770606 : c == 9 ? 1033777 :
            c == 11 ? 710513 : c == 12 ? 1033774 : c == 13 ? 141873 : c == 14 ? 575038 : 0;
    int b = c == 0 ? 4228 : c == 1 ? 14897 : c == 2 ? 18004 : c == 3 ? 17969 : c == 4 ? 32272 :
            c == 5 ? 32272 : c == 6 ? 16912 : c == 7 ? 14468 : c == 8 ? 15921 : c == 9 ? 17969 :
            c == 11 ? 17969 : c == 12 ? 17969 : c == 13 ? 17962 : c == 14 ? 31281 : 0;
    return r < 4 ? (a >> (5 * r)) & 31 : (b >> (5 * (r - 4))) & 31;
}
// The messages: 0 "TURN LEFT", 1 "TURN RIGHT", 2 "MAX ALTITUDE"; the code of letter ci, -1 past the end
int warnCode(int msg, int ci) {
    if (msg == 2) return ci == 0 ? 11 : ci == 1 ? 12 : ci == 2 ? 13 : ci == 3 ? 10 : ci == 4 ? 12 : ci == 5 ? 4 :
                         ci == 6 ? 0 : ci == 7 ? 7 : ci == 8 ? 0 : ci == 9 ? 1 : ci == 10 ? 14 : ci == 11 ? 5 : -1;
    if (ci < 4) return ci;                                          // "TURN"
    if (ci == 4) return 10;
    if (msg == 0) return ci == 5 ? 4 : ci == 6 ? 5 : ci == 7 ? 6 : ci == 8 ? 0 : -1;
    return ci == 5 ? 2 : ci == 6 ? 7 : ci == 7 ? 8 : ci == 8 ? 9 : ci == 9 ? 0 : -1;
}
int warnLen(int msg) { return msg == 0 ? 9 : msg == 1 ? 10 : 12; }
// 1 where message msg covers q (screen px from its lower-left corner), S screen px per font px
float warnText(vec2 q, float S, int msg) {
    if (q.x < 0.0 || q.y < 0.0) return 0.0;
    int ci = int(floor(q.x / S)) / 6;
    int code = warnCode(msg, ci);
    if (code < 0) return 0.0;
    vec2 g = floor((q - vec2(float(ci) * 6.0 * S, 0.0)) / S);
    if (g.x > 4.0 || g.y > 6.0) return 0.0;
    return float((warnGlyph(code, 6 - int(g.y)) >> (4 - int(g.x))) & 1);
}
// One sign, premultiplied over what is below: a red bar (rect), message msg white on a red box at o.
vec4 warnSign(vec2 p, vec4 bar, vec2 o, float S, int msg, vec4 below) {
    float pad = 2.0 * S, wT = (6.0 * float(warnLen(msg)) - 1.0) * S;
    float aR = max(boxCover(p, bar), 0.85 * boxCover(p, vec4(o - pad, o + vec2(wT, 7.0 * S) + pad)));
    float t = warnText(p - o, S, msg);
    vec3 C = below.rgb * (1.0 - aR) + vec3(0.92, 0.08, 0.05) * aR;
    float A = aR + below.a * (1.0 - aR);
    return vec4(C * (1.0 - t) + vec3(1.0) * t, t + A * (1.0 - t));
}
// The warnings, premultiplied (display rgb, coverage), blinking 1.5 times a second, soft edges: at the
// heading limit (TX_FLY3.zw, fading in over the last ~6 deg) a red bar on the blocked side and the way
// back ("TURN LEFT" / "TURN RIGHT") near its top; at the max altitude (TX_ALT.w) a bar along the top.
vec4 warnLayer(vec2 p, vec2 res, vec2 mk, float mAlt, float time) {
    float onT = smoothstep(0.5, 1.0, max(mk.x, mk.y));
    if (onT <= 0.0 && mAlt <= 0.0) return vec4(0.0);
    float blink = mix(0.15, 1.0, smoothstep(-0.3, 0.3, sin(9.42477796 * time)));
    float S = uiScale(res), bw = max(3.0, floor(0.012 * res.x + 0.5)), pad = 2.0 * S;
    vec4 w = vec4(0.0);
    if (onT > 0.0) {
        bool right = mk.y > mk.x;                                   // the right side blocked: "TURN LEFT"
        float wT = (right ? 53.0 : 59.0) * S;
        vec2 o = vec2(right ? floor(res.x - bw - 3.0 * S - pad - wT) : floor(bw + 3.0 * S + pad), floor(0.86 * res.y));
        w = warnSign(p, right ? vec4(res.x - bw, 0.2 * res.y, res.x, 0.8 * res.y) : vec4(0.0, 0.2 * res.y, bw, 0.8 * res.y),
                     o, S, right ? 0 : 1, vec4(0.0)) * (onT * blink);
    }
    if (mAlt > 0.0) {
        vec2 o = vec2(floor(0.5 * res.x - 35.5 * S), floor(res.y - bw - 3.0 * S - pad - 7.0 * S));   // 12 letters: 71 font px
        vec4 m = warnSign(p, vec4(0.2 * res.x, res.y - bw, 0.8 * res.x, res.y), o, S, 2, vec4(0.0)) * (mAlt * blink);
        w = m + w * (1.0 - m.a);
    }
    return w;
}

#if SHOW_BAR
// ---------- the sun bar ----------
// A 5x7 pixel font without an array (a const array is filled per pixel): rows 0-3 and 4-6 of each glyph
// packed 5 bits a row, bit 4 the leftmost column; codes 0-9 the digits, 10 minus, 11 degree, 12 per cent.
int glyphRow(int c, int r) {
    int a = c == 0 ? 708142 : c == 1 ? 135556 : c == 2 ? 67118 : c == 3 ? 69727 : c == 4 ? 600258 :
            c == 5 ? 64031 : c == 6 ? 999686 : c == 7 ? 133183 : c == 8 ? 476718 : c == 9 ? 509486 :
            c == 10 ? 1015808 : c == 11 ? 12876 : 133977;
    int b = c == 0 ? 14905 : c == 1 ? 14468 : c == 2 ? 32004 : c == 3 ? 14881 : c == 4 ? 2143 :
            c == 5 ? 14881 : c == 6 ? 14897 : c == 7 ? 8456 : c == 8 ? 14897 : c == 9 ? 12353 : c == 12 ? 19816 : 0;
    return r < 4 ? (a >> (5 * r)) & 31 : (b >> (5 * (r - 4))) & 31;
}
// "-6°" .. "60°": 1 where the text covers q (screen px from its lower-left corner), S screen px per font px
float barText(vec2 q, float S, int n) {
    if (q.x < 0.0 || q.y < 0.0) return 0.0;
    int a = n < 0 ? -n : n, neg = n < 0 ? 1 : 0, nd = a >= 10 ? 2 : 1;
    int ci = int(floor(q.x / S)) / 6;
    if (ci > neg + nd) return 0.0;
    int code = 11;                                                  // the degree sign
    if (ci < neg) code = 10;
    else if (ci < neg + nd) code = nd == 2 && ci == neg ? a / 10 : a % 10;
    vec2 g = floor((q - vec2(float(ci) * 6.0 * S, 0.0)) / S);
    if (g.x > 4.0 || g.y > 6.0) return 0.0;
    return float((glyphRow(code, 6 - int(g.y)) >> (4 - int(g.x))) & 1);
}
// The bar, premultiplied (display rgb, coverage): the sunlight's colours, a dark tick at 0 deg, a white
// marker at the sun's elevation, its value above it on a dark box.
vec4 barLayer(vec2 p, vec2 res, float elev) {
    vec4 b = barRect(res);
    float S = uiScale(res), bw = max(1.0, res.y / 270.0);
    if (p.y > b.w + 14.0 * S || p.x < b.x - 40.0 * S || p.x > b.z + 40.0 * S) return vec4(0.0);
    vec3 C = vec3(0.0); float A = 0.0;
    float aR = boxCover(p, b + vec4(-bw, -bw, bw, bw)), aS = boxCover(p, b);
    C = C * (1.0 - aR);  A = aR + A * (1.0 - aR);
    if (aS > 0.0) {
        vec3 bb = texelFetch(iChannel1, ivec2(int(clamp((p.x - b.x) / (b.z - b.x), 0.0, 1.0) * 255.0 + 0.5), BAR_ROW), 0).rgb;
        float xh = mix(b.x, b.z, barS(0.0));
        bb *= 1.0 - 0.6 * boxCover(p, vec4(xh - 0.5 * bw, b.y, xh + 0.5 * bw, b.w));
        C = C * (1.0 - aS) + bb * aS;  A = aS + A * (1.0 - aS);
    }
    float xm = mix(b.x, b.z, barS(elev));
    vec4 mk = vec4(xm - bw, b.y - 2.0 * bw, xm + bw, b.w + 2.0 * bw);
    float aMr = boxCover(p, mk + vec4(-bw, -bw, bw, bw)), aM = boxCover(p, mk);
    C = C * (1.0 - aMr);  A = aMr + A * (1.0 - aMr);
    C = C * (1.0 - aM) + vec3(1.0) * aM;  A = aM + A * (1.0 - aM);
    int n = int(sign(elev) * floor(abs(elev) + 0.5));               // -2.5 -> -3, not -2
    int nc = (n < 0 ? 1 : 0) + (abs(n) >= 10 ? 2 : 1) + 1;
    float pad = 2.0 * S, wT = (6.0 * float(nc) - 1.0) * S;
    vec2 o = vec2(clamp(floor(xm - 0.5 * wT), pad, res.x - wT - pad), floor(b.w + 2.0 * bw + pad + S));
    float aB = 0.55 * boxCover(p, vec4(o - pad, o + vec2(wT, 7.0 * S) + pad));
    C = C * (1.0 - aB);  A = aB + A * (1.0 - aB);
    float t = barText(p - o, S, n);
    C = C * (1.0 - t) + vec3(1.0) * t;  A = t + A * (1.0 - t);
    return vec4(C, A);
}

// The altitude over the sea, top left: "dddd M  ddddd FT" (4 .. 6 km, 14 .. 21 thousand ft: always 4 and
// 5 digits), both to 10, white on a dark box. 1 where the text covers q.
float hudText(vec2 q, float S, int m, int ft) {
    if (q.x < 0.0 || q.y < 0.0) return 0.0;
    int ci = int(floor(q.x / S)) / 6;
    if (ci > 15 || ci == 4 || ci == 6 || ci == 7 || ci == 13) return 0.0;
    vec2 g = floor((q - vec2(float(ci) * 6.0 * S, 0.0)) / S);
    if (g.x > 4.0 || g.y > 6.0) return 0.0;
    int r = 6 - int(g.y), row;
    if (ci < 4) row = glyphRow((m / (ci == 0 ? 1000 : ci == 1 ? 100 : ci == 2 ? 10 : 1)) % 10, r);
    else if (ci < 13 && ci > 7) row = glyphRow((ft / (ci == 8 ? 10000 : ci == 9 ? 1000 : ci == 10 ? 100 : ci == 11 ? 10 : 1)) % 10, r);
    else row = warnGlyph(ci == 5 ? 11 : ci == 14 ? 6 : 0, r);       // M, F, T
    return float((row >> (4 - int(g.x))) & 1);
}
vec4 hudLayer(vec2 p, vec2 res, float y) {
    float S = uiScale(res), pad = 2.0 * S, wT = 95.0 * S;           // 16 characters: 95 font px
    vec2 o = vec2(floor(0.035 * res.y + pad), floor(res.y - 0.035 * res.y - pad - 7.0 * S));
    if (p.x > o.x + wT + pad + 1.0 || p.y < o.y - pad - 1.0) return vec4(0.0);
    float km = (y - SEA_Y) * UNIT_KM;
    int m = int(floor(km * 100.0 + 0.5)) * 10, ft = int(floor(km * 328.084 + 0.5)) * 10;
    float aB = 0.55 * boxCover(p, vec4(o - pad, o + vec2(wT, 7.0 * S) + pad));
    float t = hudText(p - o, S, m, ft);
    return vec4(vec3(1.0) * t, t + aB * (1.0 - t));
}

// "<n>%": 1 where the text covers q, as barText
float coverText(vec2 q, float S, int n) {
    if (q.x < 0.0 || q.y < 0.0) return 0.0;
    int nd = n >= 100 ? 3 : n >= 10 ? 2 : 1;
    int ci = int(floor(q.x / S)) / 6;
    if (ci > nd) return 0.0;
    int code = 12;                                                  // the per cent sign
    if (ci < nd) { int dv = 1; for (int k = 0; k < nd - 1 - ci; k++) dv *= 10; code = (n / dv) % 10; }
    vec2 g = floor((q - vec2(float(ci) * 6.0 * S, 0.0)) / S);
    if (g.x > 4.0 || g.y > 6.0) return 0.0;
    return float((glyphRow(code, 6 - int(g.y)) >> (4 - int(g.x))) & 1);
}
// The cover bar on the right, the sun bar turned upright: the sea's dark blue (few clouds, bottom) to
// white (a closed deck, top), a white marker at the cover, its value left of it on a dark box.
vec4 coverLayer(vec2 p, vec2 res, float cov) {
    vec4 b = coverRect(res);
    float S = uiScale(res), bw = max(1.0, res.y / 270.0);
    if (p.x < b.x - 40.0 * S || p.y < b.y - 12.0 * S || p.y > b.w + 12.0 * S) return vec4(0.0);
    vec3 C = vec3(0.0); float A = 0.0;
    float aR = boxCover(p, b + vec4(-bw, -bw, bw, bw)), aS = boxCover(p, b);
    C = C * (1.0 - aR);  A = aR + A * (1.0 - aR);
    vec3 sc = mix(vec3(0.10, 0.20, 0.32), vec3(0.95), clamp((p.y - b.y) / (b.w - b.y), 0.0, 1.0));
    C = C * (1.0 - aS) + sc * aS;  A = aS + A * (1.0 - aS);
    float ym = mix(b.y, b.w, coverS(cov));
    vec4 mk = vec4(b.x - 2.0 * bw, ym - bw, b.z + 2.0 * bw, ym + bw);
    float aMr = boxCover(p, mk + vec4(-bw, -bw, bw, bw)), aM = boxCover(p, mk);
    C = C * (1.0 - aMr);  A = aMr + A * (1.0 - aMr);
    C = C * (1.0 - aM) + vec3(1.0) * aM;  A = aM + A * (1.0 - aM);
    int n = int(floor(cov * 100.0 + 0.5));
    int nc = (n >= 100 ? 3 : n >= 10 ? 2 : 1) + 1;
    float pad = 2.0 * S, wT = (6.0 * float(nc) - 1.0) * S;
    vec2 o = vec2(floor(b.x - 2.0 * bw - pad - wT - S), clamp(floor(ym - 3.5 * S), pad, res.y - 7.0 * S - pad));
    float aB = 0.55 * boxCover(p, vec4(o - pad, o + vec2(wT, 7.0 * S) + pad));
    C = C * (1.0 - aB);  A = aB + A * (1.0 - aB);
    float t = coverText(p - o, S, n);
    C = C * (1.0 - t) + vec3(1.0) * t;  A = t + A * (1.0 - t);
    return vec4(C, A);
}
#endif

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 hc = texelFetch(iChannel0, ivec2(fragCoord), 0);
    vec3 l = hc.rgb;
    vec3 ro, rtb, upb, fw;
    camLoad(iChannel1, 0, ro, rtb, upb, fw);
    vec3 L = texelFetch(iChannel1, TX_ELEV, 0).yzw;   // the sun the bar set (Buffer A)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 rd = normalize(uv.x * rtb + uv.y * upb + FOCAL * fw);
    vec3 Lv = dropView(L, -horizonDrop(ro.y));        // the sun drawn in the lowered sky's glow (HORIZON_DROP)
#if SEA
    // An open-sea pixel, drawn here at full resolution every frame; the trace gives only the sun's and the
    // mirror ray's transmittance (packed in .a) -- in its 1/16 lattice and history the glints smeared to grain.
    if (hc.a < 0.0 && rd.y < 0.0) {
        vec2 tt = seaUnpack(hc.a);                  // the sun's, the mirror ray's transmittance
        float ts = (SEA_Y - ro.y) / rd.y;
        vec4 lt0 = texelFetch(iChannel1, TX_LIGHT, 0);
        vec3 skyA = texelFetch(iChannel1, TX_LIGHT + ivec2(1, 0), 0).rgb;
        Sea sea = seaSurface(ro + rd * ts, rd, uv.x * rtb + uv.y * upb + FOCAL * fw, rtb, upb, ro.y, iResolution.y, T);
        vec3 water = seaShade(sea, skyLut(iChannel1, sea.rr, L) * (RAD_K * lt0.a), rd, L, lt0.rgb, skyA, tt.x, tt.y, SEA_POINTS, T);
        vec3 haze = skyAir(iChannel1, rd, L) * (RAD_K * lt0.a);
        l = mix(haze, water, exp(-atmoExt(atmoDensity(CAM_KM)) * UNIT_KM * ts));   // through the air (Buffer B's HAZE_MIX)
        // near the trace's 120 units the sea fades into the far clouds' fog, as in Buffer B
        float wF = farFogW(ro, rd);
        if (wF > 0.0) l = mix(l, farFog(iChannel1, rd, L, lt0.rgb, skyA, RAD_K * lt0.a, ro.y), wF);
    }
#endif
    // The sun's light at the eye, 0 behind a cloud; physical radiances in the trace's units (RAD_K).
    vec3 sunE = RAD_K * texelFetch(iChannel1, TX_LIGHT, 0).rgb * texelFetch(iChannel1, TX_SUN, 0).x;
    l += GLARE * glare(degrees(2.0 * asin(min(0.5 * length(rd - Lv), 1.0)))) * sunE;
#if LENS_FLARE
    // the ghosts within ~43 deg of the view's axis, fading from 17 deg (the lens's openings cut their path)
    float cosA = dot(Lv, fw);
    if (cosA > 0.7317 && sunE.g > 0.0)
        l += lensGhosts(uv, FOCAL * vec2(dot(Lv, rtb), dot(Lv, upb)) / cosA, 1.0 / iResolution.y, sunE) * smoothstep(0.7317, 0.9553, cosA);
#endif
    float kL = texelFetch(iChannel1, TX_LIGHT, 0).a;   // the light's scale (Buffer A)
#if STARS
    // the stars where the sky shows (depth 1e4); above a -2 deg sun even the brightest stays under 3 % of
    // the sky, so they are skipped (they cost 1 ms a frame by day)
    if (hc.a > 5000.0 && rd.y > 0.0 && texelFetch(iChannel1, TX_ELEV, 0).x < -2.0) {
        vec2 uvX = uv + vec2(1.0, 0.0) / iResolution.y, uvY = uv + vec2(0.0, 1.0) / iResolution.y;
        l += starLight(rd, normalize(uvX.x * rtb + uvX.y * upb + FOCAL * fw), normalize(uvY.x * rtb + uvY.y * upb + FOCAL * fw),
                       1.0 / (iResolution.y * FOCAL), dot(l, vec3(0.2126, 0.7152, 0.0722)) / (RAD_K * kL)) * (RAD_K * kL);
    }
#endif
    float cover = 0.0;
    // the disc only where the pixel shows sky (it is drawn lowered with the sky, the trace's clouds are not)
    if (hc.a > 5000.0 && dot(rd, Lv) > cos(SUN_R + 2.0 / (iResolution.y * FOCAL))) cover = sunCover(fragCoord, rtb, upb, fw, Lv);
    vec3 wp = texelFetch(iChannel1, TX_LIGHT + ivec2(2, 0), 0).rgb;
    vec3 Y = tonemapReal(nightVision(adaptEye(l, wp), kL));
    // the disc is ~1e5 x the clouds: blended after the tonemap by its exact coverage
    if (cover > 0.0) Y = mix(Y, tonemapReal(adaptEye(l + sunE / SUN_SR, wp)), cover);
    // +-0.5/255 dither so smooth gradients don't step on 8-bit canvases.
    fragColor = vec4(linearToSrgb(Y) + (ign(fragCoord) - 0.5) / 255.0, 1.0);
#if SHOW_BAR
    vec4 ui = barLayer(fragCoord, iResolution.xy, texelFetch(iChannel1, TX_COVER, 0).y);   // the target (the sun glides after it)
    fragColor.rgb = fragColor.rgb * (1.0 - ui.a) + ui.rgb;     // premultiplied, display values
    ui = coverLayer(fragCoord, iResolution.xy, texelFetch(iChannel1, TX_COVER, 0).x);
    fragColor.rgb = fragColor.rgb * (1.0 - ui.a) + ui.rgb;
    ui = hudLayer(fragCoord, iResolution.xy, texelFetch(iChannel1, TX_CAM, 0).y);   // the altitude
    fragColor.rgb = fragColor.rgb * (1.0 - ui.a) + ui.rgb;
#endif
    // the blinking warnings: the heading's limit and the max altitude (Buffer A)
    vec4 wl = warnLayer(fragCoord, iResolution.xy, texelFetch(iChannel1, TX_FLY3, 0).zw, texelFetch(iChannel1, TX_ALT, 0).w, T);
    fragColor.rgb = fragColor.rgb * (1.0 - wl.a) + wl.rgb;
}//aladiN

// Buffer A -- the state: flight, mouse look, the two bars, the sunrise, the light, the sky tables, the
// cloud-top map's march rows. iChannel0 = Buffer A, iChannel1 = Buffer D, iChannel2 = Keyboard.
// Options: top of the Common tab.
// Rows (texels: Common, TX_*): 0 the state, light, cameras and sun-ray segments; 1 the cloud tops
// ahead; 2 the state and the reference sky; 3 the bar's colours; MS_ROW .. psi_ms; SKY_ROW .. the
// sky-view table; mapWorkRow .. the map's march texels and origins (Buffer D copies them).

// a key held this frame (1) or not (0)
float key(int code) {
    return texelFetch(iChannel2, ivec2(code, 0), 0).x;
}

float wrapPi(float a) {
    return a - tau * floor(a / tau + 0.5);
}

// last frame's flight (f = TX_FLY, g = TX_FLY2); fresh: the base path at this moment, autopilot on
void flyLoad(bool fresh, out vec4 f, out vec4 g) {
    if (fresh) {
        float yaw, bank, hv, om;
        pathTurn(T, yaw, bank, hv);
        pathRate(T, om, hv);
        f = vec4(pathXZ(T), yaw, bankOf(hv, om));
        g = vec4(hv, ALT, AUTO_DELAY + 2.0, 0.0);
    } else {
        f = texelFetch(iChannel0, TX_FLY, 0);
        g = texelFetch(iChannel0, TX_FLY2, 0);
    }
}

// where the flight is tc s after state f at speed v, on the arc of its present bank (the chord
// along the mean heading, shortened by sinc)
vec2 flyAhead(vec4 f, float v, float tc) {
    float a = 0.5 * turnOf(v, f.w) * tc;
    float s = abs(a) > 1e-4 ? sin(a) / a : 1.0;
    float h = f.z + a;
    return f.xy + v * tc * s * vec2(sin(h), cos(h));
}

// Sun elevation (deg), cover, bar flag (1 sun, 2 cover: fixed on the press frame, kept in TX_MOUSE.w),
// .w the sun bar was used (the sunrise stops). A press on a bar sets it while held; so does a click
// shorter than a frame, which arrives as z < 0, w > 0 with nothing held last frame.
vec4 barState(bool fresh) {
    vec4 ms = fresh ? vec4(0.0) : texelFetch(iChannel0, TX_MOUSE, 0);
    float used = fresh ? 0.0 : texelFetch(iChannel0, TX_COVER, 0).z;
    float elev = used > 0.5 ? texelFetch(iChannel0, TX_COVER, 0).y : sunRise(T);   // the bar's target (TX_ELEV follows it)
    float cov = clamp(fresh ? COVER : texelFetch(iChannel0, TX_COVER, 0).x, COVER_MIN, COVER_MAX);   // a stored cover below a raised COVER_MIN comes up
#if SHOW_BAR
    bool held = iMouse.z > 0.0;
    float at = onBar(iMouse.xy, iResolution.xy) ? 1.0 : (onCoverBar(iMouse.xy, iResolution.xy) ? 2.0 : 0.0);
    float fl = held ? (ms.x > 0.5 ? ms.w : at) : 0.0;
    bool click = !held && ms.x < 0.5 && iMouse.w > 0.0;
    if (fl == 1.0 || (click && at == 1.0)) { elev = barElev(barPos(iMouse.x, iResolution.xy)); used = 1.0; }
    if (fl == 2.0 || (click && at == 2.0)) cov = coverOf(coverPos(iMouse.y, iResolution.xy));
    return vec4(elev, cov, fl, used);
#else
    return vec4(elev, cov, 0.0, used);
#endif
}

// The map's work texels: which world column this one marches this frame, if any. Rows 0 .. 7 the
// rows / columns of each window that scroll in (Buffer D's header origins -> this frame's o),
// rows 8 .. the band Buffer D asked to remake.
bool mapJob(ivec2 ip, int n, vec4 o, out vec2 xz) {
    xz = vec2(0.0);
    int r = ip.y - mapWorkRow(iResolution.xy);
    vec4 oOld = texelFetch(iChannel1, ivec2(0, n), 0);
    vec4 h1 = texelFetch(iChannel1, ivec2(1, n), 0);
    vec4 h2 = texelFetch(iChannel1, ivec2(2, n), 0);
    if (iFrame == 0 || h1.x != float(n) || ip.x >= 2 * n) return false;   // Buffer D starts the map this frame
    int c;
    ivec2 slot;
    if (r < 8) {
        c = r >> 2;
        ivec2 s = ivec2(c == 0 ? o.xy - oOld.xy : o.zw - oOld.zw);
        int kind = (r >> 1) & 1, k = r & 1;          // 0 = a new row, 1 = a new column; which of two
        int sa = kind == 0 ? s.y : s.x;
        if (ip.x >= n || k >= abs(sa) || abs(s.x) > 2 || abs(s.y) > 2) return false;
        int line = sa > 0 ? n - sa + k : k;
        slot = kind == 0 ? ivec2(ip.x, line) : ivec2(line, ip.x);
    } else {
        if (h2.y <= 0.0) return false;               // no band being remade
        c = ip.x >= n ? 1 : 0;
        slot = ivec2(ip.x - c * n, int(h2.x) * MAP_BAND + r - 8);
    }
    xz = ((c == 0 ? o.xy : o.zw) + vec2(slot) + 0.5) * (c == 0 ? MAP_S0 : MAP_S1);
    return true;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 ip = ivec2(fragCoord);
    fragColor = vec4(0.0);                          // every texel is written: the rest stays 0
    bool mapTx = false, mapGo = false;
    vec2 mapXZ = vec2(0.0);
    bool fresh = iFrame == 0 || texelFetch(iChannel0, TX_STAMP, 0).x != STATE_STAMP;
    vec4 fly, fly2;
    flyLoad(fresh, fly, fly2);
    float dt = clamp(iTimeDelta, 0.0, 0.1);         // a hitch moves at most 0.1 s worth
#if SEA
    int mwr = mapWorkRow(iResolution.xy);
    if (ip.y >= mwr && ip.y <= mwr + 8 + MAP_BAND) {
        int n = mapN(iResolution.xy);
        // The windows ahead along last frame's heading (the map is read a frame later anyway). A turn
        // swings them sideways (64 units ahead: 20 units/s at 0.32 rad/s); they follow at most 2 texels
        // a frame, what the scroll-in strips hold -- more remakes the whole map. Far off (a restart): remade.
        vec2 hd = vec2(sin(fly.z), cos(fly.z));
        vec4 o = vec4(mapOrigin(fly.xy, hd, MAP_S0, MAP_AHEAD0, n), mapOrigin(fly.xy, hd, MAP_S1, MAP_AHEAD1, n));
        vec4 oOld = texelFetch(iChannel1, ivec2(0, n), 0);
        if (iFrame > 0 && texelFetch(iChannel1, ivec2(1, n), 0).x == float(n) && all(lessThan(abs(o - oOld), vec4(32.0))))
            o = oOld + clamp(o - oOld, -2.0, 2.0);
        if (ip.y == mwr + 8 + MAP_BAND) {           // the windows' origins: Buffer D follows these
            if (ip.x == 0) fragColor = o;
            return;
        }
        mapTx = true;
        mapGo = mapJob(ip, n, o, mapXZ);
    }
#endif
    if (!mapTx && ((ip.y >= MS_ROW && ip.y < MS_ROW + MS_N && ip.x >= MS_N) || (ip.y >= MS_ROW + MS_N && ip.y < SKY_ROW)
        || (ip.y >= SKY_ROW && (ip.y >= SKY_ROW + SKY_NV || ip.x >= SKY_NU))
        || (ip.y == 2 && ip.x >= TX_REFSKY.x + 24 + FLY_N) || (ip.y == 0 && ip.x >= TX_SEG.x + SUN_SEGS))) return;
    vec4 st = texelFetch(iChannel0, TX_STAMP, 0);
    bool settled = !fresh && st.z == REF_KEY && st.y > 3.0;   // 4 frames since the start or a control change
    gCover = fresh ? COVER : texelFetch(iChannel0, TX_COVER, 0).x;   // last frame's (the bar sets it below)
    if (ip.y >= MS_ROW && ip.y < MS_ROW + MS_N) {                           // multiple scattering psi_ms(h, mus)
        vec4 old = texelFetch(iChannel0, ip, 0);    // made only when fresh or TURBIDITY changes
        if (!fresh && old.a == TURBIDITY) {
            fragColor = old;
        } else {
            float h = float(ip.y - MS_ROW) / float(MS_N - 1) * (R_ATMO - R_EARTH);
            float mus = float(ip.x) / float(MS_N - 1) * 2.0 - 1.0;
            fragColor = vec4(msTable(h, mus, min(iFrame, 0)), TURBIDITY);
        }
        return;
    }
    // Row 1: the cloud tops along last frame's turn continued (sample 0 = next frame's camera, the hard
    // floor), and the map's work texels: one cloudTop call site, another copy crashes the D3D link.
    if (ip.y == 1 || mapTx) {
        bool go = mapTx ? mapGo : ip.x < LOOK_N;
        vec2 xz = mapTx ? mapXZ : flyAhead(fly, fly2.x, 2.0 * dt + LOOK_DT * float(ip.x));
        float top = 0.0;
        if (go) top = cloudTop(xz, T);
        if (mapTx) fragColor = go ? vec4(top <= BASE + 1e-3 ? MAP_NONE : top, 0.0, 0.0, gCover) : vec4(0.0);
        else if (go) fragColor = vec4(top);
        return;
    }
    vec3 eye = vec3(0.0, R_EARTH + CAM_KM, 0.0);
    if (ip.y == BAR_ROW) {                          // the bar's colours: the sunlight at each height
        if (ip.x < 256) {
            float e = barElev(float(ip.x) / 255.0);
            vec3 c = sunAtEye(sunDir(e));
            c = c / max(max(c.r, c.g), max(c.b, 1e-6));
            c = mix(vec3(0.10, 0.16, 0.42), c, smoothstep(-1.6, -0.6, e));   // below the horizon: twilight blue
            fragColor = vec4(pow(c, vec3(0.4545)), 1.0);
        }
        return;
    }
    vec4 sb = barState(fresh);
    // the sun glides to the bar's target within ~SUN_TAU and snaps on when close, so the light and the
    // sky table (remade only while the elevation changes) are kept again
    float elevT = sb.x;
    float elevOld = fresh ? sunRise(T) : texelFetch(iChannel0, TX_ELEV, 0).x;
    sb.x = fresh || abs(elevT - elevOld) < 0.02 ? elevT : elevOld + (elevT - elevOld) * (1.0 - exp(-dt / max(SUN_TAU, 1e-4)));
    // One atmoSky call site: the view table (rows SKY_ROW ..) remade while the sun moves, the reference
    // sky (row 2, x 3 .. 26: 24 irradiance directions under SUN_REF) while not settled.
    bool lutTx = ip.y >= SKY_ROW;
    bool refTx = ip.y == 2 && ip.x >= TX_REFSKY.x && ip.x < TX_REFSKY.x + 24;
    if (lutTx || refTx) {
        if (settled && (refTx || texelFetch(iChannel0, TX_ELEV, 0).x == sb.x)) {
            fragColor = texelFetch(iChannel0, ip, 0);
            return;
        }
        // below -6 deg the model runs at -6 and dims (twiElev, twiDim); the night's airglow on top
        float eq = refTx ? SUN_REF : sb.x;
        vec3 Lq = sunDir(twiElev(eq));
        vec3 d = refTx ? irrDir(ip.x - TX_REFSKY.x) : skyDir((vec2(ivec2(ip.x, ip.y - SKY_ROW)) + 0.5) / vec2(SKY_NU, SKY_NV), Lq);
        fragColor = vec4(atmoSky(d, Lq, iChannel0) * twiDim(eq) + nightGlow(d), 1.0);
        return;
    }
    if (ip == TX_REF && settled && texelFetch(iChannel0, TX_REF, 0).w == REF_KEY) {
        fragColor = texelFetch(iChannel0, TX_REF, 0);   // the light at SUN_REF: made for 4 frames after
        return;                                         // the start or a control change (psi_ms first)
    }
    bool lightTx = ip.y == 0 && ip.x >= TX_LIGHT.x && ip.x < TX_SUN.x;
    if (lightTx && settled && texelFetch(iChannel0, TX_ELEV, 0).x == sb.x) {
        fragColor = texelFetch(iChannel0, ip, 0);   // the sun has not moved: last frame's light
        return;
    }
    if (ip == TX_REF || lightTx) {
        // the light for this frame's sun or (TX_REF) SUN_REF; the sky irradiance from last frame's sky texels
        vec3 Ls = sunDir(ip == TX_REF ? SUN_REF : sb.x);
        vec3 sunIrr = sunAtEye(Ls);
        vec3 sky = vec3(0.0);                       // sky irradiance on a horizontal surface
        for (int k = 0; k < 24; k++)
            sky += (ip == TX_REF ? texelFetch(iChannel0, TX_REFSKY + ivec2(k, 0), 0).rgb : skyLut(iChannel0, irrDir(k), Ls)) * irrW(k);
        // The eye adapts to the scene's mean luminance, roughly: 60 % cloud deck (albedo 0.8; sun on
        // tops and flanks -- 0.3 of the horizontal area faces it -- plus sky light), 40 % sky (mean
        // radiance ~ irradiance / pi); pi dropped. The sun alone made the twilight sky ~3 x too bright.
        float E = 0.48 * luma(sunIrr) * (max(Ls.y, 0.0) + 0.3 * length(Ls.xz)) + 0.88 * luma(sky);
        if (ip == TX_REF) {
            fragColor = vec4(E, luma(SUNK * SUN_COL) / max(luma(sunIrr), 1e-6), luma(sky), REF_KEY);
            return;
        }
        // At SUN_REF the sun on the clouds is SUNK * SUN_COL and the sky light SKY_AMB; elsewhere both
        // follow the physics, and the eye adapts EYE_ADAPT of the way (1 = always as bright).
        vec4 ref = texelFetch(iChannel0, TX_REF, 0);
        // No reference yet (frames 0 .. 1: the reference sky is made from last frame's texels, the
        // first from zeros): the fixed balance, k from SUN_REF -- this frame's sun below the horizon
        // gave 0.93 / 1e-6, and that one frame stayed in the history.
        bool refOk = !fresh && ref.w == REF_KEY && ref.x > 0.0 && ref.z > 0.0;
        float kRef = refOk ? ref.y : luma(SUNK * SUN_COL) / max(luma(sunAtEye(sunDir(SUN_REF))), 1e-6);
        // the eye opens up for a darker scene (NIGHT_ADAPT) more than it closes for a brighter one
        // (EYE_ADAPT): with the day's 0.33 the night would be ~1e4 x too dark to see
        float k = refOk ? kRef * pow(ref.x / max(E, 1e-12), E < ref.x ? NIGHT_ADAPT : EYE_ADAPT) : kRef;
        vec3 skyAmb = refOk ? sky * (luma(SKY_AMB) * k / (kRef * max(ref.z, 1e-9)))
                            : sky / max(luma(sky), 1e-9) * luma(SKY_AMB);
        vec3 wp = (sunIrr + sky) / max(luma(sunIrr + sky), 1e-12);   // what lights the scene: the white point
        int i = ip.x - TX_LIGHT.x;
        fragColor = i == 0 ? vec4(k * sunIrr, k) : (i == 1 ? vec4(skyAmb, 0.0) : vec4(wp, 0.0));
        return;
    }
    // The flight. Keys: A/D or <- -> turn, W/S or up / down climb / descend, Shift faster.
    float kTurn = max(key(KEY_RIGHT), key(39)) - max(key(KEY_LEFT), key(37));
    float kClimb = max(key(KEY_UP), key(38)) - max(key(KEY_DOWN), key(40));
    float fast = mix(1.0, FAST_K, key(KEY_FAST));
    bool steer = max(max(key(KEY_RIGHT), key(39)), max(key(KEY_LEFT), key(37)))
               + max(max(key(KEY_UP), key(38)), max(key(KEY_DOWN), key(40))) > 0.5;
    float idle = fresh ? fly2.z : (steer ? 0.0 : min(fly2.z + dt, 1e3));
    float ap = smoothstep(AUTO_DELAY, AUTO_DELAY + 1.5, idle);   // the autopilot's share: fades in over 1.5 s
    float omP, hvP;                                 // the base path's turn rate and speed now
    pathRate(T, omP, hvP);
    // the speed: the pilot's SPEED, the autopilot's the base path's (so it flies that track)
    float v = fly2.x + (mix(SPEED, hvP, ap) * fast - fly2.x) * (1.0 - exp(-dt / SPEED_TAU));
    // The roll: A/D toward TURN_BANK, no key back to level, the autopilot toward the base path's bank;
    // at most ROLL_RATE, slowing over the last ROLL_EASE s, the rate itself easing in and out within
    // ROLL_ACC. An airliner with passengers rolls at ~3 .. 5 deg/s: 0 .. 25 deg take ~8 s.
    float bankCmd = mix(kTurn * radians(TURN_BANK), bankOf(hvP, omP), ap);
    // The heading stays near the sun (away from it the clouds render poorly): its centre at most
    // FLY_SUN_EDGE of the screen width past the edge at look 0; phiH = its angle from the heading (> 0 =
    // left). A soft wall for pilot and autopilot: the bank allowed toward a side shrinks with the room
    // left (a bank b rolled out at ROLL_RATE turns ~b^2 / (2 R BANK_K v) more; half the room for the
    // eased roll), so the plane rolls out in time, flies along the limit and past it turns back gently.
    float phiFly = atan((0.5 + FLY_SUN_EDGE) * iResolution.x / iResolution.y / FOCAL);
    float phiH = wrapPi(fly.z - radians(SUN_AZ));
    float kW = radians(ROLL_RATE) * BANK_K * v;
    float remR = phiFly - phiH, remL = phiFly + phiH;   // room for a right / left turn
    bankCmd = clamp(bankCmd, -sign(remL) * sqrt(kW * abs(remL)), sign(remR) * sqrt(kW * abs(remR)));
    float rr = fresh ? 0.0 : fly2.w + (clamp((bankCmd - fly.w) / ROLL_EASE, -radians(ROLL_RATE), radians(ROLL_RATE)) - fly2.w)
                                    * (1.0 - exp(-dt / ROLL_ACC));
    float bank = fresh ? fly.w : fly.w + rr * dt;
    // the turn follows from the bank (a coordinated turn; a faster flight turns more slowly)
    float om = turnOf(v, bank);
    float yawNew = fresh ? fly.z : fly.z + 0.5 * (turnOf(fly2.x, fly.w) + om) * dt;
    vec2 xz = fresh ? fly.xy : fly.xy + v * dt * vec2(sin(0.5 * (fly.z + yawNew)), cos(0.5 * (fly.z + yawNew)));
    float yaw = wrapPi(yawNew);

    // Mouse look: the delta since the last held frame, only while held this and last frame (the release
    // frame's iMouse.xy is never read), never for a press that began on a bar. Let go, the look springs
    // back to the front (critically damped, rate in .zw, from rest), so a drag then WASD flies straight.
    vec4 lk = fresh ? vec4(0.0) : texelFetch(iChannel0, TX_LOOK, 0);
    vec2 look = lk.xy, lookV = lk.zw;
    vec4 ms = fresh ? vec4(0.0) : texelFetch(iChannel0, TX_MOUSE, 0);
    vec2 m = (iMouse.xy - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
    bool held = iMouse.z > 0.0;
    if (held && sb.z < 0.5) {
        if (ms.x > 0.5) look += (m - ms.yz) * LOOK_SENS;   // drag right = look right
        lookV = vec2(0.0);
    } else {
        float w = 2.0 / LOOK_RETURN;
        lookV += (-w * w * look - 2.0 * w * lookV) * dt;
        look += lookV * dt;
    }
    // up / down at most LOOK_PITCH of the screen height each way, clamped in the stored value (no windup)
    float pitchMax = atan(LOOK_PITCH / FOCAL);
    look.y = clamp(look.y, -pitchMax, pitchMax);
    // Sideways the turn's limit phiFly too (also keeps phi0 off the wrap); phi = the sun's angle from the
    // view axis (> 0 = left). Where the flight has turned the sun further out, the pan may not add to it.
    float phiMax = phiFly;
    float phi0 = wrapPi(yaw - radians(SUN_AZ));             // the sun's angle at look 0
    float phi = clamp(phi0 + look.x, -max(phiMax, -phi0), max(phiMax, phi0));
    look.x = phi - phi0;
    // the red glow (Image): fades in over the last 12 deg before the heading's limit, at the side
    // the plane may not turn further to (the right side when the sun leaves on the left)
    vec2 mark = vec2(1.0) - smoothstep(0.0, radians(12.0), vec2(phiFly + phi0, phiFly - phi0));
    vec4 msOut = vec4(held ? 1.0 : 0.0, held ? m : ms.yz, sb.z);

    // Altitude: the target = the pilot's altitude (plus the autopilot's climbs) and, with FLY_GUARD, the
    // highest top ahead + CLEAR. The guard jumps as cloud edges slide under the samples, so it is
    // low-passed (z) before the spring (up at ALT_TAU, down at DESCEND_TAU) follows the higher of the two.
    vec3 alt = fresh ? vec3(0.0) : texelFetch(iChannel0, TX_ALT, 0).xyz;
    float ahead = BASE;
    for (int k = 0; k < LOOK_N; k++) ahead = max(ahead, texelFetch(iChannel0, ivec2(k, 1), 0).x);
    // W/S tilt the flight path toward +-CLIMB_ANGLE at most PITCH_RATE, eased like the roll; let go and
    // it levels off. The pilot's altitude moves at v x tan(angle): ~100 m/s at 10 deg, an airliner after take-off.
    vec4 fly3 = fresh ? vec4(0.0) : texelFetch(iChannel0, TX_FLY3, 0);
    float gr = fresh ? 0.0 : fly3.y + (clamp((kClimb * radians(CLIMB_ANGLE) - fly3.x) / PITCH_EASE, -radians(PITCH_RATE), radians(PITCH_RATE)) - fly3.y)
                                    * (1.0 - exp(-dt / ROLL_ACC));
    float gam = fresh ? 0.0 : fly3.x + gr * dt;
    float vz = v * tan(gam);
    // A climb / descent starts from the altitude the plane is at (the guard often holds it above the
    // pilot's, and W would only raise that unseen value). The autopilot's climbs (the ALT_A sines) are
    // added as their change per frame, so a key that ends the autopilot leaves the altitude where it is.
    // It starts at the spring's rest point x + y PILOT_TAU, not at x: there the climb rate gets no kick
    // (from x the spring took 38 % of it in one frame, and the nose nodded with it).
    float sNow = dot(ALT_A, sin(ALT_W * T + ALT_P));
    float cmd = fresh ? ALT + sNow : fly2.y;
    float rest = alt.x + alt.y * PILOT_TAU;
    // A key that takes over from the autopilot (last frame's idle past AUTO_DELAY) holds the altitude the
    // plane is at: the pilot's altitude the guard had held it above was chased at PILOT_TAU, a nose dip
    // of 14 deg in 0.13 s on A / D.
    if (!fresh && steer && fly2.z > AUTO_DELAY) cmd = rest;
    if (fly3.x <= 1e-5 && gam > 1e-5) cmd = max(cmd, rest);
    if (fly3.x >= -1e-5 && gam < -1e-5) cmd = min(cmd, rest);
    if (!fresh) cmd += ap * (sNow - dot(ALT_A, sin(ALT_W * (T - dt) + ALT_P))) + vz * dt;
    // no windup: held S while the guard holds the camera up does not store a dive for later
    if (!fresh) cmd = max(cmd, alt.x - 1.0);
    cmd = clamp(cmd, ALT_MIN, ALT_MAX);
    // the guard: the tops ahead + the clearance, CLEAR_MIN for the pilot (else S is blocked), CLEAR for the autopilot
    float guard = -99.0;
#if FLY_GUARD
    guard = ahead + mix(CLEAR_MIN, CLEAR, ap);
#endif
    // The hard floor: the top right under the camera = row 1's sample 0 (last frame). A cloudTop of its
    // own here, a third copy of the cloud field in this pass, loses the WebGL context in the D3D link.
    float floorNow = texelFetch(iChannel0, ivec2(0, 1), 0).x + CLEAR_MIN;
    if (fresh) {
        alt = vec3(max(cmd, guard), 0.0, guard);    // row 1 holds nothing yet: floor from frame 1
    } else {
        alt.z += (guard - alt.z) * (1.0 - exp(-dt / TGT_TAU));
        float target = max(cmd, alt.z);
        float tc = mix(DESCEND_TAU, ALT_TAU, smoothstep(-0.3, 0.3, target - alt.x));
        tc = mix(tc, PILOT_TAU, (1.0 - ap) * smoothstep(-0.1, 0.1, cmd - alt.z));   // the pilot's altitude, when it leads, closely
        float w = 2.0 / tc;                        // critically damped spring
        alt.y += (w * w * (target - alt.x) - 2.0 * w * alt.y) * dt;
        alt.x += alt.y * dt;
    }
#if FLY_GUARD
    if (!fresh && alt.x < floorNow) {               // never into a cloud
        alt.x = floorNow;
        alt.y = max(alt.y, 0.0);
    }
#endif
    if (alt.x < ALT_MIN) {                          // never below the base path's range
        alt.x = ALT_MIN;
        alt.y = max(alt.y, 0.0);
    }

    // This frame's camera: yaw, pitch, bank keep the horizon level in the turn (no free-fly quaternion);
    // the nose pitched by twice the climb angle (limited for steep climbs) plus a slight downward look.
    vec3 rtb, upb, fw;
    // the start: looking up at the night sky until the sun stands at SUN_ELEV, then back over INTRO_LOOK_S
    float lookUp = INTRO_LOOK * pitchMax * (1.0 - smoothstep(SUN_RISE, SUN_RISE + INTRO_LOOK_S, T));
    cameraFrame(yaw + look.x, -0.12 + 2.0 * atan(clamp(alt.y, -0.3, 0.3), v) + look.y + lookUp, bank, rtb, upb, fw);
    vec4 c0 = vec4(xz.x, alt.x, xz.y, rtb.x);
    vec4 c1 = vec4(rtb.yz, upb.xy);
    vec4 c2 = vec4(upb.z, fw);

    if (ip == TX_FLY) fragColor = vec4(xz, yaw, bank);
    else if (ip == TX_FLY2) fragColor = vec4(v, cmd, idle, rr);
    else if (ip == TX_FLY3) fragColor = vec4(gam, gr, mark);
    else if (ip == TX_LOOK) fragColor = vec4(look, lookV);
    else if (ip == TX_MOUSE) fragColor = msOut;
    // .w the max altitude warning, over the last 0.1 units (50 m) below ALT_MAX
    else if (ip == TX_ALT) fragColor = vec4(alt, smoothstep(ALT_MAX - 0.1, ALT_MAX - 0.01, alt.x));
    else if (ip == TX_STAMP) fragColor = vec4(STATE_STAMP, fresh || st.z != REF_KEY ? 0.0 : min(st.y + 1.0, 100.0), REF_KEY, 0.0);
    else if (ip == TX_ELEV) fragColor = vec4(sb.x, sunDir(sb.x));
    else if (ip == TX_COVER) fragColor = vec4(sb.y, elevT, sb.w, 0.0);
    else if (ip == TX_SUN) {                        // the sun's transmittance: the segments marched last frame
        float od = 0.0;
        for (int i = 0; i < SUN_SEGS; i++) od += texelFetch(iChannel0, TX_SEG + ivec2(i, 0), 0).x;
        fragColor = vec4(exp(-od), 0.0, 0.0, 0.0);
    }
    else if (ip.x >= TX_SEG.x) fragColor = vec4(sunSegment(c0.xyz, sunDir(sb.x), ip.x - TX_SEG.x, T), 0.0, 0.0, 0.0);
    else if (ip.x >= TX_CAM.x) {
        int i = ip.x - TX_CAM.x;                    // 0..2 this frame, 3..5 the last frame
        if (i >= 3 && !fresh) {
            fragColor = texelFetch(iChannel0, ip - ivec2(3, 0), 0);
        } else {
            int j = i >= 3 ? i - 3 : i;
            fragColor = j == 0 ? c0 : (j == 1 ? c1 : c2);
        }
    }
}//aladiN

// Buffer B -- the volumetric cloud trace, one pixel of each 4x4 block per frame. iChannel0 = Buffer A, iChannel1 = Buffer D.
// Options: top of the Common tab.
// The trace grid is a quarter of the screen per axis (lower-left); the traced pixel of each
// block rotates (Common: tracePhase), with that screen pixel's own footprint and jitter.
// rgb = linear HDR colour; a = depth along the ray for Buffer C's reprojection (1e4 = sky), or
// for an open-sea sample its sun and mirror transmittance, packed (< 0, Common: seaPack).
// Buffer A holds the camera, sun, light and sky table; Buffer D last frame's cloud-top map (the
// sea's shadows and mirror). The cloud field is in Common: Buffer A needs it for the altitude.
//
// Shape: a low heap per jittered 2D cell, wide at the base, merging into a deck with domes;
// cauliflower lobes from hemispherical caps sqrt(1 - F1^2/R^2) around Worley points; fine lumps
// from billowed gradient noise, faded out below ~2 px and drifting upward so the detail boils.
// Density fades in over SOFT units: translucent edges, crisp lumps that shade each other.
// Light: sun shadow march with multiple-scattering octaves, sky ambient from a short upward
// occlusion march, dual-lobe phase for the silver lining, per-channel distance haze.


precision highp int;   

// exact speed levers (pixel-identical), each switchable
#ifdef GL_ES            // shadertoy.com (WebGL2 / ANGLE)
#define TUNE_CELLS 0    // the cache's inlined copies cost fxc ~4x compile time
#else                   // desktop GL
#define TUNE_CELLS 2    // heaps() keeps the 3x3 block's per-cell values (1: only in the march)
#endif


#if TUNE_CELLS
// heaps() with the 3x3 block's per-cell values kept while p stays in its cell: evaluated once
// per cell instead of once per call (~70 march steps per pixel cross only a few cells). Named
// variables, no arrays: a run-time array index is slow on the Intel driver.
// hA = ctr.x, ctr.y, r (-1: no heap in this cell), top; hB = the two wobble phases
vec4 hA0, hA1, hA2, hA3, hA4, hA5, hA6, hA7, hA8;
vec2 hB0, hB1, hB2, hB3, hB4, hB5, hB6, hB7, hB8;
ivec2 hCell = ivec2(0);
bool hValid = false;

#define HFILL(A, B, i, j) { \
    ivec3 c = ivec3(cell.x + i, 0, cell.y + j); \
    vec3 h = hash33(c); \
    vec3 g = hash33(c + ivec3(0, 1, 0)); \
    A = vec4((vec2(c.xz) + 0.3 + 0.4 * h.xy) * CELL, h.z >= gCover ? -1.0 : CELL * (0.24 + 0.16 * g.x), 2.0 * g.y); \
    B = vec2(6.28 * g.z, 6.28 * h.x); }

#define HCELL(A, B) if (A.z >= 0.0) { \
    float r = A.z; \
    float top = A.w; \
    vec3 q = p - vec3(A.x, 0.0, A.y); \
    float y = clamp(q.y, BASE, top); \
    vec2 wob = vec2(sin(y * 0.7 + B.x), cos(y * 0.6 + B.y)) * 0.35 * r; \
    float rad = r * (0.65 + 1.2 * smoothstep(top, top - 3.0, y)); \
    float tower = (length(q - vec3(wob.x, y, wob.y)) - rad) * 0.7; \
    d = smin(d, tower, 0.2 * CELL); }

float heapsC(vec3 p) {
    ivec2 cell = ivec2(floor(p.xz / CELL));
    if (!hValid || cell != hCell) {
        hCell = cell;
        hValid = true;
        HFILL(hA0, hB0, -1, -1) HFILL(hA1, hB1, 0, -1) HFILL(hA2, hB2, 1, -1)
        HFILL(hA3, hB3, -1, 0)  HFILL(hA4, hB4, 0, 0)  HFILL(hA5, hB5, 1, 0)
        HFILL(hA6, hB6, -1, 1)  HFILL(hA7, hB7, 0, 1)  HFILL(hA8, hB8, 1, 1)
    }
    float d = 1e3;
    HCELL(hA0, hB0) HCELL(hA1, hB1) HCELL(hA2, hB2)
    HCELL(hA3, hB3) HCELL(hA4, hB4) HCELL(hA5, hB5)
    HCELL(hA6, hB6) HCELL(hA7, hB7) HCELL(hA8, hB8)
    return d;
}
#endif

// the heaps() of the lighting lookups: TUNE_CELLS 2 gives them the cache too, 1 only the march
#if TUNE_CELLS == 2
#define heapsL heapsC
#else
#define heapsL heaps
#endif

// lobes() from octave o0 on, continuing from the q / fr an earlier call left, so the march
// computes octaves 0 and 1 once for both of its lobes() calls
float lobesRun(inout vec3 q, inout float fr, float fine, float d, float lod, int o0) {
    for (int o = o0; o < 6; o++) {
        float wgt = clamp(lod - float(o), 0.0, 1.0);
        if (wgt <= 0.0) break;
        float x = max(1.0 - worley2(q * fr) / 0.36, 0.0);
        float h = 0.6 / fr * RELIEF[o] * (o == 0 ? 1.0 : fine) * wgt;
        d -= h * x / sqrt(x + 0.04) * clamp(1.0 - d / (1.5 * h), 0.0, 1.0);
        q = ROT * q + 3.1;
        fr *= 2.1;
    }
    return d;
}

// cloud() for a lighting lookup that only counts below some d: lobes() lower d by at most
// 0.98 h per octave (1.2, 0.74, 0.27), so from hdSkip on (margin >= 0.024) it adds exactly 0.
float cloudL(vec3 p, float lod, float hdSkip) {
    float d = heapsL(p);
    if (d > 2.0) return d - 1.9;
    if (d >= hdSkip) return d;
    return lobes(p, d, lod);
}

float puff(float d) {
    return smoothstep(0.0, SOFT, -d);
}

// Lighting density with a ramp of width w: wide ramps keep sharp lobe rims out of the shadows.
float puffL(float d, float w) {
    return smoothstep(-0.3 * w, w, -d);
}

// The bumps at this frame's time (Common's bumps() takes the time as a parameter).
float bumps(vec3 p, float oct) {
    return bumps(p, oct, T);
}

// Optical depth toward the sun: the first short steps use more detail so lobes shadow each other.
float sunDepth(vec3 p, vec3 L, float lod) {
    float od = 0.0, s = 0.08;
    for (int k = 0; k < 6; k++) {
        p += L * s;
        float l = 1.0;
        if (k < 3) l = 2.0;
        if (k == 0) l = min(lod, 4.0);
        // from this heaps distance on d stays above puffL's zero and the bumps' 0.45: needs
        // 0.902 / 0.956 / 1.011 (k = 3..5), 1.060 (k = 2), 1.142 (k = 0, 1)
        float hs = 0.93 + 0.055 * float(k - 3);
        if (k < 3) hs = 1.09;
        if (k < 2) hs = 1.17;
        float d = cloudL(p, l, hs);
        if (k < 2 && d < 0.45) d -= bumps(p, 2.0);   // fine lumps shade each other
        od += puffL(d, SOFT * (1.0 + 2.0 * float(k))) * s;
        s *= 1.6;
    }
    return od;
}

// Optical depth straight up, coarse and soft: overhangs give a broad gradient, no silhouette.
float skyDepth(vec3 p) {
    // puffL(d, 0.8) is 0 from d = 0.24, out of lobes()' reach from 1.066 / 0.857 (2 / 1 octave)
    return puffL(cloudL(p + vec3(0.0, 0.5, 0.0), 2.0, 1.09), 0.8) * 0.6
         + puffL(cloudL(p + vec3(0.0, 1.5, 0.0), 1.0, 0.89), 0.8) * 1.0;
}

// Henyey-Greenstein phase, scaled by 4*pi so isotropic = 1.
float hg(float c, float g) {
    return (1.0 - g * g) / pow(1.0 + g * g - 2.0 * g * c, 1.5);
}

// The sun's and the sky's light on the clouds; the haze thins each channel on its own (blue
// first) and fills in with the sky's light.

#define SUN_LIGHT sunC
#define AMB_COL skyA
#define HAZE_MIX(c, t) mix(haze, c, exp(-airExt * (t)))

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    gCover = texelFetch(iChannel0, TX_COVER, 0).x;   // the cover the right bar set
    vec2 ares = ceil(iResolution.xy * 0.25);
    if (fragCoord.x > ares.x || fragCoord.y > ares.y) {   // whole thread groups leave here
        fragColor = vec4(0.0);
        return;
    }
    vec2 h = floor(fragCoord) * 4.0 + vec2(tracePhase(iFrame)) + 0.5;   // its screen pixel
    vec2 uv = (h - 0.5 * iResolution.xy) / iResolution.y;
    vec3 L = texelFetch(iChannel0, TX_ELEV, 0).yzw;   // the sun the bar set
    vec3 ro, rtb, upb, fw;
    camLoad(iChannel0, 0, ro, rtb, upb, fw);
    vec3 rd = normalize(uv.x * rtb + uv.y * upb + FOCAL * fw);

    float ph = mix(hg(dot(rd, L), -0.2), hg(dot(rd, L), 0.6), 0.3);
    // Droplets scatter without absorbing (1 km of cloud holds ~0.3 mm of water), so a cloud has
    // the colour of the light on it; the physical sky fills the background and the haze.
    vec4 lt0 = texelFetch(iChannel0, TX_LIGHT, 0);
    vec3 sunC = lt0.rgb;
    vec3 skyA = texelFetch(iChannel0, TX_LIGHT + ivec2(1, 0), 0).rgb;
    // the sky table in the trace's units (RAD_K): unscaled it is ~3x too dark next to the clouds
    vec3 haze = skyAir(iChannel0, rd, L) * (RAD_K * lt0.a);
    vec3 hazeC = skyCloudAir(iChannel0, rd, L) * (RAD_K * lt0.a);   // the clouds': no horizon step
    vec3 airExt = atmoExt(atmoDensity(CAM_KM)) * UNIT_KM;   // the air between camera and clouds
    vec3 sigT = vec3(SIGMA);
    vec3 albedo = vec3(1.0);
    float tEnd = min(120.0, rd.y > 0.0 ? (TOP - ro.y) / rd.y : (BASE - ro.y) / rd.y);
    float t = 0.0;
    vec3 trans = vec3(1.0), S = vec3(0.0);
    float wSum = 0.0, tSum = 0.0;   // depth for Buffer C: t weighted by what each step adds
    if (ro.y > TOP) t = (TOP - ro.y) / rd.y;
    float jit = ign(h);   // the jitter of the screen pixel, not of the trace texel
    float px = 1.0 / (iResolution.y * FOCAL);   // pixel footprint per unit of distance
    // Near clouds move too fast for the history to hold fine detail: the footprint grows with
    // jPar, the parallax in pixels per frame of a point 1 unit along this ray (falls off as 1 / t).
    vec3 pro, prt, pup, pfw;
    camLoad(iChannel0, 1, pro, prt, pup, pfw);
    vec3 dp = ro + rd - pro;
    vec2 hNear = FOCAL * vec2(dot(dp, prt), dot(dp, pup)) / max(dot(dp, pfw), 1e-4);
    vec2 hFar = FOCAL * vec2(dot(rd, prt), dot(rd, pup)) / max(dot(rd, pfw), 1e-4);
    float jPar = length(hNear - hFar) * iResolution.y;
    for (int i = 0; i < 500 && t < tEnd && trans.r > 0.02; i++) {   // red has the least extinction
        float dt = 0.03 + 0.003 * t;   // under SOFT out to the haze, so the ramp doesn't band
        dt *= STEP_K;   // option (changes the look): coarser volume steps
        vec3 p = ro + rd * (t + jit * dt);
#if TUNE_CELLS
        float hd = heapsC(p);
#else
        float hd = heaps(p);
#endif
        if (hd > 2.0) {
            // No lobe from the 3x3 block can be within 0.1. A tower plus lobes reaches at
            // most 2.32 + 1.52 outside its own cell, so anything farther is >= edge + 0.1 away.
            vec2 f = mod(p.xz, CELL);
            float edge = min(min(f.x, CELL - f.x), min(f.y, CELL - f.y));
            t += max(min(hd - 1.9, edge + CELL - 3.9), dt);
            continue;
        }
        // octaves 3+ add at most 0.14 outward: two octaves bound the distance across the lobe shell
        vec3 lq = p;
        float lfr = 0.5;
        float lfine = 0.35 + 0.65 * smoothstep(-5.0, 3.0, p.y);
        float d2 = lobesRun(lq, lfr, lfine, hd, 2.0, 0);   // = lobes(p, hd, 2.0)
        float dc = d2 - 0.25;
        if (dc > 0.0) {
            t += max(dc * 0.5, dt);
            continue;
        }
        // Octave count from footprint: octave o has lobe radius 1.2/2.1^o; keep those >= 2 px.
        float pxN = px * max(1.0, NEAR_LOD_K * jPar / max(t, 0.1));   // near filter
        float lod = clamp(log2(0.6 / (pxN * max(t, 0.1))) / 1.07 + 1.0, 2.0, MAX_OCT);
        float d = lobesRun(lq, lfr, lfine, d2, lod, 2);    // = lobes(p, hd, lod)
        if (d > 0.45) {   // fine bumps push out by ~0.3 at the 99th percentile
            t += max((d - 0.45) * 0.5, dt);
            continue;
        }
        // Fine bump octaves down to ~2 px (first period 0.33 units).
        float foct = clamp(log2(0.33 / (2.0 * pxN * max(t, 0.1))) + 1.0, 1.0, 4.0);
        d -= bumps(p, foct);
        float dens = puff(d);
        if (dens <= 0.0) {
            t += dt;
            continue;
        }
        float od = sunDepth(p, L, lod);
        // direct sun with forward-scattering phase plus two softer multiple-scattering octaves
        vec3 sun = exp(-sigT * od) * ph
                 + MS * (0.5 * exp(-0.25 * sigT * od) + 0.25 * exp(-0.06 * sigT * od)) * mix(ph, 1.0, 0.6);
        float hy = smoothstep(-4.0, 8.0, p.y);
        vec3 amb = AMB * AMB_COL * (0.1 + 0.25 * hy) * exp(-1.5 * skyDepth(p));
        vec3 lum = mix(hazeC, SUN_LIGHT * sun + amb, exp(-airExt * t));
        vec3 tr = exp(-sigT * dens * dt);
        float wD = trans.r * (1.0 - tr.r);
        wSum += wD;
        tSum += wD * t;
        S += trans * albedo * (1.0 - tr) * lum;
        trans *= tr;
        t += dt;
    }
    bool seaOpen = false, seaHit = false;
    float seaSh = 1.0, seaTr = 1.0;
#if SEA
    // the sea, where the ray leaves the cloud base within 120 units (beyond: the far band below)
    if (rd.y < 0.0 && trans.r > 0.02 && (BASE - ro.y) / rd.y <= 120.0) {
        float ts = (SEA_Y - ro.y) / rd.y;
        vec3 sp = ro + rd * ts;
        // last frame's cloud-top map: its header says whether it exists yet
        float nM = float(mapN(iResolution.xy));
        vec4 mh = texelFetch(iChannel1, ivec2(0, int(nM)), 0);
        bool mapOk = texelFetch(iChannel1, ivec2(1, int(nM)), 0).xy == vec2(nM, 0.0);   // of this size, every band made
        vec2 msz = vec2(textureSize(iChannel1, 0));
        vec3 Ls = normalize(vec3(L.x, max(L.y, 0.01), L.z));   // a sun at or below the horizon: grazing
        // the sun's disc (0.53 deg) widens a shadow's edge by 0.0093 x the distance to the cloud
        float sh = mapOk ? colTrans(iChannel1, sp, Ls, mh, nM, msz, 0.0093) : seaShadow(sp, L);
        sh = mix(1.0, sh, SEA_SHADOW_K);   // the shadows' strength
        // smooth here: the Image draws an open-sea pixel's glitter at full resolution
        Sea sea = seaSurface(sp, rd, uv.x * rtb + uv.y * upb + FOCAL * fw, rtb, upb, ro.y, iResolution.y, T);
        // the mirror ray through the clouds, its edge softened by the waves' ~2 slope deviations
        seaTr = SEA_MIRROR != 0 && mapOk
              ? colTrans(iChannel1, sp, normalize(sea.rr), mh, nM, msz, 2.0 * sqrt(0.5 * (sea.S[0][0] + sea.S[1][1]))) : 1.0;
        seaSh = sh;
        vec3 water = seaShade(sea, skyLut(iChannel0, sea.rr, L) * (RAD_K * lt0.a), rd, L, sunC, skyA, sh, seaTr, 0.0, T);
        haze = HAZE_MIX(water, ts);                  // through the air to the eye
        // near the trace's 120 units the sea fades into the far clouds' fog (Common: farFog)
        float wF = farFogW(ro, rd);
        if (wF > 0.0) haze = mix(haze, farFog(iChannel0, rd, L, sunC, skyA, RAD_K * lt0.a, ro.y), wF);
        wSum += trans.r;                                 // the history reprojects it at its depth
        tSum += trans.r * ts;
        seaOpen = trans.r > 0.98;                        // no cloud in front: the Image draws it
        seaHit = true;
    }
#endif
    // The far band (Common: farBand): past 120 units the sky table below the horizon would draw a
    // dark band, so the ray meets a flat deck at the tops' height (lit tops, sea between, by the
    // cover) fading into the sky at the level, continuous behind soft clouds.
    if (rd.y < 0.0 && trans.r > 0.02 && !seaHit) {
        haze = farBand(iChannel0, ro, rd, L, sunC, skyA, RAD_K * lt0.a, gCover, T);
        // the far band comes out of the same fog above the line (Common: farFog)
        float wF = farFogW(ro, rd);
        if (wF > 0.0) haze = mix(haze, farFog(iChannel0, rd, L, sunC, skyA, RAD_K * lt0.a, ro.y), wF);
    }
    // an upward ray's background: the sky with its horizon lowered under the far clouds (HORIZON_DROP); the
    // clouds' and the sea's haze above stays the true airlight (lowered, the sky table's own horizon -- where
    // the air in front of the ground begins -- crossed the far cloud field as a line)
    if (rd.y >= 0.0) haze = skyLut(iChannel0, dropView(rd, horizonDrop(ro.y)), L) * (RAD_K * lt0.a);
    vec3 l = S + trans * haze;   // the sun's disc is drawn in the Image, at full resolution
    // the cap at 100 guards the history from one bad frame (lit clouds stay below ~3, the glitter
    // is white long before); .a = depth or the open sea's packed transmittances (see the top)
    fragColor = vec4(min(l, vec3(100.0)), seaOpen ? seaPack(seaSh, seaTr) : (wSum > 0.02 ? tSum / wSum : 1e4));
}

// Buffer C -- the full-resolution history. iChannel0 = Buffer B, iChannel1 = Buffer C (itself), iChannel2 = Buffer A.
// Options: top of the Common tab.
// The traced pixel of each 4x4 block takes Buffer B's fresh sample, the other 15 last frame's
// picture reprojected from their own depth; rejected or off-screen history falls back to the
// fresh samples. rgb = linear HDR colour, a = depth along the ray (1e4 = sky) or an open-sea
// pixel's packed transmittances (< 0, Common: seaPack).

#define REJECT 0.15     // history rejected above this relative depth difference
#define SECOND_DEPTH 2  // also follow the nearest fresh sample's depth (2: only where it disagrees)
#define CR_CLAMP 1      // keep the Catmull-Rom fetch inside its 2x2 texels' range (no ringing)
#define CR_TAPS 5       // Catmull-Rom taps: 9, or 5 (corners left out)
// Near clouds smear the history: the parallax per frame (a turn reprojects exactly) fades from
// the plain history (far) to TAA on a Gaussian blend of the fresh samples (near).
#define EDGE0 0.15      // relative depth spread of the fresh samples around: edge starts...
#define EDGE1 0.5       // ...and is full

vec4 fresh(ivec2 a, vec2 ares) {
    return texelFetch(iChannel0, clamp(a, ivec2(0), ivec2(ares) - 1), 0);
}

// Catmull-Rom fetch of last frame's colour at p (pixels): bilinear would blur a pixel that is
// resampled up to 15 frames in a row.
vec3 historyCR(vec2 p) {
    vec2 R = iResolution.xy;
    vec2 c = floor(p - 0.5) + 0.5;
    vec2 f = p - c;
    vec2 w0 = f * (-0.5 + f * (1.0 - 0.5 * f));
    vec2 w1 = 1.0 + f * f * (-2.5 + 1.5 * f);
    vec2 w2 = f * (0.5 + f * (2.0 - 1.5 * f));
    vec2 w3 = f * f * (-0.5 + 0.5 * f);
    vec2 w12 = w1 + w2;
    vec2 t0 = (c - 1.0) / R, t12 = (c + w2 / w12) / R, t3 = (c + 2.0) / R;
#if CR_TAPS == 5
    // the four corner taps carry the smallest weights: left out, the rest renormalised
    vec3 s = (texture(iChannel1, vec2(t12.x, t0.y)).rgb * w12.x * w0.y
            + texture(iChannel1, vec2(t0.x, t12.y)).rgb * w0.x * w12.y
            + texture(iChannel1, vec2(t12.x, t12.y)).rgb * w12.x * w12.y
            + texture(iChannel1, vec2(t3.x, t12.y)).rgb * w3.x * w12.y
            + texture(iChannel1, vec2(t12.x, t3.y)).rgb * w12.x * w3.y)
           / (w12.x * w0.y + w0.x * w12.y + w12.x * w12.y + w3.x * w12.y + w12.x * w3.y);
#else
    vec3 s = (texture(iChannel1, vec2(t0.x, t0.y)).rgb * w0.x
            + texture(iChannel1, vec2(t12.x, t0.y)).rgb * w12.x
            + texture(iChannel1, vec2(t3.x, t0.y)).rgb * w3.x) * w0.y
           + (texture(iChannel1, vec2(t0.x, t12.y)).rgb * w0.x
            + texture(iChannel1, vec2(t12.x, t12.y)).rgb * w12.x
            + texture(iChannel1, vec2(t3.x, t12.y)).rgb * w3.x) * w12.y
           + (texture(iChannel1, vec2(t0.x, t3.y)).rgb * w0.x
            + texture(iChannel1, vec2(t12.x, t3.y)).rgb * w12.x
            + texture(iChannel1, vec2(t3.x, t3.y)).rgb * w3.x) * w3.y;
#endif
#if CR_CLAMP
    // Catmull-Rom overshoots at high-contrast edges, and 15 resamples in a row pile that up into
    // dark specks: keep the result inside the range of the 2x2 texels it sits between.
    ivec2 b = ivec2(floor(p - 0.5));
    vec3 c00 = texelFetch(iChannel1, b, 0).rgb, c10 = texelFetch(iChannel1, b + ivec2(1, 0), 0).rgb;
    vec3 c01 = texelFetch(iChannel1, b + ivec2(0, 1), 0).rgb, c11 = texelFetch(iChannel1, b + ivec2(1, 1), 0).rgb;
    return clamp(s, min(min(c00, c10), min(c01, c11)), max(max(c00, c10), max(c01, c11)));
#else
    return max(s, vec3(0.0));   // light stays >= 0
#endif
}

// Follow a depth guess into last frame twice (depth -> point -> pixel hp -> its depth): 2 = last
// frame saw that point there, 1 = it saw another depth, 0 = off screen.
int follow(float depth, vec3 ro, vec3 rd, vec3 pro, vec3 prt, vec3 pup, vec3 pfw, float tSea,
           out vec2 hp, out float dAt) {
    vec2 R = iResolution.xy;
    hp = vec2(0.0);
    dAt = depth;
    for (int i = 0; i < 2; i++) {
        vec3 d = ro + rd * dAt - pro;
        float z = dot(d, pfw);
        hp = FOCAL * vec2(dot(d, prt), dot(d, pup)) / max(z, 1e-4) * R.y + 0.5 * R;
        if (z <= 0.0 || hp.x < 0.5 || hp.y < 0.5 || hp.x > R.x - 0.5 || hp.y > R.y - 0.5) return 0;
        dAt = texelFetch(iChannel1, ivec2(hp), 0).a;
        if (dAt < 0.0) dAt = tSea;          // open sea there: the plane along this ray
    }
    float seen = length(ro + rd * dAt - pro);   // what last frame should have seen there
    return dAt >= 1e3 || abs(seen - dAt) <= REJECT * min(seen, dAt) ? 2 : 1;
}

// a sample's depth; an open-sea sample (.a < 0) lies on the sea plane along its pixel px's ray
float sDepth(float a, vec2 px, vec3 ro, vec3 rtb, vec3 upb, vec3 fw) {
    if (a >= 0.0) return a;
    vec2 uv = (px + 0.5 - 0.5 * iResolution.xy) / iResolution.y;
    vec3 d = normalize(uv.x * rtb + uv.y * upb + FOCAL * fw);
    return d.y < 0.0 ? (SEA_Y - ro.y) / d.y : 1e4;
}

// The fresh samples around h, Gaussian-weighted (NEAR_SIGMA px): nearly shift-invariant, so it
// does not jump when the lattice changes phase (a bilinear blend of samples 4 px apart draws
// flickering stairs at moving edges). lo / hi = the colour range of the samples within 6 px.
vec3 gaussFresh(ivec2 h, ivec2 ph, vec2 ares, out vec3 lo, out vec3 hi) {
    ivec2 a0 = ivec2(floor(vec2(h - ph) * 0.25));
    vec3 sum = vec3(0.0);
    float wsum = 0.0;
    lo = vec3(1e9);
    hi = vec3(-1e9);
    for (int j = -1; j <= 2; j++) {
        for (int i = -1; i <= 2; i++) {
            ivec2 a = a0 + ivec2(i, j);
            vec3 s = fresh(a, ares).rgb;
            vec2 d = vec2(4 * a + ph - h);
            float r2 = dot(d, d);
            float w = exp(-r2 / (2.0 * NEAR_SIGMA * NEAR_SIGMA));
            sum += s * w;
            wsum += w;
            if (r2 <= 36.0) {
                lo = min(lo, s);
                hi = max(hi, s);
            }
        }
    }
    return sum / wsum;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 R = iResolution.xy;
    vec2 ares = ceil(R * 0.25);
    ivec2 h = ivec2(fragCoord);
    ivec2 ph = tracePhase(iFrame);
    ivec2 q = h - ph;                      // position in this frame's trace lattice
    ivec2 a0 = ivec2(floor(vec2(q) * 0.25));
    vec4 s00 = fresh(a0, ares);
    bool isFresh = (q.x & 3) == 0 && (q.y & 3) == 0;   // traced this frame: s00 is its sample
    vec4 s10 = fresh(a0 + ivec2(1, 0), ares);
    vec4 s01 = fresh(a0 + ivec2(0, 1), ares);
    vec4 s11 = fresh(a0 + ivec2(1, 1), ares);
    vec3 ro, rtb, upb, fw;
    camLoad(iChannel2, 0, ro, rtb, upb, fw);
    vec2 uv = (fragCoord - 0.5 * R) / R.y;
    vec3 rd = normalize(uv.x * rtb + uv.y * upb + FOCAL * fw);
    float tSea = rd.y < 0.0 ? (SEA_Y - ro.y) / rd.y : 1e4;   // the sea plane's depth along this ray
    float d00 = sDepth(s00.a, vec2(4 * a0 + ph), ro, rtb, upb, fw);
    float d10 = sDepth(s10.a, vec2(4 * (a0 + ivec2(1, 0)) + ph), ro, rtb, upb, fw);
    float d01 = sDepth(s01.a, vec2(4 * (a0 + ivec2(0, 1)) + ph), ro, rtb, upb, fw);
    float d11 = sDepth(s11.a, vec2(4 * (a0 + ivec2(1, 1)) + ph), ro, rtb, upb, fw);
    float dNear = min(min(d00, d10), min(d01, d11));
    if (iFrame == 0) {                      // no history yet: the four fresh samples blended
        vec2 f = vec2(q - 4 * a0) * 0.25;
        fragColor = vec4(mix(mix(s00.rgb, s10.rgb, f.x), mix(s01.rgb, s11.rgb, f.x), f.y), dNear);
        return;
    }
    vec3 pro, prt, pup, pfw;
    camLoad(iChannel2, 1, pro, prt, pup, pfw);
    // Two depth guesses, the own last depth and the nearest fresh sample's: a cloud edge that
    // moved over the pixel is only in the second (the own depth still finds the background).
    vec2 hp, hp2;
    float depth, depth2;
    float dOwn = texelFetch(iChannel1, h, 0).a;
    if (dOwn < 0.0) dOwn = tSea;            // open sea last frame
    int st = follow(dOwn, ro, rd, pro, prt, pup, pfw, tSea, hp, depth);
#if SECOND_DEPTH
#if SECOND_DEPTH == 2
    // where the guesses agree both lead to the same pixel
    if (abs(dNear - dOwn) > REJECT * min(dNear, dOwn)) {
#endif
    int st2 = follow(dNear, ro, rd, pro, prt, pup, pfw, tSea, hp2, depth2);
    if (st2 > st || (st2 == 2 && depth2 < depth * (1.0 - REJECT))) {   // the nearer surface wins
        st = st2;
        hp = hp2;
        depth = depth2;
    }
#if SECOND_DEPTH == 2
    }
#endif
#endif
#if SEA
    // The open sea reprojects exactly (a plane), so it skips the TAA, which spread its glints to
    // ~3x3 px with a dark ring and smeared them along the flight: the fresh sample or last frame's
    // nearest texel keeps a glint one pixel. A cloud in front mixes the depth and keeps the TAA.
    if (rd.y < 0.0 && st == 2 && abs(depth - tSea) < 0.02 * tSea) {
        fragColor = isFresh ? s00 : texelFetch(iChannel1, ivec2(hp), 0);
        return;
    }
#endif
    // How near: the parallax against hInf, where this direction at infinity lands last frame.
    // A rejected history counts as near.
    float near = 1.0;
    vec3 hist = vec3(0.0);
    if (st > 0) {
        vec2 hInf = FOCAL * vec2(dot(rd, prt), dot(rd, pup)) / max(dot(rd, pfw), 1e-4) * R.y + 0.5 * R;
        float par = length(hp - hInf);
        if (st == 2) near = smoothstep(NEAR_PX0, max(NEAR_PX1, NEAR_PX0 + 0.01), par);   // the controls overlap: edges kept apart
#if EDGE_SOFT
        // Cloud edges in front of something farther: the fuzzy depth reprojects badly across the
        // silhouette and pops each time the pixel is fresh again. Treat them as near, only where
        // the point moves, so the far horizon stays sharp.
        float dMax = min(max(max(d00, d10), max(d01, d11)), 1e3);
        float edge = smoothstep(EDGE0, EDGE1, (dMax - dNear) / dNear) * smoothstep(0.1, 0.4, par);
        near = max(near, edge);
#endif
        hist = historyCR(hp);
    }
    if (near <= 0.0) {                      // far and consistent: full detail
        fragColor = isFresh ? s00 : vec4(hist, depth);
        return;
    }
    // Near, rejected or off screen: TAA on the Gaussian blend, the history clamped to the samples'
    // range (no streaks), NEAR_NEW of the blend per frame (averages the lattice's phase changes).
    vec3 lo, hi;
    vec3 g = gaussFresh(h, ph, ares, lo, hi);
    vec3 nearCol = st > 0 ? mix(clamp(hist, lo, hi), g, NEAR_NEW) : g;
    vec3 farCol = isFresh ? s00.rgb : hist;
    fragColor = vec4(mix(farCol, nearCol, near), st == 2 ? depth : (isFresh ? s00.a : dNear));
}//aladiN

// Buffer D -- the cloud-top map: copies and scrolls what Buffer A marched. iChannel0 = Buffer D, iChannel1 = Buffer A.
// Options: top of the Common tab.
// Two N x N windows side by side: x < N fine (MAP_S0 units a texel), N <= x < 2N coarse (MAP_S1).
// A texel: .x the highest cloud top over its world point or MAP_NONE, .y the same softened (shadows,
// mirror), .w the cover it was made with. Row N: texel 0 the windows' origins (world texel of slot 0:
// fine .xy, coarse .zw), 1 (N, bands still invalid), 2 (band to remake next, frames left, cover).
// The clouds stand still in the world, so the windows follow the camera by whole texels and each
// value moves with its world point. The march lives in Buffer A's work rows: here its unrun code cost
// 1.74 ms a frame (the Intel driver sizes a pass for its heaviest path), in Buffer B a second copy of
// the cloud field crashed the D3D link.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = vec4(0.0);
#if SEA
    ivec2 ip = ivec2(fragCoord);
    int n = mapN(iResolution.xy);
    if (ip.y > n || ip.x >= 2 * n) return;
    int bands = n / MAP_BAND;
    int wr = mapWorkRow(iResolution.xy);
    vec4 o = texelFetch(iChannel1, ivec2(0, wr + 8 + MAP_BAND), 0);   // this frame's origins (Buffer A)
    vec4 oOld = texelFetch(iChannel0, ivec2(0, n), 0);
    vec4 h1 = texelFetch(iChannel0, ivec2(1, n), 0);
    vec4 h2 = texelFetch(iChannel0, ivec2(2, n), 0);
    bool built = iFrame > 0 && h1.x == float(n);       // last frame's map is of this size
    ivec4 s4 = built ? ivec4(o - oOld) : ivec4(0);      // the windows' shift, texels
    bool jump = built && any(greaterThan(abs(s4), ivec4(2)));   // more than Buffer A's scroll-in strips hold
    bool rebuilding = built && h2.y > 0.0;              // Buffer A remade band h2.x this frame
    int bandNow = int(h2.x);
    gCover = texelFetch(iChannel1, TX_COVER, 0).x;
    if (ip.y == n) {                                    // the header
        if (ip.x == 0) fragColor = o;
        else if (ip.x == 1) {
            float bad = !built || jump ? float(bands) : max(h1.y - (rebuilding ? 1.0 : 0.0), 0.0);
            fragColor = vec4(float(n), bad, 0.0, 0.0);
        } else if (ip.x == 2) {
            float b = built ? h2.x : 0.0, left = built ? h2.y : 0.0;
            if (rebuilding) { b = mod(b + 1.0, float(bands)); left -= 1.0; }
            if (!built || jump) { b = 0.0; left = float(bands); }
            else if (gCover != h2.z) left = float(bands);   // a cover change: one more full cycle from here
            fragColor = vec4(b, left, gCover, 0.0);
        }
        return;
    }
    int c = ip.x >= n ? 1 : 0;                          // which window
    ivec2 slot = ip - ivec2(c * n, 0);
    ivec2 s = c == 0 ? s4.xy : s4.zw;
    ivec2 src = slot + s;                               // this world texel's slot last frame
    bool inOld = built && !jump && src.x >= 0 && src.y >= 0 && src.x < n && src.y < n;
    vec4 v = inOld ? texelFetch(iChannel0, src + ivec2(c * n, 0), 0) : vec4(MAP_NONE, MAP_NONE, 0.0, 0.0);
    bool fresh = false;
    if (built && !jump && !inOld) {                     // it scrolled in: Buffer A marched it this frame
        int kind = src.y < 0 || src.y >= n ? 0 : 1;     // a new row (corners too), else a new column
        int k = kind == 0 ? (s.y > 0 ? slot.y - (n - s.y) : slot.y) : (s.x > 0 ? slot.x - (n - s.x) : slot.x);
        v = texelFetch(iChannel1, ivec2(kind == 0 ? slot.x : slot.y, wr + 4 * c + 2 * kind + k), 0);
        fresh = true;
    }
    if (rebuilding && slot.y / MAP_BAND == bandNow) {   // Buffer A remade this band this frame
        v = texelFetch(iChannel1, ivec2(c * n + slot.x, wr + 8 + slot.y - bandNow * MAP_BAND), 0);
        fresh = true;
    }
    // .y = the tops softened by a 3 x 3 tent: cumulus edges thin out over 100 .. 300 m and the sun's
    // disc adds a penumbra, while a heap's side drops within one texel of .x. Taps 3 texels apart fine
    // (std 0.53 units), 2 coarse (1.4); remade with the texel and every 8th frame in its tile's turn.
    int tile = (slot.x >> 4) + 16 * (slot.y >> 4) + 256 * c;
    if (fresh || !inOld || ((tile * 3 + iFrame + 4) & 7) == 0) {
        int st = c == 0 ? 3 : 2;
        float soft = 0.0;
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                ivec2 q = clamp(src + st * ivec2(i, j), ivec2(0), ivec2(n - 1));
                float t = inOld && (i != 0 || j != 0) ? texelFetch(iChannel0, q + ivec2(c * n, 0), 0).x : v.x;
                soft += float((2 - abs(i)) * (2 - abs(j))) / 16.0 * t;
            }
        }
        v.y = soft;
    }
    fragColor = vec4(v.x, v.y, 0.0, v.w);
#endif
}//aladiN

