#define SUN_NIGHT -18.0    // where the sunrise starts, degrees (-18 = astronomical night), -18 .. 0
#define SUN_AZ -5.0        // the sun's azimuth from the flight's mean direction, degrees (- = left):
                           // -5 puts it ~15 deg left of the view during the sunrise, -60 .. 60
