// near clouds: calm vs crisp
#define NEAR_SIGMA 1.0     // near softness, px: the Gaussian that rebuilds near pixels from fresh samples, 1 .. 8
#define NEAR_LOD_K 0.0     // near motion blur (0 = full detail): the footprint x parallax px per frame, 0 .. 8
#define NEAR_PX0 2.0       // near starts at this parallax, px per frame, 0.1 .. 2
#define NEAR_PX1 5.065     // fully near from this parallax, px per frame, 0.5 .. 6
