                           // grazing views ~half the mean normal's; 0 = the mean normal's
#define SEA_WAVES 1        // swell and wind-sea trains; what the pixel cannot resolve widens Cox & Munk's slopes
#define SEA_SWELL 1.0      // swell from far storms, x 1.6 m / 0.9 m (two trains, 210 / 140 m long), 0 .. 3
#define SEA_SWELL_DIR 68.7549 // the swell's direction from the wind's, degrees, -180 .. 180
#define SEA_WINDSEA 0.36   // the wind waves' share of the slope variance (the rest is finer than a pixel), 0 .. 0.6
