#define T ( iTime*spEED )   // Buffer and Image code only: shadertoy.com compiles Common without uniforms

/// helpers
const float tau  = atan( 1. )*8.; // 2.*acos( -1. )
const float pi   = tau/2.;
const float tauq = tau/4.;

// Flight path: sums of sines with unrelated frequencies -- smooth in every derivative, never
// visibly repeating. Field surface: median 1.37, 99th percentile 3.61, highest seen 4.24; the
// altitude is ALT +- 0.8 but never lower than CLEAR above the clouds (Buffer A).
#define SPEED 1.2       // forward speed along +z
#define FOCAL 0.8       // wide-angle lens: ~64 degrees vertical, ~96 horizontal at 16:9
#define BANK_K 4.5      // bank (rad) per unit of lateral acceleration: up to ~24 degrees
const vec3 WEAVE_A = vec3(6.0, 3.0, 1.0);          // sideways weave: amplitudes...
const vec3 WEAVE_W = vec3(0.071, 0.113, 0.173);    // ...angular frequencies (rad/s)...
const vec3 WEAVE_P = vec3(0.0, 1.7, 4.1);          // ...and phases; heading up to ~38 degrees
const vec3 ALT_A = vec3(0.45, 0.25, 0.1);          // climbs and descents: ALT +- 0.8
const vec3 ALT_W = vec3(0.083, 0.137, 0.211);      // fast enough for visible dives
const vec3 ALT_P = vec3(2.3, 0.4, 3.3);

// Ground track and turn at a moment: xz, the heading's yaw, the bank of a coordinated turn
// (right turn = right wing down), the horizontal speed. The altitude lives in Buffer A.
vec2 pathXZ(float time) {
    vec3 aw = WEAVE_W * time + WEAVE_P;
    return vec2(dot(WEAVE_A, sin(aw)), SPEED * time);
}

void pathTurn(float time, out float yaw, out float bank, out float hv) {
    vec3 aw = WEAVE_W * time + WEAVE_P;
    float dx = dot(WEAVE_A * WEAVE_W, cos(aw));
    float ddx = -dot(WEAVE_A * WEAVE_W * WEAVE_W, sin(aw));
    hv = sqrt(SPEED * SPEED + dx * dx);
    yaw = atan(dx, SPEED);
    bank = BANK_K * ddx * SPEED / hv;
}

// The base path's turn rate (rad/s, d/dt of pathTurn's yaw; > 0 = right) and horizontal speed:
// what the autopilot flies around the current heading.
void pathRate(float time, out float om, out float hv) {
    vec3 aw = WEAVE_W * time + WEAVE_P;
    float dx = dot(WEAVE_A * WEAVE_W, cos(aw));
    float ddx = -dot(WEAVE_A * WEAVE_W * WEAVE_W, sin(aw));
    hv = sqrt(SPEED * SPEED + dx * dx);
    om = SPEED * ddx / (hv * hv);
}

// The bank for speed v and turn rate om: pathTurn's BANK_K x (v x om) as tan(bank), so a hard turn
// saturates below 90 deg. Deliberately gentle: a real g-load at the scene's 600 m/s needs ~80 deg.
float bankOf(float v, float om) {
    return atan(BANK_K * v * om);
}

// and back: the turn rate a bank gives at speed v
float turnOf(float v, float bank) {
    return tan(bank) / (BANK_K * max(v, 0.1));
}

// keys: JavaScript keyCodes of the Keyboard channel (the arrows work as well)
#define KEY_LEFT 65     // A: turn left
#define KEY_RIGHT 68    // D: turn right
#define KEY_UP 87       // W: climb
#define KEY_DOWN 83     // S: descend
#define KEY_FAST 16     // Shift: faster
#define ALT_MIN 2.8             // never below the base path's range: 3.6 - 0.8
#define ALT_MAX 6.67            // 6335 m over the sea, a blinking red bar "MAX ALTITUDE" there; higher, the
                                // trace's 120 units leave a dark band under the horizon
#define ROLL_EASE 1.5           // the roll slows over its last ROLL_EASE s x ROLL_RATE...
#define ROLL_ACC 0.8            // ...and its rate builds up and dies down within ~this (s): no jerk
#define PITCH_EASE 0.8          // the same for the W/S tilt (at 1.5 it climbed on 4 s after W)
#define SPEED_TAU 0.8           // the speed follows Shift within ~this

// The banked camera frame, orthonormal: a ray is normalize(uv.x * rtb + uv.y * upb + FOCAL * fw).
void cameraFrame(float yaw, float pitch, float bank, out vec3 rtb, out vec3 upb, out vec3 fw) {
    fw = vec3(sin(yaw) * cos(pitch), sin(pitch), cos(yaw) * cos(pitch));
    vec3 rt = vec3(cos(yaw), 0.0, -sin(yaw));
    vec3 up = cross(fw, rt);
    rtb = cos(bank) * rt - sin(bank) * up;
    upb = cos(bank) * up + sin(bank) * rt;
}

// State (Buffer A): row 0 = state, row 1 = the cloud tops ahead on the path.
#define STATE_STAMP (15.0 + 16.0 * floor(SUN_ELEV * 10.0 + 0.5))                  // bump with the texel map or the start settings
const ivec2 TX_LOOK = ivec2(0, 0);       // .xy mouse look offset (yaw, pitch), radians; .zw its return rate
const ivec2 TX_MOUSE = ivec2(1, 0);      // .x held last frame, .yz the mouse at the last held frame
const ivec2 TX_ALT = ivec2(2, 0);        // .x altitude, .y climb rate, .z the guard's smoothed level,
                                         // .w the max altitude warning (0 .. 1, the Image draws it)
const ivec2 TX_STAMP = ivec2(3, 0);
const ivec2 TX_CAM = ivec2(4, 0);        // 4..6 this frame's camera, 7..9 the last frame's
#define LOOK_N 10                        // cloud tops sampled ahead on the path...
#define LOOK_DT 0.35                     // ...this many seconds apart (3.15 s ahead)
#define CLEAR_MIN 0.6                    // hard floor above the top right under the camera
#define TGT_TAU 0.6                      // the altitude target is smoothed over ~this (no steps)
#define ALT_TAU 0.9                      // climbing follows the target within ~this many seconds...
#define DESCEND_TAU 3.0                  // ...descending more lazily (no jerky lift)
#define PILOT_TAU 0.35                   // the pilot's W/S altitude is smooth already: followed closely

// A camera from the state buffer: which 0 = this frame, 1 = the last frame. The sampler is a
// parameter -- Common must not name a channel (shadertoy.com compiles it alone).
void camLoad(sampler2D s, int which, out vec3 ro, out vec3 rtb, out vec3 upb, out vec3 fw) {
    ivec2 b = TX_CAM + ivec2(3 * which, 0);
    vec4 c0 = texelFetch(s, b, 0);
    vec4 c1 = texelFetch(s, b + ivec2(1, 0), 0);
    vec4 c2 = texelFetch(s, b + ivec2(2, 0), 0);
    ro = c0.xyz;
    rtb = vec3(c0.w, c1.xy);
    upb = vec3(c1.zw, c2.x);
    fw = c2.yzw;
}

// Which pixel of each 4x4 block Buffer B traces this frame, in 4x4 Bayer order (k & 3 the 2x2
// quadrant, k >> 2 the pixel in it): frames in a row land far apart, every pixel fresh every 16th.
ivec2 bayer2(int c) {
    return ivec2(c == 1 || c == 2 ? 1 : 0, c == 1 || c == 3 ? 1 : 0);
}
ivec2 tracePhase(int frame) {
    int k = frame & 15;
    return 2 * bayer2(k & 3) + bayer2(k >> 2);
}

// Interleaved gradient noise (Jorge Jimenez): the march's step jitter and dither.
float ign(vec2 p) {
    return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));
}

// ---------- the cloud field ----------

#define CELL 4.0
#define TOP 10.5
#define BASE -4.0
#define SIGMA 12.0      // extinction at full density
#define SOFT 0.55       // depth over which density fades in below the surface
#define AMB 0.8         // sky ambient scale
#define MS 0.25         // multiple-scattering scale
#define SUNK 2.2        // direct + scattered sun gain

#define AIRMASS 20.0    // air path to a sun ~1 deg above the horizon, in zenith air masses
// Sun colour after that path: Rayleigh-like optical depth per channel (~1/lambda^4).
const vec3 SUN_COL = 2.2 * exp(-vec3(0.04, 0.10, 0.23) * AIRMASS);   // ~ (1.0, 0.30, 0.02)
const vec3 SKY_AMB = vec3(0.25, 0.38, 0.85);   // blue sky light from above: lights the shadowed sides
const vec3 ABSORB = vec3(0.02, 0.12, 0.30);    // absorption per channel, as a fraction of SIGMA
#define MAX_OCT 3.0     // Worley lobe octaves (big/medium); fine detail comes from BUMP noise
float gCover = COVER;    // the cover in use: each pass sets it from Buffer A (the right bar)

#define BUMP 0.9        // fine billow lumps: surface push std ~0.12, 99th pct ~0.3 outward

// Cap height / cap radius per lobe octave (before the 0.6x island fade): soft big lobes,
// crisp medium ones, flat fine ones.
const float RELIEF[6] = float[6](1.0, 1.3, 1.0, 0.75, 0.6, 0.5);
// Inigo Quilez, https://iquilezles.org
const mat3 ROT = mat3(0.00, 0.80, 0.60, -0.80, 0.36, -0.48, -0.60, -0.48, 0.64);

const vec3 SUN = vec3(-0.75, 0.02, 1.0);    // ~1 deg above the horizon, ~37 deg left of view

// Float-only hash: survives mediump ints and FragCoord's GLSL->WGSL translation (which turns an
// unsigned hash into a constant). "Hash without Sine", Dave Hoskins, MIT, shadertoy.com/view/4djSRW
vec3 hash33(ivec3 c) {
    vec3 p = fract(vec3(c) * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yxz + 33.33);
    return fract((p.xxy + p.yxx) * p.zyx);
}

// Gradient (Perlin-style) noise, roughly [-1, 1], quintic fade.
float grad(ivec3 c, vec3 r) {
    return dot(hash33(c) * 2.0 - 1.0, r);
}

float gnoise(vec3 p) {
    ivec3 i = ivec3(floor(p));
    vec3 f = fract(p);
    vec3 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    return mix(mix(mix(grad(i, f), grad(i + ivec3(1, 0, 0), f - vec3(1.0, 0.0, 0.0)), u.x),
                   mix(grad(i + ivec3(0, 1, 0), f - vec3(0.0, 1.0, 0.0)), grad(i + ivec3(1, 1, 0), f - vec3(1.0, 1.0, 0.0)), u.x), u.y),
               mix(mix(grad(i + ivec3(0, 0, 1), f - vec3(0.0, 0.0, 1.0)), grad(i + ivec3(1, 0, 1), f - vec3(1.0, 0.0, 1.0)), u.x),
                   mix(grad(i + ivec3(0, 1, 1), f - vec3(0.0, 1.0, 1.0)), grad(i + ivec3(1, 1, 1), f - vec3(1.0, 1.0, 1.0)), u.x), u.y), u.z);
}

// Inigo Quilez, https://iquilezles.org
float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

float smax(float a, float b, float k) {
    return -smin(-a, -b, k);
}

// Worley F1^2, exact below 0.36 (all the caps use): points sit in [0.15, 0.85] of their cell, so
// only this cell and the nearer neighbour per axis can hold one within 0.6.
float worley2(vec3 p) {
    ivec3 i = ivec3(floor(p));
    vec3 f = fract(p);
    ivec3 n = ivec3(step(vec3(0.5), f)) * 2 - 1;   // vector edge: WGSL step() needs matching types
    float m = 9.0;
    for (int z = 0; z < 2; z++) {   // explicit braces: FragCoord's WGSL translation misplaces
        for (int y = 0; y < 2; y++) {   // the closing braces of brace-less nested loops
            for (int x = 0; x < 2; x++) {
                ivec3 o = ivec3(x, y, z) * n;
                vec3 r = vec3(o) + 0.15 + 0.7 * hash33(i + o) - f;
                m = min(m, dot(r, r));
            }
        }
    }
    return m;
}

// Coarse shape: one tower per jittered 2D cell, wide at the base and narrowing upward.
float heaps(vec3 p) {
    ivec2 cell = ivec2(floor(p.xz / CELL));
    float d = 1e3;   // no tower in the 3x3 block (the march has its own empty-space bound)
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            ivec3 c = ivec3(cell.x + i, 0, cell.y + j);
            vec3 h = hash33(c);
            // tops in 0..2; caps, lobes and bumps add < ~3, so everything stays below ~5
            if (h.z >= gCover) continue;
            vec3 g = hash33(c + ivec3(0, 1, 0));
            float r = CELL * (0.24 + 0.16 * g.x);
            float top = 2.0 * g.y;
            vec2 ctr = (vec2(c.xz) + 0.3 + 0.4 * h.xy) * CELL;
            vec3 q = p - vec3(ctr.x, 0.0, ctr.y);
            // wobbling heap from BASE to 'top': radius 0.65r at the rounded top, 1.85r three units
            // below it, so neighbours close into a deck
            float y = clamp(q.y, BASE, top);
            vec2 wob = vec2(sin(y * 0.7 + 6.28 * g.z), cos(y * 0.6 + 6.28 * h.x)) * 0.35 * r;
            float rad = r * (0.65 + 1.2 * smoothstep(top, top - 3.0, y));
            float tower = (length(q - vec3(wob.x, y, wob.y)) - rad) * 0.7;
            d = smin(d, tower, 0.2 * CELL);

        }
    }
    return d;
}

// Cauliflower lobes (at most 1.45 outward) on the tower distance d; lod = octaves, the last fading
// in (no pops). A cap shrinks with p's distance outside the surface: it grows out of it, no islands.
float lobes(vec3 p, float d, float lod) {
    vec3 q = p;
    float fr = 0.5;
    float fine = 0.35 + 0.65 * smoothstep(-5.0, 3.0, p.y);   // smoother, broader lower bodies
    for (int o = 0; o < 6; o++) {
        float wgt = clamp(lod - float(o), 0.0, 1.0);
        if (wgt <= 0.0) break;
        float x = max(1.0 - worley2(q * fr) / 0.36, 0.0);
        float h = 0.6 / fr * RELIEF[o] * (o == 0 ? 1.0 : fine) * wgt;
        d -= h * x / sqrt(x + 0.04) * clamp(1.0 - d / (1.5 * h), 0.0, 1.0);
        q = ROT * q + 3.1;
        fr *= 2.1;
    }
    return d;
}

// Billowed gradient noise for 'oct' octaves (last one fading in), first period ~0.33 units, as an
// outward surface push (n: mean 0.28, std 0.13, 99th pct 0.64). time = iTime (Common names no uniform).
float bumps(vec3 p, float oct, float time) {
    p = p * 3.0 + vec3(0.0, -0.1 * time, 0.0);
    float n = 0.0, a = 1.0;
    for (int o = 0; o < 4; o++) {
        float w = clamp(oct - float(o), 0.0, 1.0);
        if (w <= 0.0) break;
        n += a * w * abs(gnoise(p));
        p = ROT * p * 2.03;
        a *= 0.5;
    }
    return BUMP * (n - 0.28);
}


// The cloud surface at full detail, < 0 inside: Buffer A's altitude must never enter a cloud.
float cloudField(vec3 p, float time) {
    float d = heaps(p);
    if (d > 2.0) return d - 1.9;
    d = lobes(p, d, MAX_OCT);
    if (d < 1.5) d -= bumps(p, 4.0, time);
    return d;
}

// Height of the highest cloud surface over xz, marched down from above the tallest possible top
// (~6.9) by 0.4 x the distance, at least 0.02; out of steps it answers the last height (never too low).
float cloudTop(vec2 xz, float time) {
    float y = 9.0;
    for (int i = 0; i < 96; i++) {
        float d = cloudField(vec3(xz.x, y, xz.y), time);
        if (d < 0.0) return y;
        y -= max(0.4 * d, 0.02);
        if (y < BASE) return BASE;
    }
    return y;
}

// ---------- real colours: a single-scattering atmosphere ----------
// Rayleigh, Mie and ozone over a spherical Earth, in km (Bruneton & Neyret 2008, Hillaire 2020), with
// linear-sRGB coefficients fitted to a spectral computation (single wavelengths made the low sun too
// red). Relative to the sun's irradiance above the air (1). Radiances x pi (RAD_K): a white diffuse
// surface lit by the sun shows the sun's value, as the sunlit tops do; x 4 pi was 4 x too bright.
#define RAD_K pi
#define R_EARTH 6360.0
#define R_ATMO 6420.0
#define H_R 8.0                                        // Rayleigh scale height, km
#define H_M 1.2                                        // Mie scale height, km
const vec3 BETA_R = vec3(7.006e-3, 14.395e-3, 33.377e-3);   // Rayleigh per km at sea level
#define BETA_M 3.996e-3                                // Mie scattering at sea level, x TURBIDITY
#define MIE_EXT 1.11                                   // Mie extinction / scattering
#define MIE_G 0.76
const vec3 BETA_O = vec3(2.624e-3, 1.638e-3, 0.0);           // ozone absorption per km at its peak

// Densities at height h (km above the surface): Rayleigh, Mie, ozone (a tent around 25 km).
vec3 atmoDensity(float h) {
    h = max(h, 0.0);   // below the surface counts as at it: psi_ms's bottom row ran through the Earth
                       // (exp(+6000)), NaN in the haze over the clouds
    return vec3(exp(-h / H_R), exp(-h / H_M), max(0.0, 1.0 - abs(h - 25.0) / 15.0));
}

vec3 atmoExt(vec3 dens) {
    return BETA_R * dens.x + BETA_M * TURBIDITY * MIE_EXT * dens.y + BETA_O * dens.z;
}

// Ray (o, d) against the sphere of radius r around the Earth's centre: the far hit, or the
// near hit ahead (-1 when there is none).
float sphereFar(vec3 o, vec3 d, float r) {
    float b = dot(o, d), h = b * b - dot(o, o) + r * r;
    return h < 0.0 ? -1.0 : -b + sqrt(h);
}

float sphereNear(vec3 o, vec3 d, float r) {
    float b = dot(o, d), h = b * b - dot(o, o) + r * r;
    if (h < 0.0) return -1.0;
    float t = -b - sqrt(h);
    return t > 0.0 ? t : -1.0;
}

// Sunlight left at o (km from the Earth's centre), 0 behind the Earth (its shadow); 8 samples.
vec3 atmoTrans(vec3 o, vec3 L) {
    if (sphereNear(o, L, R_EARTH) > 0.0) return vec3(0.0);
    float len = sphereFar(o, L, R_ATMO);
    vec3 od = vec3(0.0);
    float prev = 0.0;
    for (int i = 0; i < 8; i++) {
        float t1 = len * (float(i) + 1.0) * (float(i) + 1.0) / 64.0;
        float tm = 0.5 * (prev + t1);
        od += atmoExt(atmoDensity(length(o + L * tm) - R_EARTH)) * (t1 - prev);
        prev = t1;
    }
    return exp(-od);
}

// ---------- multiple scattering in the sky (Hillaire 2020) and the setting sun ----------
// Single scattering leaves the twilight sky in the Earth's shadow black and the low sky too dark.
// psi_ms: second order from 64 directions, higher orders as L2 / (1 - f_ms), isotropic; it depends
// only on height and the sun's zenith cosine, so it is a 32 x 32 table in Buffer A (rows MS_ROW ..),
// remade when TURBIDITY changes.
#define MS_N 32
#define MS_ROW 4
#define SUN_RAD 0.004654                 // the sun's angular radius, radians (0.2666 deg)

// psi_ms at height h (km) for the sun's zenith cosine mus; zero = 0 from the pass (min(iFrame, 0)):
// the loops stay loops (fxc would unroll 64 x 20 bodies)
vec3 msTable(float h, float mus, int zero) {
    vec3 o = vec3(0.0, R_EARTH + max(h, 0.01), 0.0);   // just above the surface: rays down hit it
    vec3 L = vec3(sqrt(max(1.0 - mus * mus, 0.0)), mus, 0.0);
    vec3 l2 = vec3(0.0), fms = vec3(0.0);
    for (int k = zero; k < 64; k++) {
        float z = 1.0 - 2.0 * (float(k) + 0.5) / 64.0, r = sqrt(max(1.0 - z * z, 0.0));
        float a = 2.39996323 * (float(k) + 0.5);                    // golden angle: a Fibonacci sphere
        vec3 d = vec3(r * cos(a), z, r * sin(a));
        float tg = sphereNear(o, d, R_EARTH);
        float len = tg > 0.0 ? tg : sphereFar(o, d, R_ATMO);
        vec3 od = vec3(0.0);
        float prev = 0.0;
        for (int s = zero; s < 20; s++) {
            float t1 = len * (float(s) + 1.0) * (float(s) + 1.0) / 400.0;
            float ds = t1 - prev, tm = 0.5 * (prev + t1);
            prev = t1;
            vec3 p = o + d * tm;
            vec3 dens = atmoDensity(length(p) - R_EARTH);
            vec3 ext = atmoExt(dens);
            vec3 tv = exp(-(od + 0.5 * ext * ds));
            od += ext * ds;
            vec3 sc = BETA_R * dens.x + BETA_M * TURBIDITY * dens.y;
            l2 += tv * sc * atmoTrans(p, L) * ds / (4.0 * pi);   // isotropic phase
            fms += tv * sc * ds;
        }
        if (tg > 0.0) {                                               // the sea reflects what reaches it
            vec3 g = o + d * tg;
            l2 += exp(-od) * atmoTrans(g, L) * max(dot(normalize(g), L), 0.0) * 0.06 / pi;
        }
    }
    return (l2 / 64.0) / (1.0 - fms / 64.0);
}

// psi_ms from the table (bilinear between its texel centres)
vec3 msPsi(sampler2D s, float h, float mus) {
    vec2 q = vec2(clamp(mus * 0.5 + 0.5, 0.0, 1.0), clamp(h / (R_ATMO - R_EARTH), 0.0, 1.0)) * float(MS_N - 1);
    return textureLod(s, (q + vec2(0.5, float(MS_ROW) + 0.5)) / vec2(textureSize(s, 0)), 0.0).rgb;
}

// The sunlight at the eye as the disc sets behind the limb (acos(R / (R + h)) below the horizontal):
// the disc's share above it (a circle segment) x the light along the lowest clear ray. No refraction.
vec3 sunAtEye(vec3 L) {
    vec3 eye = vec3(0.0, R_EARTH + CAM_KM, 0.0);
    float dip = acos(R_EARTH / (R_EARTH + CAM_KM));
    float e = asin(clamp(L.y, -1.0, 1.0));
    float x = clamp((e + dip) / SUN_RAD, -1.0, 1.0);                 // the disc's centre above the limb, in radii
    float f = 1.0 - (acos(x) - x * sqrt(1.0 - x * x)) / pi;
    float eg = max(e, 0.0005 - dip);
    vec2 hz = normalize(L.xz + 1e-9);
    return atmoTrans(eye, vec3(hz.x * cos(eg), sin(eg), hz.y * cos(eg))) * f;
}

// Sky radiance toward rd for an eye CAM_KM up: single scattering plus psi_ms (msT = Buffer A), 16
// samples to the ground or to space; the sea below (albedo 0.06) reflects the light that reaches it.
vec3 atmoSky(vec3 rd, vec3 L, sampler2D msT) {
    vec3 o = vec3(0.0, R_EARTH + CAM_KM, 0.0);
    float tg = sphereNear(o, rd, R_EARTH);
    float len = tg > 0.0 ? tg : sphereFar(o, rd, R_ATMO);
    float mu = dot(rd, L);
    float pR = 3.0 / (16.0 * pi) * (1.0 + mu * mu);
    float pM = (1.0 - MIE_G * MIE_G) / (4.0 * pi * pow(1.0 + MIE_G * MIE_G - 2.0 * MIE_G * mu, 1.5));
    vec3 sum = vec3(0.0), od = vec3(0.0);
    float prev = 0.0;
    for (int i = 0; i < 16; i++) {
        float t1 = len * (float(i) + 1.0) * (float(i) + 1.0) / 256.0;
        float ds = t1 - prev, tm = 0.5 * (prev + t1);
        prev = t1;
        vec3 p = o + rd * tm;
        vec3 dens = atmoDensity(length(p) - R_EARTH);
        vec3 ext = atmoExt(dens);
        vec3 tv = exp(-(od + 0.5 * ext * ds));
        od += ext * ds;
        vec3 sc = BETA_R * dens.x + BETA_M * TURBIDITY * dens.y;
        sum += tv * (atmoTrans(p, L) * (BETA_R * dens.x * pR + BETA_M * TURBIDITY * dens.y * pM)
                   + msPsi(msT, length(p) - R_EARTH, dot(normalize(p), L)) * sc) * ds;
    }
    if (tg > 0.0) {
        vec3 g = o + rd * tg;
        sum += exp(-od) * atmoTrans(g, L) * max(dot(normalize(g), L), 0.0) * 0.06 / pi;
    }
    return sum;
}

// The light the state (Buffer A) keeps for the trace and the Image: row 0, texels 10..12.
const ivec2 TX_LIGHT = ivec2(10, 0);   // +0 .rgb sun on the clouds, .a scale k; +1 .rgb sky
                                       // ambient, .a TURBIDITY it was made with; +2 .rgb white point
const ivec2 TX_SUN = ivec2(13, 0);     // .x the sun's transmittance through the clouds (the
                                       // segments of last frame): the Image's sun disc and glare
const ivec2 TX_SEG = ivec2(14, 0);     // 14 .. 77: the optical depth of the sun ray's segments
#define SUN_SEGS 64

// Optical depth of segment i of the sun ray through the trace's clouds, one Buffer A texel each (the
// whole ray in one texel cost 12 .. 40 ms). Loop shaped like cloudTop's (exits by return, no continue /
// break, no conditions in its head): otherwise linking Buffer A crashed the D3D driver on shadertoy.com.
float sunSegment(vec3 o, vec3 L, int i, float time) {
    float t = 120.0 / float(SUN_SEGS) * float(i), t1 = t + 120.0 / float(SUN_SEGS);
    float od = 0.0;
    for (int k = 0; k < 32; k++) {
        vec3 p = o + L * t;
        float d = cloudField(p, time);
        float dt = min((0.03 + 0.003 * t) * STEP_K, t1 - t);
        od += SIGMA * smoothstep(0.0, SOFT, -d) * dt;   // 0 outside the cloud
        t += d > 0.0 ? max(0.5 * d, dt) : dt;
        if (t >= t1 || od > 7.0 || p.y > TOP) return od;
    }
    return od;
}

float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

// ---------- the sun bar and the sun's direction ----------
const ivec2 TX_ELEV = ivec2(0, 2);   // .x the sun's elevation (degrees), .yzw its direction: set by the bar
const ivec2 TX_REF = ivec2(1, 2);    // the light at SUN_REF: .x the scene's mean luminance, .y the reference
                                     // sun scale k, .z the sky irradiance's luma, .w REF_KEY
#define BAR_ROW 3                    // Buffer A row 3, x < 256: the bar's colours (display sRGB)
// the settings the kept light depends on (a change remakes it); the adapt/night ones hashed into 1/1024 steps
#define REF_KEY (TURBIDITY * 1000.0 + CAM_KM * 10.0 + floor(fract(sin(dot(vec4(EYE_ADAPT, NIGHT_ADAPT, TWI_SLOPE, NIGHT_SKY * 1e9), vec4(12.9898, 78.233, 37.719, 4.581))) * 43758.5453) * 1023.0) / 1024.0)
#define SUN_REF degrees(asin(normalize(SUN).y))   // the reference sun (0.92 deg): the light balance's anchor

// the sun's horizontal direction (x, z) at azimuth SUN_AZ, and the sun at elevation e (degrees)
vec2 sunH() { return vec2(sin(radians(SUN_AZ)), cos(radians(SUN_AZ))); }
vec3 sunDir(float e) {
    vec2 h = sunH();
    float r = radians(e);
    return vec3(h.x * cos(r), sin(r), h.y * cos(r));
}

// The bar: SUN_MIN to SUN_MAX across the lower middle, sizes as shares of the frame, the 5x7 label in
// whole font pixels. Elevation runs with the square of the position: the low sun gets half the bar.
float uiScale(vec2 res) { return max(1.0, floor(res.y / 225.0)); }   // screen px per font px
vec4 barRect(vec2 res) {                                             // the strip: x0, y0, x1, y1 (px)
    float y0 = 0.035 * res.y;
    return vec4(0.22 * res.x, y0, 0.78 * res.x, y0 + 0.022 * res.y);
}
bool onBar(vec2 p, vec2 res) {                                       // where a press works the bar
#if SHOW_BAR
    vec4 b = barRect(res);
    float m = b.w - b.y;
    return p.y >= 0.0 && p.y < b.w + m + 12.0 * uiScale(res) && p.x > b.x - m && p.x < b.z + m;
#else
    return false;
#endif
}
float barPos(float x, vec2 res) { vec4 b = barRect(res); return clamp((x - b.x) / (b.z - b.x), 0.0, 1.0); }
float barElev(float s) { return SUN_MIN + (SUN_MAX - SUN_MIN) * s * s; }
float barS(float e) { return sqrt(clamp((e - SUN_MIN) / (SUN_MAX - SUN_MIN), 0.0, 1.0)); }
// the sunrise's elevation at time t (s): SUN_NIGHT to SUN_ELEV, eased
float sunRise(float t) { return SUN_RISE > 0.0 ? mix(SUN_NIGHT, SUN_ELEV, smoothstep(0.0, SUN_RISE, t)) : SUN_ELEV; }

// ---------- the cloud cover bar (right), the sky-view table, the sea ----------
// Less cover is faster (0.45: -11 %, 0.25: -29 %).
const ivec2 TX_COVER = ivec2(2, 2);  // .x the cloud cover (share of cells with a heap): set by the right bar;
                                     // .y the sun bar's target elevation (TX_ELEV glides after it, SUN_TAU)
const ivec2 TX_REFSKY = ivec2(3, 2); // x 3 .. 26: the sky's radiance in the 24 irradiance directions under SUN_REF
const ivec2 TX_FLY = ivec2(27, 2);   // .xy the camera over the ground (xz), .z the heading (yaw), .w the bank (rad)
const ivec2 TX_FLY2 = ivec2(28, 2);  // .x the speed, .y the altitude the pilot set (the autopilot climbs around it),
                                     // .z seconds since the last key, .w the roll rate (rad/s)
const ivec2 TX_FLY3 = ivec2(29, 2);  // .x the flight path's angle by W/S (rad), .y its rate (rad/s),
                                     // .zw the heading limit's red glow, left / right side (0 .. 1; the Image draws it)
#define FLY_N 3                      // texels after TX_REFSKY's 24
#define COVER_MIN 0.33   // the right bar's lowest cover
#define COVER_MAX 0.95

// The right bar, vertical: x0, y0, x1, y1 (px). A press on it (or on its label, left of it)
// sets the cover from iMouse.y while held.
vec4 coverRect(vec2 res) {
    float x1 = res.x - 0.035 * res.y;
    return vec4(x1 - 0.022 * res.y, 0.22 * res.y, x1, 0.78 * res.y);
}
bool onCoverBar(vec2 p, vec2 res) {
#if SHOW_BAR
    vec4 b = coverRect(res);
    float m = b.z - b.x;
    return p.x > b.x - m - 30.0 * uiScale(res) && p.x <= res.x && p.y > b.y - m && p.y < b.w + m;
#else
    return false;
#endif
}
float coverPos(float y, vec2 res) { vec4 b = coverRect(res); return clamp((y - b.y) / (b.w - b.y), 0.0, 1.0); }
float coverOf(float s) { return mix(COVER_MIN, COVER_MAX, s); }
float coverS(float c) { return clamp((c - COVER_MIN) / (COVER_MAX - COVER_MIN), 0.0, 1.0); }

// The 24 directions the sky's irradiance is summed over (4 elevation bands x 6 azimuths), and
// their weights (sin el cos el d_el d_az: a horizontal surface).
vec3 irrDir(int k) {
    float el = (float(k / 6) + 0.5) * 0.39269908, az = (float(k - 6 * (k / 6)) + 0.5) * 1.04719755;
    return vec3(cos(el) * sin(az), sin(el), cos(el) * cos(az));
}
float irrW(int k) {
    float el = (float(k / 6) + 0.5) * 0.39269908;
    return sin(el) * cos(el) * 0.39269908 * 1.04719755;
}

// The sky-view table (Hillaire 2020), Buffer A rows SKY_ROW ..: x = azimuth from the sun (0 .. 180
// deg), y = elevation, squeezed toward the eye's horizon (sqrt). Remade only while the sun moves.
#define SKY_ROW 36
#define SKY_NU 32
#define SKY_NV 64
vec3 skyDir(vec2 uv, vec3 L) {
    float hz = -acos(R_EARTH / (R_EARTH + CAM_KM));
    float v = uv.y * 2.0 - 1.0;
    float el = v >= 0.0 ? hz + v * v * (0.5 * pi - hz) : hz - v * v * (0.5 * pi + hz);
    float az = uv.x * pi;
    vec2 s = normalize(L.xz + 1e-9);
    vec2 h = vec2(s.x * cos(az) - s.y * sin(az), s.x * sin(az) + s.y * cos(az));
    return vec3(h.x * cos(el), sin(el), h.y * cos(el));
}
vec3 skyLut(sampler2D s, vec3 rd, vec3 L) {
    float hz = -acos(R_EARTH / (R_EARTH + CAM_KM));
    float el = asin(clamp(rd.y, -1.0, 1.0));
    float v = el >= hz ? sqrt((el - hz) / (0.5 * pi - hz)) : -sqrt((hz - el) / (0.5 * pi + hz));
    float az = acos(clamp(dot(normalize(rd.xz + 1e-9), normalize(L.xz + 1e-9)), -1.0, 1.0));
    vec2 q = clamp(vec2(az / pi * float(SKY_NU), (v * 0.5 + 0.5) * float(SKY_NV)),
                   vec2(0.5), vec2(float(SKY_NU), float(SKY_NV)) - 0.5);
    return textureLod(s, (q + vec2(0.0, float(SKY_ROW))) / vec2(textureSize(s, 0)), 0.0).rgb;
}

// The airlight a hazed cloud or the sea fades to: the table, with its step at the eye's horizon (the
// sky above, the air in front of the dark ground below) eased over 2 deg below it -- the far clouds
// straddle that elevation, and the step drew a line through them.
vec3 skyAir(sampler2D s, vec3 rd, vec3 L) {
    float hz = -acos(R_EARTH / (R_EARTH + CAM_KM));
    float e = asin(clamp(rd.y, -1.0, 1.0));
    vec3 c = skyLut(s, rd, L);
    if (e >= hz) return c;
    vec2 h = normalize(rd.xz + 1e-9);
    float eu = hz + 0.002;
    vec3 up = skyLut(s, vec3(h.x * cos(eu), sin(eu), h.y * cos(eu)), L);
    return mix(up, c, smoothstep(0.0, radians(2.0), hz - e));
}

// The clouds' airlight: the table without its horizon -- below the eye's horizon the sky just above it,
// so no cloud ever shows the step between the sky and the air in front of the ground.
vec3 skyCloudAir(sampler2D s, vec3 rd, vec3 L) {
    float hz = -acos(R_EARTH / (R_EARTH + CAM_KM)) + 0.002;
    float e = asin(clamp(rd.y, -1.0, 1.0));
    if (e >= hz) return skyLut(s, rd, L);
    vec2 h = normalize(rd.xz + 1e-9);
    return skyLut(s, vec3(h.x * cos(hz), sin(hz), h.y * cos(hz)), L);
}

// ---------- the night sky ----------
// The single-scattering sky is unreliable below -6 deg (all of it in the Earth's shadow by ~-7.8):
// there it keeps -6 deg's shape and dims by TWI_SLOPE decades per degree. The night's floor is
// airglow at ~90 km, brighter toward the horizon (van Rhijn, capped at 3), dim below the eye's horizon.
#define TWI_E0 -6.0
float twiElev(float e) { return max(e, TWI_E0); }                       // the elevation the model is run at
float twiDim(float e) { return pow(10.0, TWI_SLOPE * min(e - TWI_E0, 0.0)); }
vec3 nightGlow(vec3 d) {
    float c = clamp(1.0 - d.y * d.y, 0.0, 1.0);                       // cos^2 of the elevation
    float f = d.y >= 0.0 ? min(1.0 / sqrt(max(1.0 - 0.9724 * c, 1e-3)), 3.0) : 0.3;
    return NIGHT_SKY * f * vec3(0.82, 1.03, 1.12);                     // luma 1: airglow's green + red, the sky's blue
}

// The sea's surface is the SEA MODULE at the end of this tab. The sun through the cloud layer above
// a sea point before the cloud-top map exists: three coarse samples of the heaps (no lobes, no bumps).
float seaShadow(vec3 p, vec3 L) {
    float s = 1.0;
    for (int i = 0; i < 3; i++) {
        float y = mix(BASE, 2.0, (float(i) + 0.5) / 3.0);   // the heaps' bodies, below their tops
        s *= smoothstep(-0.5, 0.5, heaps(p + L * ((y - p.y) / max(L.y, 0.01))));
    }
    return s;
}

// ---------- the cloud-top map (Buffer D) ----------
// The clouds stand still in the world, so the highest cloud surface per texel is made once and
// carried along; a texel is remade only when it scrolls in or the cover changes. Two windows side by
// side, fine and coarse. A ray at height y is in a cloud where the column's top is above y; the map
// does not depend on the sun, so the sun bar needs no remake.
#define MAP_S0 0.25          // fine window: units per texel
#define MAP_S1 1.0           // coarse window
#define MAP_AHEAD0 16.0      // the windows' centres ahead of the camera along its heading
#define MAP_AHEAD1 64.0
#define MAP_TOPMAX 4.9       // no surface the map holds reaches higher (tower 2 + cap 0.65 r + lobes 1.45 + lumps 0.3)
#define MAP_NONE (BASE - 0.5)   // the top of a column without cloud

int mapN(vec2 res) { return int(min(256.0, min(floor(res.x * 0.5), floor(res.y) - 1.0))); }   // texels per side
#define MAP_BAND 8           // rows of both windows Buffer A remakes a frame while the map is remade
// Buffer A's work rows for the map, above the sky table (x < 2N): 4 x window (new rows / columns),
// MAP_BAND band rows, then the window origins. Marched at Buffer A's one cloudTop call site: a march
// in Buffer D cost 1.74 ms as unrun code, one in Buffer B crashed the D3D link on ANGLE.
int mapWorkRow(vec2 res) { return SKY_ROW + SKY_NV; }

// A window's slot 0 as a world texel index: its centre ahead along the unit xz heading hd, N/2 back.
vec2 mapOrigin(vec2 camXZ, vec2 hd, float s, float ahead, int n) {
    return floor((camXZ + hd * ahead) / s) - float(n / 2);
}

// The softened column top over xz (Buffer D's .y): the fine window, blended into the coarse one over
// its last 8 texels; -99 outside both. hdr = the windows' origins (texel (0, n)), sz = Buffer D's size.
float mapTop(sampler2D m, vec2 xz, vec4 hdr, float n, vec2 sz) {
    vec2 q0 = xz / MAP_S0 - hdr.xy - 0.5;           // slot coordinates: an integer = a texel's centre
    float w = clamp((min(min(q0.x, q0.y), min(n - 1.0 - q0.x, n - 1.0 - q0.y)) - 3.0) / 8.0, 0.0, 1.0);
    float top0 = 0.0;
    if (w > 0.0) top0 = textureLod(m, (q0 + 0.5) / sz, 0.0).y;
    if (w >= 1.0) return top0;
    vec2 q1 = xz / MAP_S1 - hdr.zw - 0.5;
    if (min(q1.x, q1.y) < 1.5 || max(q1.x, q1.y) > n - 2.5) return -99.0;
    return mix(textureLod(m, (q1 + vec2(n, 0.0) + 0.5) / sz, 0.0).y, top0, w);
}

// Transmittance of the cloud layer from the sea point s along dir (up): 24 samples BASE ..
// MAP_TOPMAX, dense near the base, with an edge ramp that widens by soft x the way (the sun's disc,
// the waves' scatter); past the map two heap samples. Loop shaped like sunSegment's (plain head, exits by return).
float colTrans(sampler2D m, vec3 s, vec3 dir, vec4 hdr, float n, vec2 sz, float soft) {
    float u0 = (BASE - s.y) / dir.y, du = (MAP_TOPMAX - BASE) / dir.y;
    float od = 0.0;
    for (int k = 0; k < 24; k++) {
        float x = (float(k) + 0.5) / 24.0;
        float u = u0 + du * x * x;
        vec3 p = s + dir * u;
        float top = mapTop(m, p.xz, hdr, n, sz);
        if (top < -90.0) {                          // beyond the map: the rest from the heaps
            float r = 1.0;
            for (int i = 0; i < 2; i++) {
                float y = mix(p.y, max(p.y, 2.0), (float(i) + 0.5) / 2.0);
                r *= smoothstep(-0.5, 0.5, heaps(p + dir * ((y - p.y) / dir.y)));
            }
            return exp(-od) * (p.y > 2.0 ? 1.0 : r);
        }
        // at most 0.6 more: a grazing mirror ray runs 100 units through the layer, and a wide edge
        // counted every column under it as half a cloud (the far sea mirrored a flat grey)
        float w = 0.15 + min(soft * u, 0.6);
        // a column barely above the base is a thin fringe that lets light through; SEA_SHADOW_SIGMA, not
        // the trace's SIGMA 12: a column holds the cloud's whole thickness, at 12 every edge was hard
        od += SEA_SHADOW_SIGMA * smoothstep(-w, w, top - p.y) * smoothstep(0.0, 1.0, top - BASE) * du * 2.0 * x / 24.0;   // ds = du d(x^2)
        if (od > 6.0) return exp(-od);
    }
    return exp(-od);
}

// ===== SEA MODULE begin ==========================================================================
// The sea's surface, self-contained so it can be lifted out and put back as one block.
// Needs from outside: the SEA_* options, SEA_Y, UNIT_KM, RAD_K, hash33, gnoise.
// Interface (keep it): seaSurface(sp, rd, D, rtb, upb, roY, resY, time) -> Sea;
// seaShade(sea, mirSky, rd, L, sunC, skyA, sh, tr, points, time) -> the water's light, where the
// caller gives mirSky = the sky's radiance along sea.rr, sh = the sun's transmittance through the
// clouds, tr = the mirror ray's (1 = open sky), points = the glitter's share drawn as points.
// From kilometres up the sea is the statistics of its slopes (Cox & Munk 1954): the sky in the mirror
// (Fresnel, n = 1.33), the sun's glitter, the water's own dark blue-green (0.4 / 1.2 / 2.2 %).
#define SEA_COL vec3(0.004, 0.012, 0.022)
float seaFresnel(float c) { return 0.02 + 0.98 * pow(1.0 - clamp(c, 0.0, 1.0), 5.0); }
// The Fresnel averaged over the visible facets of slopes with std s along the view (the sky's mirror
// and the water's 1 - F, as in Bruneton, Neyret & Holzschuch 2010): fitted to a Monte Carlo of Gaussian
// slopes, s 0.03 .. 0.25, within 0.03 (research sea-lab/mean_fresnel_mc.py, F58). At 5 deg below the
// level and 7 m/s: 0.35, the mean normal's 0.64.
float seaFresnelAvg(float c, float s) {
    return 0.02 + 0.98 * pow(1.0 - clamp(c, 0.0, 1.0), 5.0 * exp(-3.56 * s)) / (1.0 + 23.5 * pow(s, 1.5));
}

// ---------- the sea's surface ----------
// LEAN mapping (Olano & Baker 2010) for the sea, as in Bruneton, Neyret & Holzschuch 2010: a few wave
// trains give the slopes the pixel resolves, the rest of the variance widens Cox & Munk's: no aliasing.
#define SEA_G 9.81
#define WIND_AZ radians(SEA_WIND_DIR)                // the wind blows toward this azimuth (from +z toward +x)

// Cox & Munk (1954) slope variances along / across the wind u (m/s), clean and slick mixed by sl.
vec2 coxMunk(float u, float sl) {
    return mix(vec2(3.16e-3 * u, 0.003 + 1.92e-3 * u), vec2(0.005 + 0.78e-3 * u, 0.003 + 0.84e-3 * u), sl);
}

// One wave train: wavelength lam (m), azimuth az from the wind, slope amplitude s = a k. Adds the
// filtered mean slope to mu, the variance averaged away to sig, the whole variance to sigT (taken out
// of Cox & Munk's). cf = the footprint's covariance (m^2), x = the point (m, wind frame), t = s.
void waveTrain(float lam, float az, float s, float ph, vec2 x, float t, mat2 cf,
               inout vec2 mu, inout mat2 sig, inout mat2 sigT) {
    float k = tau / lam;
    vec2 d = vec2(cos(az), sin(az));                 // wind frame: x along, y across the wind
    float g = exp(-0.5 * k * k * dot(d, cf * d));    // the footprint's Gaussian filter of this train
    mu += g * s * cos(k * dot(d, x) - sqrt(SEA_G * k) * t + ph) * d;
    mat2 dd = 0.5 * s * s * mat2(d.x * d.x, d.x * d.y, d.x * d.y, d.y * d.y);
    sig += (1.0 - g * g) * dd;
    sigT += dd;
}

// Smith's Lambda for Gaussian slopes (Walter et al. 2007's rational fit): how much the waves in front
// hide toward w (away from the sea, wind frame); S = the slopes' covariance.
float seaLambda(vec3 w, mat2 S) {
    float a2 = max(dot(w.xz, w.xz), 1e-12);
    float s2 = dot(w.xz, S * w.xz) / a2;             // slope variance along w's azimuth
    float nu = max(w.y, 1e-4) / sqrt(2.0 * s2 * a2); // cot(theta) / (sqrt(2) sigma)
    return nu < 1.6 ? (1.0 - 1.259 * nu + 0.396 * nu * nu) / (3.535 * nu + 2.181 * nu * nu) : 0.0;
}

// The sun's glitter per unit of its irradiance: slope Gaussian (mu, S, wind frame) x Fresnel /
// (4 cos view cos^4 tilt), x Smith's masking 1 / (1 + Lambda(eye) + Lambda(sun)) as in Bruneton et
// al. 2010 -- without it 1 / cos view grows without bound and the glitter burns white at the horizon.
float seaGlitter(vec3 rd, vec3 L, vec2 mu, mat2 S) {
    vec3 h = normalize(L - rd);                      // the facet normal that mirrors the sun to the eye
    float c = max(h.y, 1e-3);
    vec2 e = -h.xz / c - mu;
    float det = S[0][0] * S[1][1] - S[0][1] * S[1][0];
    vec2 se = vec2(S[1][1] * e.x - S[1][0] * e.y, S[0][0] * e.y - S[0][1] * e.x) / det;   // S^-1 e
    return seaFresnel(dot(h, L)) * exp(-0.5 * dot(e, se)) / (tau * sqrt(det))
         / (4.0 * max(-rd.y, 1e-3) * c * c * c * c)
         / (1.0 + seaLambda(-rd, S) + seaLambda(L, S));
}

// Whitecaps: coverage by the local wind (Monahan & O'Muircheartaigh 1980, W = 3.84e-6 U^3.41), each a
// patch along the crest (0.025 .. 0.075 lambda_p^2) breaking at albedo 0.55 and fading as its foam
// ages (mean 0.22, Koepke 1984). Two candidates per peak-wavelength cell (Pierson-Moskowitz), more in
// wave groups, each covering its share of the pixel; the mean once the footprint outgrows a cell.
// Returns (foam reflectance, coverage). x = m, wind frame; ji = m -> px; ext = footprint's long side (m).
vec2 whitecaps(vec2 x, float u, float uLoc, mat2 ji, float detJ, float ext, float t) {
    float W = min(3.84e-6 * pow(uLoc, 3.41), 0.08);
    float cw = 2.0 * pi * u * u / (0.731 * SEA_G);   // lambda_p = 2 pi g / omega_p^2, omega_p = 0.855 g / U
    float wMean = smoothstep(0.5, 1.0, ext / cw);
    vec2 mean = vec2(0.22 * W, W);
    if (wMean >= 1.0) return mean;
    float grp = 2.0 * smoothstep(-0.35, 0.35, gnoise(vec3(x / (3.0 * cw), 4.7)));   // wave groups, mean ~1
    float p = 10.0 * W * grp;                         // the chance a candidate breaks in this cycle
    float tl = 1.5 * tau * u / (0.855 * SEA_G); // 1.5 wave periods
    vec2 c0 = floor(x / cw), sum = vec2(0.0);
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            for (int m = 0; m < 2; m++) {
                ivec2 cell = ivec2(c0) + ivec2(i, j);
                ivec2 cwr = cell & 4095;                     // wrapped: the float hash of huge indices degenerates
                float ph = hash33(ivec3(cwr, 31 + m)).x;
                float uc = t / tl + ph;
                vec3 hp = hash33(ivec3(cwr, 1000 + 2 * (int(floor(uc)) & 1023) + m));
                if (hp.z < p) {
                    float ar = (0.025 + 0.05 * fract(hp.z * 17.31)) * cw * cw;   // its area, m^2
                    vec2 hm = 0.5 * sqrt(ar * 0.5) * vec2(1.0, 2.0);           // half sides: along, across
                    vec2 q = ji * ((vec2(cell) + hp.xy) * cw - x);   // its centre, pixels from this one's
                    vec2 e = vec2(abs(ji[0][0]) * hm.x + abs(ji[1][0]) * hm.y, abs(ji[0][1]) * hm.x + abs(ji[1][1]) * hm.y);
                    vec2 o = max(min(q + e, 0.5) - max(q - e, -0.5), 0.0);
                    float a = o.x * o.y * (ar / detJ) / (4.0 * e.x * e.y);   // the box's overlap, the true area
                    sum += vec2(0.55 * exp(-2.2 * fract(uc)) * a, a);
                }
            }
        }
    }
    return mix(min(sum, vec2(1.0)), mean, wMean);
}

// The glitter as single sun reflections: a facet mirroring the sun is over 1000 x the sky and far
// below a pixel, so real glitter is few points burnt to white, smooth only in its core. A glint is a
// SEA_GLINT_M square showing the sun's disc: the glinting share is pdf x the sun's solid angle (pdf =
// glit / Fresnel), a cs x cs m cell holds lam = share x cs^2 / SEA_GLINT_M^2 -- Poisson per cell and
// twinkle slot, exponential brightness. World cells, two levels crossfaded: a coarser render scale
// puts more glints into a pixel, never bigger ones. Returns the factor on glit, mean 1. Cells wrapped
// (& 4095): the float hash of huge indices (570 km out) comes back nearly constant -- a white sea.
#define SEA_SUN_SR 6.804e-5                           // the sun's solid angle, sr
float sparkleOf(float pdf, vec2 x, mat2 ji, float detJ, float time) {
    float share = pdf * SEA_SUN_SR;                   // the share of the sea that glints right now
    float ag = SEA_GLINT_M * SEA_GLINT_M;
    // cells of 1.5 px of the footprint's long axis (the 3 x 3 search holds every glint that can touch
    // the pixel), at least 3 glints wide (a glint stays in its cell's middle third)
    float fi = dot(ji[0], ji[0]) + dot(ji[1], ji[1]), di = 1.0 / detJ;
    float smax = 1.0 / sqrt(max(0.5 * (fi - sqrt(max(fi * fi - 4.0 * di * di, 0.0))), 1e-30));   // m per px, longer axis
    float lv = log2(max(1.5 * smax, 3.0 * SEA_GLINT_M));   // the cells' size, m, as a power of two
    float l0 = floor(lv), f = lv - l0, res = 0.0;
    // too few glints to see, or so many per cell that their sum varies by under 2 %: the mean
    float lam0 = share * exp2(2.0 * l0) / ag;
    if (4.0 * lam0 < 1e-5 || lam0 > 2000.0) return 1.0;
    vec2 ej = vec2(abs(ji[0][0]) + abs(ji[1][0]), abs(ji[0][1]) + abs(ji[1][1]));   // px per m of a box's side
    vec2 e = max(0.5 * SEA_GLINT_M * ej, vec2(1e-4)); // a glint's half box, px
    for (int k = 0; k < 2; k++) {
        float cs = exp2(l0 + float(k));
        float lam = share * cs * cs / ag;             // glints in a cell, on average
        // few per cell: one glint-sized patch (Poisson cut at 4, mn = its mean); many: the cell's box lit
        // by their sum, compound Poisson (mean lam, variance 2 lam) as a normal -- grain, not a smooth mean
        float sm = smoothstep(1.0, 6.0, lam);
        float ex = exp(-lam), l2 = 0.5 * lam * lam, l3 = l2 * lam / 3.0;
        float c1 = ex * (1.0 + lam), c2 = c1 + ex * l2, c3 = c2 + ex * l3;
        float mn = ex * (lam + 2.0 * l2 + 3.0 * l3) + 4.0 * (1.0 - c3);
        vec2 ec = 0.5 * cs * ej;                      // a cell's half box, px
        vec2 c0 = floor(x / cs) - 1.0;
        float s = 0.0, sc = 0.0;
        for (int j = 0; j < 3; j++) {
            for (int i = 0; i < 3; i++) {
                vec2 cell = c0 + vec2(i, j);
                ivec2 cw = ivec2(cell) & 4095;
                vec3 h = hash33(ivec3(cw, 77 + int(l0) + k));   // the glints' place and their phase
                // twinkling: the place stays, each 1 / SEA_TWINKLE s slot draws count and brightness anew,
                // flashing as 2 sin^2 (mean kept); the seed int(l0) + k matches the place's across levels
                float tw = time * SEA_TWINKLE + 7.0 * h.z;
                float slot = floor(tw);
                vec3 hs = hash33(ivec3(cw, 300 + (int(slot) & 1023) + 2048 * ((int(l0) + k) & 15)));
                float sn = sin(pi * (tw - slot));
                float twk = SEA_TWINKLE > 0.0 ? 2.0 * sn * sn : 1.0;
                if (sm < 1.0) {
                    float n = hs.z < ex ? 0.0 : hs.z < c1 ? 1.0 : hs.z < c2 ? 2.0 : hs.z < c3 ? 3.0 : 4.0;
                    if (n > 0.0) {
                        vec2 q = ji * ((cell + 1.0 / 3.0 + (1.0 / 3.0) * h.xy) * cs - x);   // the patch, px from here
                        vec2 o = max(min(q + e, 0.5) - max(q - e, -0.5), 0.0);
                        float b = n + sqrt(n) * (-log(max(hs.x, 1e-3)) - 1.0);   // n exponential glints: mean n, spread sqrt(n)
                        s += b * twk * o.x * o.y / (4.0 * e.x * e.y);   // its share of the pixel / its area (px)
                    }
                }
                if (sm > 0.0) {
                    vec2 q = ji * ((cell + 0.5) * cs - x);   // the cell's centre, px from here
                    vec2 o = max(min(q + ec, 0.5) - max(q - ec, -0.5), 0.0);
                    float g = 2.0 * (hs.x + hs.y + hs.z - 1.5);   // ~ normal (three uniforms), spread 1
                    sc += max(lam + sqrt(2.0 * lam) * g, 0.0) * twk * o.x * o.y / (4.0 * ec.x * ec.y);
                }
            }
        }
        // a cell carries cs^2 / detJ pixels' worth of glitter, mn (lam) glints on average
        res += (k == 0 ? 1.0 - f : f) * (cs * cs / detJ) * mix(s / mn, sc / lam, sm);
    }
    return res;
}

// The sea at one pixel (wind frame, m): point, footprint (px -> m), local wind, resolved mean slope,
// slope covariance, mirror ray, Fresnel, the wind's world axes.
struct Sea { vec2 xw; mat2 jw; float uLoc; vec2 mu; mat2 S; vec3 rr; float F; vec2 wd; };

// sp = the sea point, rd = the unit ray, D = the unnormalised ray (uv.x rtb + uv.y upb + FOCAL fw)
// of the pixel, roY = the camera's height, resY = iResolution.y, time = iTime.
Sea seaSurface(vec3 sp, vec3 rd, vec3 D, vec3 rtb, vec3 upb, float roY, float resY, float time) {
    Sea s;
    float sD = (SEA_Y - roY) / D.y * UNIT_KM * 1000.0 / resY;   // the screen pixel's axes carried to the plane
    vec2 jx = (rtb - D * (rtb.y / D.y)).xz * sD, jy = (upb - D * (upb.y / D.y)).xz * sD;
    s.wd = vec2(sin(WIND_AZ), cos(WIND_AZ));         // world xz of the wind frame's axes
    mat2 toW = mat2(s.wd.x, s.wd.y, -s.wd.y, s.wd.x); // wind frame -> world xz (columns: along, across)
    s.jw = transpose(toW) * mat2(jx, jy);            // pixel -> metres, wind frame
    // the waves' filter, a Gaussian of SEA_WAVE_PX (the pixel box's std 0.29 px let 66 % of a wave at
    // Nyquist through: moire); what it takes goes into the glitter's width
    mat2 cf = (SEA_WAVE_PX * SEA_WAVE_PX) * s.jw * transpose(s.jw);
    s.xw = transpose(toW) * (sp.xz * UNIT_KM * 1000.0);
    // gusts moving with the wind; slicks = calm streaks along it, contrast filtered by the footprint
    s.uLoc = SEA_WIND * max(1.0 + SEA_GUST * gnoise(vec3((s.xw.x - SEA_WIND * time) / 2500.0, s.xw.y / 900.0, 7.3)), 0.3);
    float slA = exp(-0.5 * cf[1][1] * pow(tau / 320.0, 2.0));
    float sl = SEA_SLICK * mix(0.2, smoothstep(0.1, 0.35, gnoise(vec3(s.xw.x / 1800.0, s.xw.y / 160.0, 2.1))), slA);
    vec2 cm = coxMunk(s.uLoc, sl);
    s.mu = vec2(0.0);
    mat2 sig = mat2(0.0), sigT = mat2(0.0);
#if SEA_WAVES
    // two swell and six wind-sea trains (+-60 deg, 0.5 .. 1.9 lambda_p; three drew a diamond lattice),
    // each phase shifted by a slow noise so their sum draws no regular fabric
    float lp = 2.0 * pi * SEA_WIND * SEA_WIND / (0.731 * SEA_G);
    float pw = SEA_WAVE_NOISE * gnoise(vec3(s.xw / (2.5 * lp), 9.1));
    float swl = SEA_SWELL;
    waveTrain(210.0, radians(SEA_SWELL_DIR), 0.8 * swl * tau / 210.0, 0.4 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(140.0, radians(SEA_SWELL_DIR) - 0.3, 0.45 * swl * tau / 140.0, 2.1 - 0.6 * pw, s.xw, time, cf, s.mu, sig, sigT);
    vec2 cm0 = coxMunk(SEA_WIND, 0.0);
    float sw = sqrt(SEA_WINDSEA / 3.0 * (cm0.x + cm0.y));   // each train SEA_WINDSEA / 6 of the variance
    waveTrain(1.9 * lp, 0.1, sw, 0.7 + 1.7 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(1.45 * lp, -0.5, sw, 4.0 - 2.3 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(1.1 * lp, 0.65, sw, 5.5 + 2.9 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(0.83 * lp, -0.23, sw, 2.6 - 1.1 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(0.64 * lp, 1.02, sw, 1.3 + 3.7 * pw, s.xw, time, cf, s.mu, sig, sigT);
    waveTrain(0.5 * lp, -0.88, sw, 3.4 - 2.9 * pw, s.xw, time, cf, s.mu, sig, sigT);
#endif
    // the rest stays Cox & Munk's (at least a third); kept positive definite: each axis >= 15 % of it
    float fT = min(1.0, 0.67 * (cm.x + cm.y) / max(sigT[0][0] + sigT[1][1], 1e-9));
    s.S = mat2(cm.x, 0.0, 0.0, cm.y) - fT * sigT + sig;
    s.S[0][0] = max(s.S[0][0], 0.15 * cm.x);
    s.S[1][1] = max(s.S[1][1], 0.15 * cm.y);
    float offLim = 0.9 * sqrt(s.S[0][0] * s.S[1][1]);
    float off = clamp(s.S[0][1], -offLim, offLim);
    s.S[0][1] = off;
    s.S[1][0] = off;
    vec2 muW = toW * s.mu;                           // the mean slope in world xz
    vec3 n = normalize(vec3(-muW.x, 1.0, -muW.y));
    s.rr = reflect(rd, n);
    s.rr.y = max(s.rr.y, 0.002);
#if SEA_FRESNEL_AVG
    vec2 vw = transpose(toW) * rd.xz;                // the view's azimuth in the wind frame
    float sv = sqrt(max(dot(vw, s.S * vw) / max(dot(vw, vw), 1e-12), 0.0));   // the slopes' std along it
    s.F = seaFresnelAvg(dot(-rd, n), sv);
#else
    s.F = seaFresnel(dot(-rd, n));
#endif
    return s;
}

// The sea's light at one pixel, before the air in front: mirror (sky and clouds), glitter, water, foam.
vec3 seaShade(Sea s, vec3 mirSky, vec3 rd, vec3 L, vec3 sunC, vec3 skyA, float sh, float tr,
              float points, float time) {
    vec3 mir = mirSky;
#if SEA_MIRROR
    // the clouds in the mirror make the far sea's grey (at grazing angles the sea mirrors 5 .. 20 %): flat
    // mirror rays meet the flanks (half sun, half shade), steeper ones the dark base (diffuse ~0.2)
    vec3 base = 0.2 * (sunC * max(L.y, 0.0) + skyA);
    vec3 flank = 0.35 * sunC * (0.3 + 0.7 * max(L.y, 0.0)) + 0.5 * skyA;
    mir = mix(mix(flank, base, smoothstep(0.3, 0.7, s.rr.y)), mir, tr);
#endif
    // the glitter, in the slopes' wind frame
    vec2 wp = vec2(-s.wd.y, s.wd.x);
    float glit = seaGlitter(vec3(dot(rd.xz, s.wd), rd.y, dot(rd.xz, wp)), vec3(dot(L.xz, s.wd), L.y, dot(L.xz, wp)), s.mu, s.S);
    float detJ = abs(determinant(s.jw));
    mat2 ji = inverse(s.jw);                         // metres -> pixels
    // the points need the slopes' density alone: glit / the Fresnel of the facet that mirrors the sun
    float Fh = seaFresnel(dot(normalize(L - rd), L));
    if (SEA_GLINT_M > 0.0 && points > 0.0) glit *= mix(1.0, sparkleOf(glit / Fh, s.xw, ji, detJ, time), points);
    vec3 water = s.F * mir + RAD_K * sunC * (glit * sh) + (1.0 - s.F) * SEA_COL * (sunC * (max(L.y, 0.0) * sh) + skyA);
    // a glitter point is the sun's light concentrated: capped high with its hue kept -- a per-channel cap
    // of 8 cut the far glitter to plain white, which 180 km of air then dyed orange
    water *= min(1.0, SEA_CAP / max(max(water.r, water.g), max(water.b, 1e-6)));
#if SEA_FOAM
    vec2 fo = whitecaps(s.xw, SEA_WIND, s.uLoc, ji, detJ, sqrt(max(dot(s.jw[0], s.jw[0]), dot(s.jw[1], s.jw[1]))), time);
    water = water * (1.0 - fo.y) + fo.x * (sunC * (max(L.y, 0.0) * sh) + skyA);
#endif
    return water;
}

// The sea past the caller's trace: seaSurface / seaShade with a pixel tens of km wide (resY 1), so
// waves and foam average out without a seam to the near sea. mirSky = the sky along (rd.x, -rd.y, rd.z).
vec3 seaFarLight(vec3 sp, vec3 rd, vec3 mirSky, vec3 L, vec3 sunC, vec3 skyA, float sh, float tr, float roY, float time) {
    vec3 ac = normalize(vec3(rd.z, 0.0, -rd.x) + vec3(1e-9, 0.0, 0.0));   // across the ray, level
    Sea s = seaSurface(sp, rd, rd, ac, vec3(0.0, 1.0, 0.0), roY, 1.0, time);
    return seaShade(s, mirSky, rd, L, sunC, skyA, sh, tr, 0.0, time);
}

// An open-sea sample packs the sun's and mirror ray's transmittance into .a (< 0) instead of its depth,
// so the Image draws the sea at full resolution (in the 1/16 lattice the glitter smeared into grain).
float seaPack(float sh, float tr) { return -(1.0 + floor(clamp(sh, 0.0, 1.0) * 4095.0 + 0.5) + 4096.0 * floor(clamp(tr, 0.0, 1.0) * 4095.0 + 0.5)); }
vec2 seaUnpack(float a) { float v = -a - 1.0, q = floor(v / 4096.0); return vec2(v - 4096.0 * q, q) / 4095.0; }
// ===== SEA MODULE end ============================================================================

// The far background past the trace's 120 units: a flat deck (weighted by the cover, more toward
// grazing views) over the far sea (sun and mirror rays clear the layer by the cover's chance over the
// slant path), hazed toward the level sky. In Common so the Image can fade the near sea into it.
// The sky with its horizon lowered by d (radians) under the edge of the traced field (HORIZON_DROP):
// dropView raises a direction's elevation by d; the sun is drawn at dropView(L, -d) to stay in its glow.
float horizonDrop(float roY) { return HORIZON_DROP >= 0.0 ? atan(max(roY - FAR_DECK_Y, 0.0), 120.0) + radians(HORIZON_DROP) : 0.0; }
vec3 dropView(vec3 rd, float d) {
    float e = min(asin(clamp(rd.y, -1.0, 1.0)) + d, 1.5707);
    vec2 h = normalize(rd.xz + vec2(1e-9, 0.0));
    return vec3(h.x * cos(e), sin(e), h.y * cos(e));
}

vec3 farBand(sampler2D sky, vec3 ro, vec3 rd, vec3 L, vec3 sunC, vec3 skyA, float kRad, float cover, float time) {
#if FAR_SKY
    vec3 dv = dropView(rd, horizonDrop(ro.y));
    dv.y = abs(dv.y);                                  // below the lowered horizon: the sky mirrored
    return skyLut(sky, dv, L) * kRad;
#else
    vec3 airExt = atmoExt(atmoDensity(CAM_KM)) * UNIT_KM;
    float tD = max((FAR_DECK_Y - ro.y) / rd.y, 120.0);
    float cov = 1.0 - pow(1.0 - cover, 1.0 + 0.15 / max(-rd.y, 0.01));
    vec3 deck = FAR_DECK_ALB * (sunC * (0.25 + 0.75 * max(L.y, 0.0)) + skyA);
    float tS = (SEA_Y - ro.y) / rd.y;
    float shF = mix(1.0, pow(1.0 - cover, 1.0 + 1.8 / max(L.y, 0.01)), SEA_SHADOW_K);
    float trF = pow(1.0 - cover, 1.0 + 1.8 / max(-rd.y, 0.01));
    vec3 seaFar = seaFarLight(ro + rd * tS, rd, skyLut(sky, vec3(rd.x, -rd.y, rd.z), L) * kRad,
                              L, sunC, skyA, shF, trF, ro.y, time);
    vec3 hazeLevel = skyLut(sky, normalize(vec3(rd.x, 0.0, rd.z) + 1e-9), L) * kRad;
    return mix(hazeLevel, mix(seaFar, deck, cov), exp(-airExt * tD));
#endif
}

// A fog in the far clouds' colour at the trace's 120 units, where the near sea and the far band (two
// models) met in a hard line. farFogW: 1 where the ray crosses BASE at 120, 0 at +-FAR_FOG x 120.
float farFogW(vec3 ro, vec3 rd) {
    return FAR_FOG > 0.0 ? 1.0 - smoothstep(0.0, FAR_FOG * 120.0, abs((BASE - ro.y) / rd.y - 120.0)) : 0.0;
}
vec3 farFog(sampler2D sky, vec3 rd, vec3 L, vec3 sunC, vec3 skyA, float kRad, float roY) {
#if FAR_SKY
    vec3 dv = dropView(rd, horizonDrop(roY));          // the band's own colour at the line
    dv.y = abs(dv.y);
    return skyLut(sky, dv, L) * kRad;
#else
    vec3 deck = FAR_DECK_ALB * (sunC * (0.25 + 0.75 * max(L.y, 0.0)) + skyA);
    vec3 hazeLevel = skyLut(sky, normalize(vec3(rd.x, 0.0, rd.z) + 1e-9), L) * kRad;
    return mix(hazeLevel, deck, exp(-atmoExt(atmoDensity(CAM_KM)) * UNIT_KM * 120.0));
#endif
}//aladiN

