vec4 fxaa(sampler2D tex, vec2 uv, vec2 ts) {
    const float spanMax = 8.0, redMin = 1.0/128.0, redMul = 1.0/32.0;
    const vec3 luma = vec3(0.299, 0.587, 0.114);

    vec4 cc = texture(tex, uv);
    vec3 c00 = texture(tex, uv + vec2(-0.5,-0.5)*ts).rgb;
    vec3 c10 = texture(tex, uv + vec2(+0.5,-0.5)*ts).rgb;
    vec3 c01 = texture(tex, uv + vec2(-0.5,+0.5)*ts).rgb;
    vec3 c11 = texture(tex, uv + vec2(+0.5,+0.5)*ts).rgb;

    float lCC = dot(cc.rgb,luma), l00 = dot(c00,luma), l10 = dot(c10,luma), l01 = dot(c01,luma), l11 = dot(c11,luma);

    vec2 dir;
    dir.x = (l01+l11)-(l00+l10);
    dir.y = (l00+l01)-(l10+l11);

    float redDir = max((l00+l10+l01+l11)*redMul, redMin);
    float rcp = 1.0 / (min(abs(dir.x), abs(dir.y)) + redDir);
    dir = clamp(dir * rcp, -spanMax, spanMax) * ts;

    vec4 sA = 0.5 * (texture(tex, uv - dir*(1.0/6.0)) + texture(tex, uv + dir*(1.0/6.0)));
    vec4 sB = sA * 0.5 + 0.25 * (texture(tex, uv - dir*0.5) + texture(tex, uv + dir*0.5));

    float lMin = min(lCC, min(min(l00, l10), min(l01, l11)));
    float lMax = max(lCC, max(max(l00, l10), max(l01, l11)));
    float lB = dot(sB.rgb, luma);

    vec3 aa = (lB < lMin || lB > lMax) ? sA.rgb : sB.rgb;
    return vec4(aa, cc.a);
}

vec3 radialDOF(sampler2D tex, vec2 uv, float blurRadius, float aspect) {
    vec3 col = vec3(0.0);
    const float goldenAngle = 2.39996323;
    const float iterations = 48.0; 

    for (float i = 0.0; i < iterations; i++) {
        float r = sqrt((i + 0.5) / iterations) * blurRadius;
        float theta = i * goldenAngle;
        vec2 offset = vec2(cos(theta), sin(theta)) * r;
        offset.x /= aspect;
        col += texture(tex, uv + offset).rgb;
    }
    return col / iterations;
}

vec3 bloomBrightPass(sampler2D tex, vec2 uv, vec2 ts, float threshold) {
    vec3 col = vec3(0.0);
    float totWeight = 0.0;
    const float taps = 20.0;
    const float goldenAngle = 2.39996323;

    for (float i = 0.0; i < taps; i++) {
        float r = sqrt(i / taps) * 0.012; 
        float theta = i * goldenAngle;
        vec2 offset = vec2(cos(theta), sin(theta)) * r;

        vec3 smpl = texture(tex, uv + offset).rgb;
        float luma = dot(smpl, vec3(0.299, 0.587, 0.114));

        vec3 bright = max(smpl - threshold, 0.0);
        float karisWeight = 1.0 / (1.0 + luma);

        col += bright * karisWeight;
        totWeight += karisWeight;
    }
    return col / max(totWeight, 0.0001);
}

vec3 anamorphicStreak(sampler2D tex, vec2 uv, vec2 ts, float threshold) {
    vec3 streak = vec3(0.0);
    float tot = 0.0;
    for (float i = 1.0; i <= 14.0; i++) {
        float w = 1.0 / i;
        vec3 sR = texture(tex, uv + vec2(i * ts.x * 2.5, 0.0)).rgb;
        vec3 sL = texture(tex, uv - vec2(i * ts.x * 2.5, 0.0)).rgb;
        streak += max(sR - threshold, 0.0) * w;
        streak += max(sL - threshold, 0.0) * w;
        tot += w * 2.0;
    }
    return streak / max(tot, 0.0001);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 ts = 1.0 / iResolution.xy;
    vec2 uv = fragCoord * ts;

    float targetAspect = 2.35;
    float aspect = iResolution.x / iResolution.y;
    float barH = max(0.0, (1.0 - (aspect / targetAspect)) / 2.0);

    if (uv.y < barH || uv.y > 1.0 - barH) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec2 centerUV = uv - 0.5;
    float distSq = dot(centerUV, centerUV);
    vec2 caOffset = centerUV * distSq * 0.0018; 

    vec3 col = fxaa(iChannel0, uv, ts).rgb;
    col.r = fxaa(iChannel0, uv - caOffset, ts).r;
    col.b = fxaa(iChannel0, uv + caOffset, ts).b;

    centerUV.x *= aspect;
    float dist = length(centerUV);
    float blurMask = smoothstep(0.50, 0.95, dist);

    if (blurMask > 0.0) {
        vec3 bokehCol = radialDOF(iChannel0, uv, blurMask * 0.014, aspect);
        col = mix(col, bokehCol, blurMask * 0.7);
    }

    vec3 bloom = bloomBrightPass(iChannel0, uv, ts, 1.4); 
    col += bloom * 0.16;

    vec3 streak = anamorphicStreak(iChannel0, uv, ts, 2.2); 
    col += streak * vec3(0.4, 0.8, 1.0) * 0.06;


    col *= 0.82;

    col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);


    col = pow(max(col, 0.0), vec3(1.15));

    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(vec3(lum), col, 1.12);
    col *= vec3(0.98, 1.00, 1.02);

    vec2 vUV = uv - 0.5;
    float vig = 1.0 - smoothstep(0.22, 1.30, length(vUV));
    col *= mix(1.0, vig, 0.42);



    col = pow(max(col, 0.0), vec3(1.0 / 2.2));

    fragColor = vec4(col, 1.0);
}

//1023 15:45
#define ZERO (min(iFrame, 0))
#define CAMBUF iChannel0
#define AUDIO  iChannel1
#define MAX_DIST 180.0
#define VOL_DIST 40.0

const float LIGHT_POWER = 4.0;

const float BEAM_GAIN = 0.4;    

mat3  gColRot;
vec3  gBall;
float gPress;
vec3  gImp;
float gWaveR;
float gWaveAmp;
float gLightDip;
float gFocal = 1.0;
float gTime;
float gBass, gMid, gHigh, gTotal;

vec2 hash22(vec2 p) {
    mat2 m = mat2(13.85, 47.77, 99.41, 88.48);
    return fract(sin(m * p) * 46738.29);
}

float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2(1, 0)), f.x),
               mix(hash12(i + vec2(0, 1)), hash12(i + vec2(1, 1)), f.x), f.y);
}

float line1(float x, float w, float fw) {
    fw += 1e-4;
    float dd = 0.5 - abs(fract(x) - 0.5);
    float a = smoothstep(w - fw, w + fw, dd);
    return mix(a, 1.0 - 2.0 * w, clamp(fw / w * 0.5, 0.0, 1.0));
}
float lineMask(vec2 uv, float w, float fw) {
    return line1(uv.x, w, fw) * line1(uv.y, w, fw);
}

float voronoi(vec2 p) {
    vec2 g = floor(p);
    vec2 f = fract(p);
    float dist = 1.0;
    for (int y = ZERO - 1; y <= 1; y++) {
        for (int x = ZERO - 1; x <= 1; x++) {
            vec2 lattice = vec2(x, y);
            float d = distance(lattice + hash22(g + lattice), f);
            dist = min(dist, d);
        }
    }
    return dist;
}

vec3 getVoronoi2D(vec2 uv, float t) {
    vec2 scaledUV = uv * 2.0 - 1.0;

    float offset = 0.0, r = 0.0;
    for (int k = ZERO; k < 2; k++) {
        float v = voronoi(k == 0 ? uv * 8.0 + vec2(t * 0.5) : uv * 4.0);
        if (k == 0) offset = v; else r = v * 10.0;
    }

    float distDenom = abs(((scaledUV.x + sin(scaledUV.y + t)) + offset) * 30.0);
    float t_val = 1.0 / max(distDenom, 0.002);
    vec3 finalColor = vec3(10.0 * scaledUV.y, 2.0, 1.0 * r) * t_val;
    return abs(gColRot * finalColor);
}

vec3 getTriplanarVoronoi(vec3 lp, float t, bool full) {
    vec3 w = abs(normalize(lp));
    w *= w;
    w /= (w.x + w.y + w.z);

    if (!full) w = step(vec3(max(w.x, max(w.y, w.z))), w);

    vec3 c = vec3(0.0);
    float ws = 0.0;
    for (int i = ZERO; i < 3; i++) {
        float wi = (i == 0) ? w.x : ((i == 1) ? w.y : w.z);
        if (wi > 0.03) {
            vec2 uvA = (i == 0) ? lp.yz : ((i == 1) ? lp.xz : lp.xy);
            c += getVoronoi2D(uvA, t) * wi;
            ws += wi;
        }
    }
    return c / ws;
}

vec3 lightCol(float idx, float t) {
    vec3 baseCol = hash13(idx * 123.4) * 0.8 + 0.2;
    float glitchProb = hash11(idx * 87.1);
    float intensity = 1.0;
    if (glitchProb > 0.6) {
        intensity  = step(0.5, fract(sin(t * 30.0 + idx + gHigh * 60.0) * 43758.5453));
        intensity *= max(0.2, sin(t * 10.0 + idx * 5.0));
    }
    float beat = 0.7 + AUDIO_AMOUNT * gBass * (0.45 + 0.35 * sin(idx * 1.3 - t * 6.0));
    baseCol = mix(baseCol, baseCol.zxy, clamp(gMid * AUDIO_AMOUNT, 0.0, 1.0) * 0.5);
    return baseCol * intensity * beat * gLightDip;
}

float sphSoftShadow(vec3 ro, vec3 rd, vec4 sph, float k) {
    vec3 oc = ro - sph.xyz;
    float b = dot(oc, rd);
    float c = dot(oc, oc) - sph.w * sph.w;
    float h = b * b - c;
    float d = sqrt(max(0.0, sph.w * sph.w - h)) - sph.w;
    float t = -b - sqrt(max(h, 0.0));
    return (t < 0.0) ? 1.0 : smoothstep(0.0, 1.0, 2.5 * k * d / t);
}



vec3 beamApex(float idx) {
    return vec3(0.0, ROOM_H - 0.2, idx * LS + LS * 0.5);
}


vec3 beamDir(float idx, float t) {
    float ph  = hash11(idx * 17.3) * 6.2831;
    float spd = 0.5 + hash11(idx * 3.7) * 0.7;
    float mag = 0.22 + 0.22 * gMid * AUDIO_AMOUNT;
    vec2 sw = vec2(sin(t * spd + ph), cos(t * spd * 0.8 + ph * 1.7)) * mag;
    return normalize(vec3(sw.x, -1.0, sw.y));
}

float beamProfile(vec3 p, vec3 A, vec3 D, float tanH) {
    vec3 v = p - A;
    float along = dot(v, D);
    float perp = length(v - D * along);
    float r = max(along, 0.0) * tanH + 0.05;
    float prof = 1.0 - smoothstep(0.35 * r, r, perp);
    return along > 0.0 ? prof : 0.0;
}

void gatherLight(vec3 p, vec3 n, vec3 rd, float shin, float t, vec4 sph,
                 bool shadows, out vec3 diff, out vec3 spec) {
    diff = vec3(0.0);
    spec = vec3(0.0);
    float cell = floor(p.z / LS);
    float nb = cell + (fract(p.z / LS) > 0.5 ? 1.0 : -1.0);
    float tanH = 0.22 * (1.0 + 0.4 * AUDIO_AMOUNT * gBass);
    for (int i = ZERO; i < 2; i++) {
        float idx = (i == 0) ? cell : nb;
        vec3 lp = beamApex(idx);
        vec3 L = lp - p;
        float d2 = dot(L, L);
        L *= inversesqrt(d2);
        float att = 1.0 / (1.0 + 0.08 * d2);

        float spot = beamProfile(p, lp, beamDir(idx, t), tanH);
        float pool = 0.5 + 1.2 * spot;

        vec3 lc = lightCol(idx, t) * att * LIGHT_POWER * pool;
        float sh = shadows ? sphSoftShadow(p + n * 0.01, L, sph, 8.0) : 1.0;
        vec3 h = normalize(L - rd);
        diff += lc * max(dot(n, L), 0.0) * sh;
        spec += lc * pow(max(dot(n, h), 0.0), shin) * sh;
    }
}
vec3 getLocalSpherePos(vec3 p, vec3 center) {
    vec3 localP = p - center;
    float rollAngle = -center.z;
    mat2 rotX = mat2(cos(rollAngle), -sin(rollAngle), sin(rollAngle), cos(rollAngle));
    localP.yz *= rotX;
    return localP;
}

void setupFrame(float t) {
    float cs = cos(t), sn = sin(t);
    float k = (1.0 - cs) / 3.0, r = sn * 0.57735027;
    gColRot = mat3(cs + k, k - r, k + r,
                   k + r, cs + k, k - r,
                   k - r, k + r, cs + k);

    gTime = t;
    gBall = getSpherePos(t);
    float bh = abs(sin(t * 3.5)) * 1.5;
    gPress = 1.0 - smoothstep(0.0, 0.45, bh);

    float ti = mod(t * 3.5, PI) / 3.5;
    gImp = vec3(0.0, 0.0, gBall.z - 4.0 * ti);
    gWaveR = 7.0 * ti;
    gWaveAmp = 0.35 * exp(-ti * 2.5);
    gLightDip = 1.0 - 0.35 * exp(-ti * 12.0);
}

float deformD(vec3 q, float kind) {
    float K, fo, A;
    if (kind < 0.5)      { K = 0.17; fo = 0.30; A = 1.0; }
    else if (kind < 1.5) { K = 0.22; fo = 0.09; A = 0.9; }
    else                 { K = 0.10; fo = 0.06; A = 0.4; }

    vec3 db = q - gBall;
    float w = -gPress * K * exp(-dot(db, db) * fo);

    float r = length(q - gImp);
    float x = r - gWaveR;
    float wave = sin(x * 2.6) * exp(-x * x * 0.5) * gWaveAmp / (1.0 + 0.25 * r);
    float vib = AUDIO_AMOUNT * gBass * 0.05 * sin(length(db) * 2.5 - gTime * 12.0)
              * exp(-dot(db, db) * 0.04);
    return w + (wave + vib) * A;
}


bool planeHit(vec3 ro, vec3 rd, vec3 N0, float c, vec3 T1, vec3 T2, float kind,
              out float s, out vec3 n) {
    float den = dot(rd, N0);
    s = (c - dot(ro, N0)) / den;
    n = N0;
    vec3 q = ro + rd * s;

    if (abs(q.z - gImp.z) < 11.0) {

        const float EPS = 0.02; 
        for (int it = ZERO; it < 3; it++) {
            vec3 p = ro + rd * s;
            float hgt = dot(p, N0) - c;
            vec3 pp = p - N0 * hgt;

            float D0 = deformD(pp, kind);
            float D1 = deformD(pp + T1 * EPS, kind);
            float D2 = deformD(pp + T2 * EPS, kind);

            float g1 = (D1 - D0) / EPS;
            float g2 = (D2 - D0) / EPS;

            float fp = den - (g1 * dot(rd, T1) + g2 * dot(rd, T2));
            fp = (fp < 0.0 ? -1.0 : 1.0) * max(abs(fp), 0.08); 
            s -= 0.75 * (hgt - D0) / fp; 
        }

        vec3 pFinal = ro + rd * s;
        float hgtFinal = dot(pFinal, N0) - c;
        vec3 ppFinal = pFinal - N0 * hgtFinal;

        const float N_EPS = 0.01;
        float dx = deformD(ppFinal + T1 * N_EPS, kind) - deformD(ppFinal - T1 * N_EPS, kind);
        float dy = deformD(ppFinal + T2 * N_EPS, kind) - deformD(ppFinal - T2 * N_EPS, kind);

        n = normalize(N0 - (dx / (2.0 * N_EPS)) * T1 - (dy / (2.0 * N_EPS)) * T2);
    }
    return s > 1e-3;
}

vec2 trace(vec3 ro, vec3 rd, vec4 sph, out vec3 n) {
    float tmin = MAX_DIST;
    float mat = 0.0;
    n = vec3(0.0, 1.0, 0.0);

    vec3 oc = ro - sph.xyz;
    float b = dot(oc, rd);
    float cc = dot(oc, oc) - sph.w * sph.w;
    float h = b * b - cc;
    if (h > 0.0) {
        float ss = -b - sqrt(h);
        if (ss > 1e-3) { tmin = ss; mat = 1.0; n = (oc + rd * ss) / sph.w; }
    }

    for (int i = ZERO; i < 2; i++) {
        vec3 N0, T1;
        float c, kind;
        bool ok, neg;
        if (i == 0) {
            ok = abs(rd.y) > 1e-4;
            neg = rd.y < 0.0;
            N0 = neg ? vec3(0, 1, 0) : vec3(0, -1, 0);
            c = neg ? 0.0 : -ROOM_H;
            T1 = vec3(1, 0, 0);
            kind = neg ? 0.0 : 2.0;
        } else {
            ok = abs(rd.x) > 1e-4;
            neg = rd.x < 0.0;
            N0 = neg ? vec3(1, 0, 0) : vec3(-1, 0, 0);
            c = -ROOM_W;
            T1 = vec3(0, 1, 0);
            kind = 1.0;
        }
        if (ok) {
            float s; vec3 nn;
            if (planeHit(ro, rd, N0, c, T1, vec3(0, 0, 1), kind, s, nn) && s < tmin) {
                tmin = s;
                n = nn;
                if (i == 0) {
                    if (neg) mat = 2.0;
                    else {
                        vec3 q = ro + rd * s;
                        float lz = mod(q.z, LS) - LS * 0.5;
                        mat = (abs(q.x) < 0.5 && abs(lz) < 0.5) ? 6.0 : 3.0;
                    }
                } else {
                    mat = neg ? 4.0 : 5.0;
                }
            }
        }
    }
    return vec2(tmin, mat);
}

float footprint(float d, vec3 n, vec3 rd) {
    return clamp(1.25 * d / (iResolution.y * gFocal * max(abs(dot(n, rd)), 0.08)), 0.0, 0.5);
}

vec3 calcVolumetrics(vec3 ro, vec3 rd, float maxD, float t, float dither) {
    const int STEPS = 45; 
    float dist = min(maxD, VOL_DIST);

    vec3 acc = vec3(0.0);
    float lastCell = -1e9;
    vec3 lc = vec3(0.0);
    vec3 D = vec3(0.0, -1.0, 0.0);
    vec3 A = vec3(0.0);
    float tanH = 0.14 * (1.0 + 0.4 * AUDIO_AMOUNT * gBass);

    float s = 0.2 * dither; 

    for (int i = ZERO; i < STEPS; i++) {
        if (s > dist) break;

        float stepSize = 0.2 + s * 0.04; 
        if (s + stepSize > dist) stepSize = dist - s; 

        vec3 p = ro + rd * s;
        float cell = floor(p.z / LS);
        if (cell != lastCell) {
            lc = lightCol(cell, t);
            D = beamDir(cell, t);
            A = beamApex(cell);
            lastCell = cell;
        }


        float fogNoise = vnoise(vec2(p.x * 0.35 + sin(t * 0.2), p.z * 0.15 - t * 0.18));
        float fogDensity = 0.022 + 0.016 * fogNoise;

       vec3 fogTint = mix(vec3(0.04, 0.16, 0.22), vec3(0.22, 0.04, 0.15),
                           smoothstep(-ROOM_W, ROOM_W, p.x));

       fogTint += lc * 0.08;


        fogDensity *= 1.0 + 0.25 * AUDIO_AMOUNT * gBass;

        acc += fogTint * fogDensity * stepSize;


        vec3 v = p - A;
        float along = dot(v, D);

        if (along > 0.0 && p.y <= A.y) {
            float perp = length(v - D * along);
            float r = along * tanH + 0.04;

            float prof = smoothstep(r + 0.15, r * 0.4, perp);

            if (prof > 0.0) {
                float dust = 0.65 + 0.7 * vnoise(vec2(p.x * 1.3 + p.y * 0.9, p.z * 1.1 - p.y * 0.7) + t * 0.4);
                float fall = 1.0 / (1.0 + 0.03 * along * along);

                acc += lc * prof * dust * fall * stepSize;
            }
        }
        s += stepSize;
    }
    return acc * BEAM_GAIN;
}



vec3 renderSurface(vec3 p, inout vec3 n, vec3 rd, float mat, float t, float px,
                   vec4 sph, bool full, out float refl) {
    refl = 0.0;


    if (mat > 5.5) {
        vec3 lc = lightCol(floor(p.z / LS), t);
        vec2 q = abs(vec2(p.x, mod(p.z, LS) - LS * 0.5));
        float edge = 1.0 - smoothstep(0.30, 0.50, max(q.x, q.y));
        return lc * (1.2 + 1.8 * edge); 
    }

    bool isSph = mat < 1.5;
    vec3 albedo = vec3(0.1);
    vec3 emis = vec3(0.0);
    vec3 vor = vec3(0.0);
    float shin = 40.0;
    float specAmt = 0.5;
    float ao = 1.0;
    float nf = 1.0 / (1.0 + px * 60.0);

    vec3 sc = 0.5 + 0.5 * cos(t * 0.8 + vec3(0.0, 2.0, 4.0));
    float xr = length(p - gImp) - gWaveR;
    float ring = exp(-xr * xr * 1.2) * gWaveAmp * 2.5;

    if (isSph) {
        vor = getTriplanarVoronoi(getLocalSpherePos(p, sph.xyz), t, full);
        shin = 32.0;
    }

    else if (mat < 2.5) {
        vec2 uv = p.xz;
        vec2 fr = fract(uv);
        vec2 e = 0.5 - abs(fr - 0.5);

        float big   = lineMask(uv, 0.014, px);
        float small = lineMask(uv * 4.0, 0.03, px * 4.0);
        float rnd   = hash12(floor(uv));

        vec2 bev = 1.0 - smoothstep(vec2(0.0), vec2(0.04), e);
        n.xz += sign(fr - 0.5) * bev * 0.55 * nf;
        float grain = vnoise(uv * vec2(60.0, 14.0)) - 0.5;
        n.xz += vec2(grain * 0.05, grain * 0.02) * nf;
        n = normalize(n);

        albedo = mix(vec3(0.07, 0.08, 0.095), vec3(0.13, 0.14, 0.16), rnd);
        albedo *= mix(0.6, 1.0, small);
        albedo *= big;
        albedo *= 0.8 + 0.4 * vnoise(uv * 3.0);

        vec3 neon = (p.x < 0.0) ? vec3(0.1, 0.9, 1.0) : vec3(1.0, 0.15, 0.65);
        float strip = 1.0 - smoothstep(0.02, 0.03 + px, abs(abs(p.x) - 2.65));
        float pulse = (0.55 + 0.45 * sin(p.z * 0.8 - t * 3.0)) * (0.7 + 1.6 * AUDIO_AMOUNT * gMid);
        emis += neon * strip * (pulse + ring * 2.0) * 2.0;
        emis += neon * exp(-abs(abs(p.x) - 2.65) * 7.0) * 0.06 * pulse;
        emis += sc * ring * 0.5;

        ao = 0.6 + 0.4 * smoothstep(0.0, 1.2, ROOM_W - abs(p.x));
        shin = 90.0;
        specAmt = 1.2 * (0.6 + 0.8 * vnoise(uv * 8.0));
        refl = 0.22;
    }
    else if (mat < 3.5) {

        /* Kind of prefer this roof material ? 
        vec2 uv = p.xz * 0.5;
        albedo = vec3(0.05, 0.055, 0.065) * lineMask(uv, 0.015, px * 0.5);
        float lz = mod(p.z, LS) - LS * 0.5;
        float frame = 1.0 - smoothstep(0.55, 0.62, max(abs(p.x), abs(lz)));
        albedo = mix(albedo, vec3(0.02), frame);
        shin = 60.0;
        specAmt = 0.4;
        ao = 0.8;
        */

        /* The Voronoi patten in the roof  
        vec2 uv = p.xz * 0.5;
        float mask = lineMask(uv, 0.015, px * 0.5);
        albedo = vec3(0.05, 0.055, 0.065) * mask;

        float lz = mod(p.z, LS) - LS * 0.5;
        float frame = 1.0 - smoothstep(0.55, 0.62, max(abs(p.x), abs(lz)));
        albedo = mix(albedo, vec3(0.02), frame);


        vec2 vorUV = p.xz * 0.12;
        vec3 roofVor = getVoronoi2D(vorUV, t * 0.4);


        float vorIntensity = 0.025 + 0.025 * AUDIO_AMOUNT * gMid;
        emis += roofVor * vorIntensity * (1.0 - frame);

        shin = 60.0;
        specAmt = 0.4;
        ao = 0.8;

        */

        vec2 uv = p.xz * 0.5;
        float mask = lineMask(uv, 0.015, px * 0.5);
        albedo = vec3(0.035, 0.04, 0.045) * mask;

        float lz = mod(p.z, LS) - LS * 0.5;
        float frame = 1.0 - smoothstep(0.55, 0.62, max(abs(p.x), abs(lz)));
        albedo = mix(albedo, vec3(0.02), frame);

        vec2 suv = p.xz * 0.16;
        vec2 drift = vec2(sin(t * 0.35 + p.z * 0.15) * 0.3, t * 0.22);

        float s1 = vnoise(suv + drift);
        float s2 = vnoise(suv * 2.3 - drift * 0.5 + s1 * 0.65);
        float smoke = smoothstep(0.28, 0.80, s1 * 0.55 + s2 * 0.45);

         vec3 lc = lightCol(floor(p.z / LS), t);
        vec3 hazeBase = vec3(0.05, 0.07, 0.09);
        vec3 smokeLit = mix(hazeBase, lc * 0.4, 0.5);
        vec3 smokeCol = mix(vec3(0.0), smokeLit, smoke);

        float smokeGain = 0.45 + 0.20 * AUDIO_AMOUNT * gBass;
        emis += smokeCol * smokeGain * (1.0 - frame * 0.6);

        shin = mix(60.0, 25.0, smoke);
        specAmt = mix(0.4, 0.15, smoke);
        ao = 0.85;


    }
    else {
        bool teal = mat < 4.5;
        vec3 tone = teal ? vec3(0.04, 0.12, 0.15) : vec3(0.14, 0.05, 0.11);
        vec3 neon = teal ? vec3(0.1, 0.9, 1.0)    : vec3(1.0, 0.15, 0.65);

        vec2 wuv = vec2(p.z * 0.5, p.y * 0.8);
        vec2 f = fract(wuv);
        vec2 cid = floor(wuv);
        float rnd = hash12(cid + (teal ? 0.0 : 17.0));
        float fwu = px * 0.8;

        float panel = lineMask(wuv, 0.015, fwu);

        vec2 e = 0.5 - abs(f - 0.5);
        vec2 bev = 1.0 - smoothstep(vec2(0.0), vec2(0.05), e);
        vec2 sg = sign(f - 0.5);
        n.z += sg.x * bev.x * 0.5 * nf;
        n.y += sg.y * bev.y * 0.5 * nf;
        n = normalize(n);

        albedo = tone * (0.7 + 0.6 * rnd) * panel;
        albedo *= 0.85 + 0.3 * vnoise(vec2(p.z * 3.0, p.y * 40.0)) * nf + 0.15 * (1.0 - nf);

        float lower = 1.0 - smoothstep(0.95, 1.05, p.y);
        float ribs = line1(p.z * 4.0, 0.12, px * 4.0);
        albedo = mix(albedo, albedo * 0.45 * mix(1.0, ribs, 0.8), lower);

        if (rnd > 0.78) {
            float inside = smoothstep(0.12, 0.12 + fwu + 0.02, min(f.x, 1.0 - f.x))
                         * smoothstep(0.20, 0.20 + fwu + 0.02, min(f.y, 1.0 - f.y));
            float slat = line1(wuv.y * 7.0, 0.18, fwu * 7.0);
            albedo *= mix(1.0, slat * 0.8 + 0.2, inside);
        }

        if (rnd < 0.15) {
            vec2 q = abs(f - vec2(0.5, 0.75));
            float led = 1.0 - smoothstep(0.05, 0.05 + px, max(q.x * 2.0, q.y * 1.25));
            vec3 lcol = mix(vec3(1.0, 0.5, 0.1), vec3(0.2, 1.0, 0.4), step(0.07, rnd));
            float blink = step(0.5, fract(t * 0.5 + rnd * 10.0));
            float hb = smoothstep(0.05, 0.25, AUDIO_AMOUNT * gHigh * (0.5 + 6.0 * rnd));
            emis += lcol * led * (0.3 + 2.7 * max(blink, hb));
        }

        float pulse = (0.55 + 0.45 * sin(p.z * 0.9 - t * 3.0)) * (0.7 + 1.6 * AUDIO_AMOUNT * gMid);
        float band = 1.0 - smoothstep(0.03, 0.05 + px, abs(p.y - 3.6));
        float low = 1.0 - smoothstep(0.02, 0.04 + px, abs(p.y - 0.15));
        emis += neon * band * (pulse + ring * 2.0) * 2.2;
        emis += neon * low * (0.8 + ring * 2.0 + 3.0 * AUDIO_AMOUNT * gBass);
        emis += neon * exp(-abs(p.y - 3.6) * 6.0) * 0.07 * pulse;
        emis += sc * ring * 0.4;

        ao = (0.55 + 0.45 * smoothstep(0.0, 1.0, p.y))
           * (0.6 + 0.4 * smoothstep(0.0, 0.8, ROOM_H - p.y));
        shin = 50.0;
        specAmt = 0.6;
        refl = 0.14;
    }


    vec3 di = sph.xyz - p;
    float l = length(di);
    if (!isSph) {
        float occ = clamp(max(dot(n, di) / l, 0.0) / (l * l), 0.0, 1.0);
        ao *= 1.0 - 0.85 * occ;
    }


    vec3 dl, sl;
    gatherLight(p, n, rd, shin, t, sph, full && !isSph, dl, sl);

     if (isSph) {
        float amb = 0.15 + 0.85 * clamp(0.5 + 0.5 * n.y, 0.0, 1.0);
        float lit = clamp(dot(dl, vec3(0.3333)), 0.0, 1.0);
        refl = 0.16;


        float fres = 1.0 - max(dot(n, -rd), 0.0);
        float rim = pow(fres, 3.2);


        vec3 vorRim = (vor + 0.15 * sc) * rim * (0.35 + 0.75 * AUDIO_AMOUNT * gBass);


        float pump = 1.0 + AUDIO_AMOUNT * (0.35 * gBass + 0.2 * gMid);
        vec3 sphereCol = vor * (0.6 * amb + 0.4 * lit) + sl * 0.5;

        return sphereCol * pump + vorRim;
    }


    float sd2 = dot(di, di);
    dl += sc * (0.5 + 0.5 * dot(n, di / l)) * 1.2 / (1.0 + sd2 * 0.5) * 0.5;

    vec3 ambCol = mix(vec3(0.15, 0.45, 0.55), vec3(0.55, 0.2, 0.45),
                      smoothstep(-ROOM_W, ROOM_W, p.x))
                * (0.12 + 0.12 * (0.5 + 0.5 * n.y)) * (1.0 + 0.8 * AUDIO_AMOUNT * gMid);

    vec3 col = albedo * (dl * (0.4 + 0.6 * ao) + ambCol * ao);
    col += sl * specAmt * ao;
    col += emis;
    return col;
}

vec3 renderScene(vec2 fragCoord, float tt, vec3 ro, vec3 ta, float focal, float seed) {
    setupFrame(tt);

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec4 sph = vec4(gBall, 1.0);
    gFocal = focal;

    mat3 cam = setCamera(ro, ta);
    vec3 rd = cam * normalize(vec3(uv, focal));

    float dither = fract(52.9829189 * fract(dot(fragCoord + seed * 17.0,
                                                vec2(0.06711056, 0.00583715))));
    vec3 fogCol = vec3(0.012, 0.014, 0.024);

    vec3 acc = vec3(0.0);
    float w = 1.0;
    vec3 o = ro, dir = rd;
    float dist = 0.0;
    float d0 = MAX_DIST;
    bool hit0 = false;

    for (int b = ZERO; b < 2; b++) {
        vec3 n;
        vec2 hit = trace(o, dir, sph, n);
        vec3 c;
        float kR = 0.0;

        if (hit.y > 0.5) {
            vec3 p = o + dir * hit.x;
            float px = footprint(dist + hit.x, n, dir) * (b == 0 ? 1.0 : 1.5);
            float refl;
            c = renderSurface(p, n, dir, hit.y, tt, px, sph, b == 0, refl);

            if (b == 0) {
                d0 = hit.x;
                hit0 = true;
                float fres = pow(1.0 - max(dot(n, -dir), 0.0), 4.0);
                kR = (refl > 0.0) ? mix(refl, 0.5, fres) : 0.0;
            } else {
                c = mix(c, fogCol, 1.0 - exp(-0.0008 * hit.x * hit.x));
            }
            o = p + n * 0.003;
            dir = reflect(dir, n);
            dist += hit.x;
        } else {
            c = (b == 0) ? fogCol : vec3(0.01, 0.012, 0.02);
        }

        acc += w * c * (1.0 - 0.6 * kR);
        w *= kR;
        if (w <= 0.0) break;
    }

    if (hit0) acc = mix(acc, fogCol, 1.0 - exp(-0.0008 * d0 * d0));

    acc += calcVolumetrics(ro, rd, d0, tt, dither);
    return acc;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 au = texelFetch(AUDIO, ivec2(0, 0), 0);
    gBass  = pow(clamp(au.x, 0.0, 1.0), 3.0);
    gMid   = pow(clamp(au.y, 0.0, 1.0), 2.0);
    gHigh  = pow(clamp(au.z, 0.0, 1.0), 2.5);
    gTotal = clamp(au.w, 0.0, 1.0);

    int N = int(texelFetch(CAMBUF, ivec2(0, 0), 0).x + 0.5);


    if (N < 1) {
        float t = iTime;
        vec3 ball = getSpherePos(t);
        vec3 ro = ball + vec3(0.0, 1.5, -6.5);   
        vec3 ta = ball + vec3(0.0, -0.2, 4.0);   
        float focal = 1.1;

        vec3 col = renderScene(fragCoord, t, ro, ta, focal, 0.0);
        fragColor = vec4(col, 1.0);
        return;
    }


    vec3 acc = vec3(0.0);
    for (int j = ZERO; j < MAX_SAMPLES; j++) {
        if (j >= N) break;
        vec4 a = texelFetch(CAMBUF, ivec2(1 + 2 * j, 0), 0);
        vec4 b = texelFetch(CAMBUF, ivec2(2 + 2 * j, 0), 0);
        acc += renderScene(fragCoord, b.w, a.xyz, b.xyz, a.w, float(j));
    }

    fragColor = vec4(acc / float(N), 1.0);
}

// Buffer B: FFT Analysis 
// iChannel0: Audio Input
// iChannel1: Buffer B (Feedback)

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if (fragCoord.x > 1.0 || fragCoord.y > 1.0) discard;

    float bass = 0.0;
    for(int i = 0; i < 15; i++) bass += texelFetch(iChannel0, ivec2(i, 0), 0).x;
    bass /= 15.0;

    float mid = 0.0;
    for(int i = 20; i < 100; i++) mid += texelFetch(iChannel0, ivec2(i, 0), 0).x;
    mid /= 80.0;

    float high = 0.0;
    for(int i = 200; i < 400; i++) high += texelFetch(iChannel0, ivec2(i, 0), 0).x;
    high /= 200.0;

    bass = pow(bass, 1.5) * 1.5;
    mid  = pow(mid, 1.2) * 1.2;
    high = pow(high, 1.0) * 1.0;
    float total = (bass + mid + high) / 3.0;

    vec4 currentAudio = vec4(bass, mid, high, total);

    vec4 prevAudio = texelFetch(iChannel1, ivec2(0, 0), 0);

    fragColor = mix(prevAudio, currentAudio, 0.3); 
}

#define PI 3.14159265359

const float ROOM_W = 3.0;
const float ROOM_H = 5.0;
const float LS     = 8.0;

const float AUDIO_AMOUNT = 1.0;

const int   NUM_CAMS = 8;
const float HOLD  = 7.0;
const float TRANS = 1.6;
const int   MAX_SAMPLES = 6;

float hash11(float p) {
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec3 hash13(float p) {
    vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xxy + p3.yzz) * p3.zyx);
}

vec3 getSpherePos(float t) {
    float bh = abs(sin(t * 3.5)) * 1.5;
    float press = 1.0 - smoothstep(0.0, 0.45, bh);
    return vec3(0.0, 1.0 + bh - 0.14 * press, t * 4.0);
}

mat3 setCamera(in vec3 ro, in vec3 ta) {
    vec3 cw = normalize(ta - ro);
    vec3 cp = vec3(0.0, 1.0, 0.0);
    vec3 cu = normalize(cross(cw, cp));
    return mat3(cu, normalize(cross(cu, cw)), cw);
}

int camIndex(float cyc) {
    return int(mod(cyc * 3.0, float(NUM_CAMS)));
}

void getCamera(int idx, float tt, out vec3 ro, out vec3 ta, out float focal) {
    vec3 sp = getSpherePos(tt);

    if (idx == 0) {
        vec3 tg = vec3(0.0, 1.0, sp.z);
        float o = tt * 0.5;
        ro = tg + vec3(sin(o) * 2.0, 1.5, -4.5 + cos(o) * 1.5);
        ta = tg;
        focal = 1.0;
    } else if (idx == 1) {
        ro = vec3(sin(tt * 0.4) * 1.3, 0.75, sp.z + 5.0 + sin(tt * 0.3) * 0.8);
        ta = vec3(0.0, sp.y * 0.7 + 0.3, sp.z);
        focal = 0.85;
    } else if (idx == 2) {
        ro = vec3(2.3, 2.6 + 0.4 * sin(tt * 0.5), sp.z - 2.0 + 3.5 * sin(tt * 0.3));
        ta = vec3(0.0, 1.2, sp.z + 0.5);
        focal = 1.0;
    } else if (idx == 3) {
        ro = vec3(0.6 * sin(tt * 0.3), 4.2, sp.z - 2.2);
        ta = vec3(0.0, 0.8, sp.z + 0.8);
        focal = 1.0;
    } else if (idx == 4) {
        ro = vec3(1.9, 0.7, sp.z + 2.5 + sin(tt * 0.5));
        ta = vec3(0.0, 0.9, sp.z - 1.0);
        focal = 0.8;
    } else if (idx == 5) {
        ro = vec3(sin(tt * 0.25) * 0.8, 4.3, sp.z + 7.0);
        ta = vec3(0.0, 1.2, sp.z);
        focal = 0.9;
    } else if (idx == 6) {
        ro = vec3(-2.4, 1.6 + 0.5 * sin(tt * 0.4), sp.z + 8.0 * sin(tt * 0.18));
        ta = vec3(0.0, 1.2, sp.z);
        focal = 1.1;
    } else {
        ro = vec3(0.8 * sin(tt * 0.2), 2.0, sp.z - 10.0);
        ta = vec3(0.0, 1.4, sp.z);
        focal = 1.6;
    }
}

void getCameraPose(int frame,int camA, int camB, float m, float tt, float bass,
                   out vec3 ro, out vec3 ta, out float focal) {
    ro = vec3(0.0); ta = vec3(0.0); focal = 1.0;
    for (int c = frame; c < 2; c++) {
        if (c == 1 && m <= 0.0) break;
        vec3 r, tg; float f;
        getCamera(c == 0 ? camA : camB, tt, r, tg, f);
        if (c == 0) { ro = r; ta = tg; focal = f; }
        else {
            ro = mix(ro, r, m);
            ta = mix(ta, tg, m);
            focal = mix(focal, f, m);
            ro.x += sin(PI * m) * 1.6;
        }
    }
    ro.x = clamp(ro.x, -2.6, 2.6);
    ro.y = clamp(ro.y, 0.6, 4.4);

    focal -= bass * 0.07;

    float bp = mod(tt * 3.5, PI);
    ro.y -= exp(-bp * 6.0) * sin(bp * 50.0) * 0.08;
    ro += bass * 0.025 * vec3(sin(tt * 91.0), sin(tt * 77.0), 0.0);
}

// Buffer C: CAMERA DIRECTOR
// iChannel0 = Buffer B (audio)

#define ZERO (min(iFrame, 0))

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    fragColor = vec4(0.0);
    int x = int(fragCoord.x);
    if (int(fragCoord.y) != 0 || x > 2 * MAX_SAMPLES) return;

    float t = iTime;
    float P = HOLD + TRANS;
    float cyc = floor(t / P);
    float local = t - cyc * P;
    int camA = camIndex(cyc);
    int camB = camIndex(cyc + 1.0);

    float u = clamp((local - HOLD) / TRANS, 0.0, 1.0);
    float spread = 0.5 * sin(PI * u);
    int N = (local > HOLD) ? MAX_SAMPLES : 1;

    if (x == 0) {
        fragColor = vec4(float(N), sin(PI * u), u, float(camA));
        return;
    }

    int j = (x - 1) / 2;
    if (j >= N) return;

    float off = (N > 1) ? float(j) / float(N - 1) - 0.5 : 0.0;
    float uj = clamp(u + off * spread, 0.0, 1.0);
    float m = uj * uj * (3.0 - 2.0 * uj);
    float tj = t + off * spread * TRANS * 0.5;

    float bass = clamp(texelFetch(iChannel0, ivec2(0, 0), 0).x, 0.0, 1.0) * AUDIO_AMOUNT;

    vec3 ro, ta; float focal;
    getCameraPose(ZERO,camA, camB, m, tj, bass, ro, ta, focal);

    bool second = ((x - 1) - 2 * j) == 1;
    fragColor = second ? vec4(ta, tj) : vec4(ro, focal);
}

// Preserve fixed iteration counts through the canonical reserved-zero state ABI.
// A writes 15.w = 0 every frame; frame zero never reads feedback here.
// A runtime-uniform bound discourages fixed-loop replication in downstream HLSL.
float cfLoopOverride=0.;
int cfLoopBound(int count) {
    if(!(cfLoopOverride>0.)||cfLoopOverride>float(count))return count;
    return int(cfLoopOverride);
}
/*
Spring / Clamp · Torque
*/
const float PI=3.14159265358979323846;
const float TAU=6.28318530717958647692;
const vec4 THREAD=vec4(1.0,1.5,1.0,1.0); // clearance scale, pitch, starts, handedness
mat2 rot2(float a) { float c=cos(a),s=sin(a);return mat2(c,s,-s,c); }
vec2 uiPoint(vec2 p,vec2 res) { return (p-0.5*res)/min(res.x/880.0,res.y/495.0)+vec2(440,247.5); }
bool inRect(vec2 p,vec4 r) { return all(greaterThanEqual(p,r.xy))&&all(lessThan(p,r.xy+r.zw)); }
// All dimensions in mm. The spring is a finite swept wire with closed,
// ground transition turns and five middle turns (5 nominal active turns).
const float SPRING_BOTTOM=-48.0;
const float SPRING_FREE=24.0;
const float WIRE_DIAMETER=1.6;
const float SPRING_RADIUS=8.0;
// A tiny helical-skew correction makes adjacent wire tubes touch without overlap.
const float CLOSED_PITCH=WIRE_DIAMETER/sqrt(1.0-pow(WIRE_DIAMETER/(TAU*SPRING_RADIUS),2.0));
const float SPRING_SOLID=6.0*CLOSED_PITCH;
const float WASHER_THICK=1.4;
const float SEAT_Z=SPRING_BOTTOM+SPRING_FREE+WASHER_THICK;
const float MAX_COMPRESSION=SPRING_FREE-SPRING_SOLID;
const float SPRING_RATE=79000.0*pow(WIRE_DIAMETER,4.0)/(8.0*pow(2.0*SPRING_RADIUS,3.0)*5.0);
const float NUT_HEIGHT=8.0;
const float NUT_BOUND_RADIUS=9.3; // circumscribed, yaw-independent hex bound
const float GUIDE_CLEAR_Z=0.8;
const float GUIDE_RADIUS=24.0;
const float GUIDE_DOCK_Z=-12.0;
const float GUIDE_LENGTH=GUIDE_RADIUS+GUIDE_CLEAR_Z-GUIDE_DOCK_Z;
// This compact demo is a guided assembly. Once the nut clears the last
// thread, the same gesture lifts it clear, slides it sideways and lowers it
// into a visible parking cradle. Reversing retraces that handling path.
// This is an explicit handling fixture, not a claim of free-body dynamics.
vec3 guidedNutPosition(float travel,int nut) {
    vec2 direction=vec2(.8674232256,.4975710479)*(nut==0?-1.:1.);
    return vec3(direction*min(travel,GUIDE_RADIUS),GUIDE_CLEAR_Z-max(travel-GUIDE_RADIUS,0.));
}
float nutPairGap(vec4 a,vec4 b) {
    return max(length(a.xy-b.xy)-2.*NUT_BOUND_RADIUS,abs(a.z-b.z)-NUT_HEIGHT);
}
int springBearingNut(vec4 a,vec4 b) {
    bool ca=length(a.xy)<.10,cb=length(b.xy)<.10;
    if(!ca&&!cb)return -1;
    return ca&&(!cb||a.z<=b.z)?0:1;
}
float springBearingZ(vec4 a,vec4 b) {
    int nut=springBearingNut(a,b);
    return nut<0?SEAT_Z:nut==0?a.z:b.z;
}
// Shared actual-pose bounds: detached nuts are never clipped from either
// first-visible-surface picking or the primary / shadow / AO renderer rays.
void assemblyBounds(vec4 lowerPose,vec4 upperPose,out vec3 lower,out vec3 upper) {
    lower=vec3(-18.,-16.,-57.);upper=vec3(18.,16.,1.);
    lower=min(lower,min(lowerPose.xyz,upperPose.xyz)-vec3(9.5,9.5,.2));
    upper=max(upper,max(lowerPose.xyz,upperPose.xyz)+vec3(9.5,9.5,NUT_HEIGHT+.2));
}
// Fit distinct actual-component boxes within the clear stage. cam.z remains
// the user's zoom choice; cam.w is this pose-dependent safety zoom floor.
float assemblyZoomFloor(vec4 a,vec4 b,vec4 camera) {
    vec3 f=-vec3(cos(camera.x)*cos(camera.y),sin(camera.x)*cos(camera.y),sin(camera.y));
    vec3 r=normalize(cross(f,vec3(0,0,1))),u=cross(r,f);
    float distance=0.;
    for(int box=0;box<6;box++) {
        // Keep the wider support and head at their actual heights. A single
        // wide box up to the bolt tip would needlessly shrink the model.
        vec3 lo,hi;
        if(box==0){lo=vec3(-5.2,-5.2,-50.2);hi=vec3(5.2,5.2,.2);}
        else if(box==1){lo=vec3(-9.5,-9.5,-56.6);hi=vec3(9.5,9.5,-49.8);}
        else if(box==2){lo=vec3(-15.5,-13.5,-50.2);hi=vec3(15.5,13.5,-48.);}
        else if(box==3){lo=vec3(-10.7,-10.7,-48.2);hi=vec3(10.7,10.7,SEAT_Z+.2);}
        else {vec3 p=box==4?a.xyz:b.xyz;lo=p-vec3(9.5,9.5,.2);hi=p+vec3(9.5,9.5,8.2);}
        for(int corner=0;corner<8;corner++) {
            vec3 p=vec3((corner/4)==0?lo.x:hi.x,((corner/2)%2)==0?lo.y:hi.y,(corner%2)==0?lo.z:hi.z)-vec3(0,0,-25);
            float x=dot(p,r),y=dot(p,u),z=dot(p,f);
            distance=max(distance,max(abs(x)/.335,(y>=0.?y/.176:-y/.145))-z);
        }
    }
    return max(.70,distance/200.);
}
float clampCompression(float z) { return clamp(SEAT_Z-z,0.0,MAX_COMPRESSION); }
float clampForce(float d,float stiffness) { return stiffness*d; }
float clampTangent(float d,float stiffness) { return stiffness; }
// Exact button rectangles. Passive HUD text and stage pixels do not consume a drag.
int uiHit(vec2 p) {
    if(inRect(p,vec4(163,18,72,30)))return 0;
    if(inRect(p,vec4(243,18,70,30)))return 1;
    if(inRect(p,vec4(321,18,70,30)))return 2;
    if(inRect(p,vec4(399,18,70,30)))return 3;
    if(inRect(p,vec4(477,18,70,30)))return 4;
    if(inRect(p,vec4(555,18,70,30)))return 5;
    if(inRect(p,vec4(633,18,38,30)))return 6;
    if(inRect(p,vec4(679,18,38,30)))return 7;
    return -1;
}
void cameraBasis(vec4 camera,out vec3 ro,out vec3 forward,out vec3 right,out vec3 up) {
    float ca=cos(camera.x),sa=sin(camera.x),ce=cos(camera.y),se=sin(camera.y);
    vec3 target=vec3(0,0,-25);
    ro=target+200.0*max(camera.z,camera.w)*vec3(ca*ce,sa*ce,se);
    forward=normalize(target-ro);right=normalize(cross(forward,vec3(0,0,1)));up=cross(right,forward);
}
void cameraRay(vec4 camera,vec2 resolution,vec2 frag,out vec3 ro,out vec3 rd) {
    vec3 f,r,u;cameraBasis(camera,ro,f,r,u);
    float viewHeight=495.0*min(resolution.x/880.0,resolution.y/495.0);
    vec2 uv=(frag-0.5*resolution)/viewHeight;
    uv.y-=0.025; // leave a little breathing room above the control strip
    rd=normalize(f*2.5+r*uv.x+u*uv.y);
}
vec2 projectCenter(vec3 p,vec4 camera,vec2 resolution) {
    vec3 ro,f,r,u;cameraBasis(camera,ro,f,r,u);vec3 d=p-ro;
    return vec2(440,247.5)+495.0*(vec2(dot(d,r),dot(d,u))*2.5/dot(d,f)+vec2(0,.025));
}
vec2 screenMove(vec2 delta,vec4 camera,float scale) {
    vec2 right=vec2(-sin(camera.x),cos(camera.x));
    vec2 forward=-vec2(cos(camera.x),sin(camera.x));
    return (right*delta.x+forward*delta.y/max(sin(camera.y),0.25))*scale;
}
// Reduced-order 60-degree V-thread + washer Coulomb friction, in mm and N.
// Pitch diameter 9.026 mm; mu_thread=0.12, mu_bearing=0.10, mean radius=8 mm.
// Friction angle exceeds lead angle: both release thresholds are positive.
const float TORQUE_DRAG_GAIN=0.0005; // N m per logical screen pixel
const float MAX_TORQUE=0.25;        // N m, signed; positive tightens
const float RUNNING_TORQUE=0.002;   // N m, small unloaded prevailing friction
float torqueArm(bool tightening) {
    float radius=4.513,lead=THREAD.y/TAU,rise=lead/radius,friction=.12/.866025403784;
    return radius*(friction+(tightening?rise:-rise))/(1.+(tightening?-1.:1.)*friction*rise)+.10*8.;
}
float resistanceNm(float force,bool tightening) {
    return RUNNING_TORQUE+max(force,0.)*torqueArm(tightening)*.001; // N mm -> N m
}
float torqueCompression(float torque,float stiffness) {
    if(torque<=RUNNING_TORQUE)return 0.;
    float target=(torque-RUNNING_TORQUE)*1000./torqueArm(true);
    if(target>=clampForce(MAX_COMPRESSION,stiffness))return MAX_COMPRESSION;
    float lo=0.,hi=MAX_COMPRESSION;
    for(int i=0;i<18;i++){float d=.5*(lo+hi);if(clampForce(d,stiffness)<target)lo=d;else hi=d;}
    return .5*(lo+hi);
}

// Analytic ISO thread-profile implementation retained from Assembly Lab.
// Mathematical reference: mjfit's ISO profile construction, commit eee986cc087d14458337fdc195d5cf03abc6aa6d.
// https://github.com/younghyopark/mjfit/blob/eee986cc087d14458337fdc195d5cf03abc6aa6d/benchmark/thread/plugin/iso_thread_sdf.cc
float gBox3(vec3 p,vec3 h) {
    vec3 q=abs(p)-h;
    return length(max(q,0.0))+min(max(q.x,max(q.y,q.z)),0.0);
}

float gExtrude(float d,float z,float lo,float hi) {
    vec2 q=vec2(d,max(lo-z,z-hi));
    return length(max(q,0.0))+min(max(q.x,q.y),0.0);
}

float gHex(vec2 p,float inradius) {
    p=abs(p);
    return max(p.y,0.866025403784*p.x+0.5*p.y)-inradius;
}

float gPhase(float u,float center,float pitch) {
    return abs(mod(u-center+0.5*pitch,pitch)-0.5*pitch);
}

float isoBoltSection(float r,float u,float radius,float pitch,float c) {
    const float rt=1.7320508075688772;
    float core=radius-5.0*rt*pitch/16.0;
    float v=gPhase(u,5.0*pitch/8.0,pitch);
    float flank=0.5*(r-core+rt*(v-3.0*pitch/8.0)+c);
    return min(r-core,max(r-radius+0.5*c,flank));
}

float isoNutSection(float r,float u,float radius,float pitch,float c) {
    const float rt=1.7320508075688772;
    float core=radius-5.0*rt*pitch/16.0;
    float v=gPhase(u,pitch/8.0,pitch);
    float flank=0.5*(radius-r+rt*(v-7.0*pitch/16.0)+c);
    float end=v-7.0*pitch/16.0+c/rt;
    return min(radius+0.5*c-r,max(core+0.5*c-r,max(flank,end)));
}

float isoBoltRadial(float u,float radius,float pitch,float c) {
    const float rt=1.7320508075688772;
    float core=radius-5.0*rt*pitch/16.0;
    float v=gPhase(u,5.0*pitch/8.0,pitch);
    return max(core,min(radius-0.5*c,core+rt*(3.0*pitch/8.0-v)-c));
}

float isoNutRadial(float u,float radius,float pitch,float c) {
    const float rt=1.7320508075688772;
    float core=radius-5.0*rt*pitch/16.0;
    float v=gPhase(u,pitch/8.0,pitch);
    if(v>7.0*pitch/16.0-c/rt) return radius+0.5*c;
    return max(core+0.5*c,min(radius+0.5*c,radius+rt*(v-7.0*pitch/16.0)+c));
}

float gThreadPhase(vec3 p,vec4 par) {
    return p.z-par.w*par.y*par.z*atan(p.y,p.x)/TAU;
}

vec2 boltField(vec3 p,vec4 par) {
    float c=0.1*par.x;
        float r=length(p.xy),core=5.0-0.541265877365*par.y;
        float farBound=gBox3(p-vec3(0,0,-28.2),vec3(9.3,9.3,28.2));
        if(farBound>3.0) return vec2(farBound,1.0);
        float tooth=isoBoltSection(r,gThreadPhase(p,par),5.0,par.y,c)/1.035;
        float d=max(tooth,max(p.z,-p.z-48.0));
        // The lead-in removes material; its cone is distance-bounded too.
        float tipRadius=core+(5.0-core)*clamp(-p.z/0.55,0.0,1.0);
        d=max(d,(r-tipRadius)/1.85);
        float shank=gExtrude(r-5.0,p.z,-50.0,-48.0);
        float head=gExtrude(gHex(p.xy,8.0),p.z,-56.4,-50.0);
        float bevel=0.4*clamp((abs(p.z+53.2)-2.75)/0.45,0.0,1.0);
        head=max(head,(gHex(p.xy,8.0)+bevel)*0.71);
        return vec2(min(d,min(shank,head)),1.0);
}
vec2 nutField(vec3 p,vec4 par) {
    float c=0.1*par.x;
        float bound=gBox3(p-vec3(0,0,4.0),vec3(9.3,9.3,4.0));
        if(bound>2.0) return vec2(bound,4.0);
        float r=length(p.xy);
        float d=isoNutSection(r,gThreadPhase(p,par),5.0,par.y,c)/1.035;
        d=max(d,max(-p.z,p.z-8.0));
        float end=min(p.z,8.0-p.z);
        float outer=gHex(p.xy,8.0)+0.45*clamp(1.0-end/0.55,0.0,1.0);
        d=max(d,outer/1.3);
        float core=5.0-0.541265877365*par.y;
        float mouth=5.2-(5.2-core-0.5*c)*clamp(end/0.65,0.0,1.0);
        d=max(d,(mouth-r)/1.85);
        return vec2(d,4.0);
}
// Integral of the active-pitch envelope, with C1 tangent continuity.
// First/last complete turn has skew-corrected close-wound pitch (closed end).
// The middle four turns have equal pitch; two half-turn transitions are smooth.
vec3 springRise(float t) {
    float x=t-1.0, value=0.0, slope=0.0, curvature=0.0;
    if(x>0.0&&x<0.5) {value=x*x; slope=2.0*x; curvature=2.0;}
    else if(x>=0.5&&x<=4.5) {value=x-0.25; slope=1.0;}
    else if(x>4.5&&x<5.0) {float u=5.0-x;value=4.5-u*u;slope=2.0*u;curvature=-2.0;}
    else if(x>=5.0)value=4.5;
    return vec3(value,slope,curvature)/4.5;
}
// Nearest finite centerline sweep. Polar angle supplies each turn candidate;
// Newton refinement corrects the helical skew. The ground planes remove the
// original terminal caps completely, leaving planar full-turn bearing strips.
vec2 springField(vec3 p,float compression) {
    float height=SPRING_FREE-compression, extra=max(height-SPRING_SOLID,0.0);
    float rho=length(p.xy), z=p.z-SPRING_BOTTOM;
    float bound=gExtrude(abs(rho-SPRING_RADIUS)-.5*WIRE_DIAMETER,z,0.0,height);
    if(bound>1.5)return vec2(bound,7.0);
    float a=atan(p.y,p.x)/TAU; if(a<0.0)a+=1.0;
    float best=1e6;
    for(int turn=0;turn<cfLoopBound(8);turn++) {
        float t=clamp(a+float(turn),0.0,7.0);
        for(int refine=0;refine<3;refine++) {
            vec3 rise=springRise(t);
            float h=CLOSED_PITCH*t+extra*rise.x-.5*WIRE_DIAMETER;
            float hp=CLOSED_PITCH+extra*rise.y,hpp=extra*rise.z;
            float angle=TAU*t;vec2 u=vec2(cos(angle),sin(angle));
            float radialDot=dot(p.xy,u), tangentDot=dot(p.xy,vec2(-u.y,u.x));
            float derivative=-SPRING_RADIUS*TAU*tangentDot+(h-z)*hp;
            float second=SPRING_RADIUS*TAU*TAU*radialDot+hp*hp+(h-z)*hpp;
            t=clamp(t-clamp(derivative/max(second,40.0),-.18,.18),max(0.0,float(turn)-.3),min(7.0,float(turn)+1.3));
        }
        vec3 rise=springRise(t);
        vec3 center=vec3(SPRING_RADIUS*vec2(cos(TAU*t),sin(TAU*t)),CLOSED_PITCH*t+extra*rise.x-.5*WIRE_DIAMETER);
        best=min(best,length(vec3(p.xy,z)-center)-.5*WIRE_DIAMETER);
    }
    // Ground faces; finite centerline ends lie a full wire radius outside them.
    return vec2(max(best,max(-z,z-height))*.94,7.0);
}
vec2 supportField(vec3 p) {
    float plate=gBox3(p-vec3(0,0,-49.0),vec3(15.,13.,.75))-.25;
    plate=max(plate,5.25-length(p.xy));
    return vec2(plate,8.);
}
vec2 washerField(vec3 p,float nutZ) {
    float top=min(nutZ,SEAT_Z),r=length(p.xy);
    float ring=max(r-10.5,5.45-r);
    return vec2(gExtrude(ring,p.z,top-WASHER_THICK,top),9.);
}

// Match the first visible material hit. Empty background, the bolt bore, and
// surfaces hidden behind the block/washer cannot latch the torque tool.
int pickNut(vec4 pose,vec4 upperPose,vec4 camera,vec4 ui,vec2 mouse,vec2 resolution) {
    vec3 ro,rd;cameraRay(camera,resolution,mouse,ro,rd);
    vec3 lower,upper;assemblyBounds(pose,upperPose,lower,upper);
    vec3 a=(lower-ro)/(rd+vec3(1e-8)),b=(upper-ro)/(rd+vec3(1e-8));
    vec3 lo=min(a,b),hi=max(a,b);float t=max(0.,max(lo.x,max(lo.y,lo.z))),end=min(hi.x,min(hi.y,hi.z));
    float bearingZ=springBearingZ(pose,upperPose),compression=clampCompression(bearingZ);
    for(int step=0;step<200;step++) {
        if(t>end)return -1;
        vec3 p=ro+rd*t;float nearest=1e5;int material=-1;
        for(int part=0;part<cfLoopBound(6);part++) {
            vec3 q=p;float d;
            if(part==0)d=boltField(q,THREAD).x;
            else if(part<=2){vec4 nut=part==1?pose:upperPose;q-=nut.xyz;q.xy=rot2(-nut.w)*q.xy;d=nutField(q,THREAD).x;}
            else if(part==3)d=springField(q,compression).x;
            else if(part==4)d=supportField(q).x;
            else d=washerField(q,bearingZ).x;
            if(ui.w>.5&&(part==1||part==2||part==3||part==5)) {
                vec2 near=vec2(cos(camera.x),sin(camera.x)),side=vec2(-near.y,near.x);
                vec2 cutXY=part==1?p.xy-pose.xy:part==2?p.xy-upperPose.xy:p.xy;
                d=max(d,(dot(cutXY,near)-abs(dot(cutXY,side)))*.70710678);
            }
            if(d<nearest){nearest=d;material=part;}
        }
        if(nearest<max(.008,t*.00006))return material==1?0:material==2?1:-1;
        t+=max(nearest*.9,.003);
    }
    return -1;
}

// Per-nut bounds are supplied by the pair solver; neither nut can drive its neighbor.
float stLowerBound=-1000.0,stUpperBound=1000.0;
bool stSpringNut=false;
float stThreadEntrance(vec4 pose,vec4 par,float depth) {
    // At a partially overlapping lead-in the actual clipped tooth surfaces
    // decide contact. Both directions are sampled to catch a tooth entering
    // the opposing solid. Full-depth contacts below use the exact reduced
    // ISO flank inequalities instead of accumulating sample error.
    float c=0.1*par.x,P=par.y;
    float core=5.0-0.541265877365*P;
    float advance=par.w*P*par.z/TAU;
    mat2 R=rot2(pose.w),Ri=rot2(-pose.w);
    float gap=10.0;
    for(int i=0;i<cfLoopBound(12);i++) {
        float angle=TAU*(float(i)+0.31)/12.0;
        vec2 direction=vec2(cos(angle),sin(angle));
        for(int j=0;j<3;j++) {
            float z=-depth+depth*(float(j)+0.5)/3.0;
            float localZ=z-pose.z;
            float radius=isoBoltRadial(z-advance*angle,5.0,P,c);
            radius=min(radius,core+(5.0-core)*clamp(-z/0.55,0.0,1.0));
            vec2 q=Ri*(direction*radius-pose.xy);
            float qr=length(q);
            float tooth=isoNutSection(qr,localZ-advance*atan(q.y,q.x),5.0,P,c)/1.035;
            float end=min(localZ,8.0-localZ);
            float mouth=5.2-(5.2-core-0.5*c)*clamp(end/0.65,0.0,1.0);
            tooth=max(tooth,(mouth-qr)/1.85);
            tooth=max(tooth,gHex(q,8.0)/1.3);
            gap=min(gap,tooth);

            float nr=isoNutRadial(localZ-advance*angle,5.0,P,c);
            nr=max(nr,mouth);
            vec2 wp=pose.xy+R*(direction*nr);
            float wr=length(wp);
            float bolt=isoBoltSection(wr,z-advance*atan(wp.y,wp.x),5.0,P,c)/1.035;
            float tip=core+(5.0-core)*clamp(-z/0.55,0.0,1.0);
            bolt=max(bolt,(wr-tip)/1.85);
            gap=min(gap,bolt);
        }
    }
    return max(gap,-0.5*depth);
}

// Coaxial contact stage. The detached handling path is integrated separately.
vec2 stGapAndFit(vec4 pose,vec4 par) {
        float depth=max(-pose.z,0.0),c=0.1*par.x;
        float gap=pose.z;
        if(depth>0.0) {
            if(depth<1.25) gap=stThreadEntrance(pose,par,depth);
            else {
                // Exact ISO flank play: |axial phase| <= 2c/sqrt(3).
                // Phase is evaluated from the pose. It never assigns the pose.
                float lead=par.w*par.y*par.z;
                float phase=mod(-pose.z+lead*pose.w/TAU+0.5*par.y,par.y)-0.5*par.y;
                float rho=length(pose.xy);
                float core=5.0-0.541265877365*par.y;
                // Eccentricity also changes the helical phase at each wall.
                // Bound both its radial normal component and polar-angle
                // perturbation; independent radial/axial tests would miss
                // their combined penetration at the ends of the backlash.
                float phaseDrift=abs(lead)/TAU*asin(clamp(rho/core,0.0,0.99));
                float flanks=c-0.866025403784*(abs(phase)+phaseDrift)-0.5*rho;
                float radial=0.5*c-rho;
                gap=min(flanks,radial);
            }
        }
        // The unthreaded shoulder is the physical lower stop.
        gap=min(gap,pose.z+48.0);
        // Solid compression stop, never allow a coil interpenetration at the solid-height stop.
        gap=min(gap,pose.z-stLowerBound);
        gap=min(gap,stUpperBound-pose.z);
        return vec2(gap,0.0);
}

// One contact evaluator call site shared by sweep, gradients and fallback.
// Minimize spring energy minus external probe work at fixed yaw, constrained by
// the SAME thread inequalities. This analytic spring target is not a pitch lock.
// A downward force probe has a stiffness-dependent free compression equilibrium.
float stAxialTrial(vec4 pose,float stiffness,float probeForce) {
    if(!stSpringNut)return 0.0;
    float d=clampCompression(pose.z),reaction=clampForce(d,stiffness);
    if(abs(probeForce)<0.0001) return d>0.0?min(d,0.30):0.0;
    if(probeForce>0.0) return 0.30;
    float wanted=clamp(-probeForce/stiffness,0.0,MAX_COMPRESSION);
    for(int i=0;i<6;i++)wanted=clamp(wanted-(clampForce(wanted,stiffness)+probeForce)/clampTangent(wanted,stiffness),0.0,MAX_COMPRESSION);
    // The residual's sign supplies the direction of the axial body force.
    float residual=reaction+probeForce;
    float target=SEAT_Z-wanted;
    return abs(residual)<0.00001?0.0:clamp(target-pose.z,-0.30,0.30);
}
vec4 stSolve(vec4 pose,vec4 movement,bool sweep,vec4 par,int tool,float stiffness,float probeForce,
             out float finalGap,out float finalFit) {
    const float e=0.0015,a=0.0004;
    bool loading=!sweep;
    bool preloaded=stSpringNut&&clampCompression(pose.z)>0.0;
    if(loading) {movement=vec4(0,0,stAxialTrial(pose,stiffness,probeForce),0);tool=1;sweep=abs(movement.z)>0.000001;}
    float linear=length(movement.xyz);
    movement.xyz*=min(1.0,3.0/max(linear,0.0001));
    movement.w=clamp(movement.w,-1.2,1.2);
    int steps=int(clamp(ceil(max(length(movement.xyz)/(loading?0.04:0.2),abs(movement.w)/0.075)),1.0,20.0));
    vec4 stepMove=movement/float(steps);
    vec4 mobility=vec4(1.0,1.0,1.0,0.022);
    if(tool==1) mobility=vec4(0.0,0.0,1.0,0.0);
    if(tool==2) mobility=vec4(0.0,0.0,1.0,0.004);
    // 0: projection gap; 1: gradient probes; 2: admissibility;
    // 3: fallback bisection; 4: final diagnostics.
    int mode=sweep?0:4,stepIndex=0,projection=0,probe=0,bisection=0;
    vec4 previous=pose,candidate=pose+stepMove,gradient=vec4(0.0);
    vec4 query=sweep?candidate:pose;
    float baseGap=0.0,positive=0.0,lo=0.0,hi=1.0,bisectT=0.5;
    finalGap=0.0;finalFit=0.0;
    while(true) {
        vec2 sampleGap=stGapAndFit(query,par);
        if(mode==4) {
            finalGap=sampleGap.x;finalFit=sampleGap.y;
            break;
        }
        bool finishStep=false;
        if(mode==0) {
            if(sampleGap.x>=((loading||preloaded)?-0.000002:-0.00035)) mode=2;
            else {
                baseGap=sampleGap.x;probe=0;gradient=vec4(0.0);mode=1;
            }
        } else if(mode==1) {
            int axis=probe/2;
            if((probe-axis*2)==0) positive=sampleGap.x;
            else {
                float difference=positive-sampleGap.x;
                gradient[axis]=axis==3?difference*e/a:difference;
            }
            probe++;
            if(probe==8) {
                vec4 n=gradient/(2.0*e);
                float denom=dot(n*mobility,n);
                if(denom<0.00001) mode=2;
                else {
                    vec4 correction=mobility*n*((-baseGap+((loading||preloaded)?0.000002:0.00015))/denom);
                    float size=max(length(correction.xyz),abs(correction.w)*5.0);
                    candidate+=correction*min(1.0,0.8/max(size,0.0001));
                    projection++;
                    mode=projection<6?0:2;
                }
            }
        } else if(mode==2) {
            if(sampleGap.x<((loading||preloaded)?-0.000004:-0.0006)) {
                lo=0.0;hi=1.0;bisection=0;mode=3;
            } else finishStep=true;
        } else {
            if(sampleGap.x>=((loading||preloaded)?-0.000001:-0.0002)) lo=bisectT;
            else hi=bisectT;
            bisection++;
            if(bisection==14) {
                candidate=mix(previous,candidate,lo);
                finishStep=true;
            }
        }
        if(finishStep) {
            pose=candidate;stepIndex++;
            if(stepIndex<steps) {
                previous=pose;candidate=pose+stepMove;projection=0;mode=0;
            } else if(!loading) {
                // One extra axial solve, same evaluator and fixed yaw. No force
                // can auto-rotate the nut; a holding brake is assumed.
                loading=true;mobility=vec4(0,0,1,0);
                float axial=stAxialTrial(pose,stiffness,probeForce);
                if(abs(axial)>0.000001) {
                    steps=int(clamp(ceil(abs(axial)/0.04),1.0,20.0));
                    stepMove=vec4(0,0,axial/float(steps),0);stepIndex=0;
                    previous=pose;candidate=pose+stepMove;projection=0;mode=0;
                } else mode=4;
            } else mode=4;
        }
        if(mode==0 || mode==2) query=candidate;
        else if(mode==1) {
            int axis=probe/2;
            vec4 offset=vec4(0.0);
            offset[axis]=axis==3?a:e;
            query=(probe-axis*2)==0?candidate+offset:candidate-offset;
        } else if(mode==3) {
            bisectT=0.5*(lo+hi);
            query=mix(previous,candidate,bisectT);
        } else query=pose;
    }
    return pose;
}

// RGBA32F state ABI: 0 lower pose, 1 upper pose (xyz,yaw); 2 UI(reserved,unused,selected,cut);
// 3 camera; 4 previous mouse/held/captured action; 5 thread; 6 diagnostics;
// 7 demo/time/unused/version; 8 compression/load/ideal lead torque/spring rate;
// 9 reserved/zero external force/net force/energy; 10 demand/tighten/loosen/motion;
// 11 anchorXY/captured nut (1 lower, 2 upper)/target compression;
// 12 brass thresholds XY, steel thresholds ZW; 13 pair gap/contact/selected/net axial load.
// 14 independent guided travel (brass,steel), detached flags (brass,steel);
// 15 actual bearing nut (-1 none, 0 brass, 1 steel), bearing height, reserved.
// "Lower/upper" pose slots preserve color identity after a possible reorder.
vec4 stRead(int n){return texelFetch(iChannel0,ivec2(n,0),0);}
bool stKey(int n){return texelFetch(iChannel1,ivec2(n,1),0).x>.5;}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
    ivec2 cell=ivec2(fragCoord);fragColor=vec4(0);if(cell.y!=0||cell.x>=16)return;
    cfLoopOverride=iFrame==0?0.:texelFetch(iChannel0,ivec2(15,0),0).w;
    vec4 poses[2];poses[0]=stRead(0);poses[1]=stRead(1);
    vec4 ui=stRead(2),cam=stRead(3),ms=stRead(4),diag=stRead(6),opt=stRead(7),load=stRead(8),probe=stRead(9),drive=stRead(10),anchor=stRead(11),guide=stRead(14);
    bool initial=iFrame==0||opt.w<6.,reset=initial;
    if(initial)cfLoopOverride=0.;
    if(initial){ui=vec4(0);cam=vec4(-1.05,.43,1,0);ms=vec4(0,0,0,-1);opt=vec4(0,0,0,6);probe=vec4(0);anchor=vec4(0);}
    float dt=clamp(iTimeDelta,0.,.05);vec2 mouse=uiPoint(iMouse.xy,iResolution.xy);
    bool held=iMouse.z>0.,wasHeld=ms.z>.5,pressed=held&&!wasHeld;int hit=pressed?uiHit(mouse):-1;
    // Nut clicks select the target. Background input always orbits.
    // Keep the feedback layout stable, including sessions from the old controls.
    ui.x=0.;if(ms.w==1.)ms.w=2.;
    if(hit==0||stKey(84)||stKey(79))ms.w=-1.;
    if(hit==1||stKey(67))ui.w=1.-ui.w;
    if(hit==2||stKey(32)){opt.x=1.-opt.x;opt.y=0.;ui.z=0.;}
    if(hit==3||stKey(82))reset=true;
    if(hit==6)cam.z=min(1.4,cam.z*1.1);if(hit==7)cam.z=max(.7,cam.z/1.1);
    if(reset){ui.xz=vec2(0);poses[0]=vec4(0,0,-21,0);poses[1]=vec4(0,0,-10.5,0);ms.w=-1.;opt.xy=vec2(0);diag=vec4(0);probe=vec4(0);anchor=vec4(0);guide=vec4(0);}
    if(pressed&&!reset){
        bool scene=hit<0;
        int nut=scene?pickNut(poses[0],poses[1],cam,ui,iMouse.xy,iResolution.xy):-1;
        ms.w=nut>=0?0.:scene?2.:hit==4?4.:hit==5?5.:-1.;
        anchor=vec4(mouse,float(nut+1),0.);probe.x=0.;
        if(nut>=0)ui.z=float(nut);
        if(ms.w>=0.)opt.x=0.;
    }
    bool manipulate=held&&ms.w>=0.;int activeTool=int(ms.w+.5),selected=int(ui.z+.5);float demand=0.,externalForce=0.;
    if(manipulate&&!reset){
        vec2 delta=mouse-ms.xy;
        if(activeTool==0)demand=clamp((anchor.x-mouse.x)*TORQUE_DRAG_GAIN,-MAX_TORQUE,MAX_TORQUE);
        if(activeTool==2&&wasHeld){cam.x-=delta.x*.009;cam.y=clamp(cam.y+delta.y*.006,.18,1.15);}
        if(activeTool==4||activeTool==5)demand=activeTool==4?.070:-.070;
    }
    if(opt.x>.5&&!manipulate&&!reset){
        float phase=mod(opt.y,24.);demand=phase<10.?.070:phase<12.?0.:phase<22.&&poses[0].z< -21.?-.070:0.;opt.y+=dt;selected=0;ui.z=0.;
    }
    float stiffness=SPRING_RATE;
    int bearing=springBearingNut(poses[0],poses[1]);
