// into a visible parking cradle. Reversing retraces that handling path.
// This is an explicit handling fixture, not a claim of free-body dynamics.
vec3 guidedNutPosition(float travel,int nut) {
    vec2 direction=vec2(.8674232256,.4975710479)*(nut==0?-1.:1.);
