float assemblyZoomFloor(vec4 a,vec4 b,vec4 camera) {
    vec3 f=-vec3(cos(camera.x)*cos(camera.y),sin(camera.x)*cos(camera.y),sin(camera.y));
    vec3 r=normalize(cross(f,vec3(0,0,1))),u=cross(r,f);
