// Small analytic studio: broad cards illuminate metal through reflections,
// while a dark gap between cards keeps the hex flats and round wire legible.
float rfSoftbox(vec3 direction,vec3 facing,vec3 tangent,vec2 extent,float blur) {
    vec3 bitangent=cross(facing,tangent);
    float den=dot(direction,facing);
    vec2 p=vec2(dot(direction,tangent),dot(direction,bitangent))/max(den,0.03);
    vec2 q=abs(p)-extent;
    float d=length(max(q,0.0))+min(max(q.x,q.y),0.0);
    return (1.0-smoothstep(-blur,blur,d))*smoothstep(0.0,0.1,den);
