vec3 rfEnvironment(vec3 p,vec3 direction,float roughness) {
    // Box/sphere-projected studio lighting gives broad metal flats a real
    // positional reflection gradient rather than one solid color per face.
    vec3 studioPoint=p-vec3(0,0,-25.);
    float along=dot(studioPoint,direction);
    float travel=-along+sqrt(max(along*along+12100.-dot(studioPoint,studioPoint),0.));
    direction=normalize(studioPoint+direction*travel);
    float sky=smoothstep(-0.5,0.8,direction.z);
    vec3 col=mix(vec3(.028,.032,.040),vec3(.075,.086,.11),sky);
    float blur=.055+roughness*.48;
    // Tall front-left softbox reaches below the horizon: a vertical metal
    // face viewed from above reflects the lower half of a studio light.
