    else if(id<3.5){base=vec3(.61,.64,.68);rough=.23;}
    else if(id<6.){base=surface.z<1.5?vec3(.78,.53,.23):vec3(.61,.64,.68);rough=.36;}
    else if(id<7.5||id>9.5){base=vec3(.54,.57,.61);rough=id>9.5?.38:.19;}
    else if(id<8.5){base=vec3(.28,.32,.36);rough=.40;}
