        float ring=1.-smoothstep(.7,1.5,abs(length(p-anchor.xy)-4.));color=mix(color,accent,ring*.8);
        color=mix(color,vec3(.045,.075,.085),panel(p,vec4(origin,166,54),7.)*.96);
        label(p,origin+vec2(10,32),14.,TXT_DRIVE,muted,code,glyph,size,ink);
        numberLabel(p,origin+vec2(8,6),24.,drive.x,3,true,accent,code,glyph,size,ink);
        label(p,origin+vec2(123,9),20.,TXT_NM,bright,code,glyph,size,ink);
    }
    if(code!=32){
        // vflip=false: atlas rows and glyph q.y both increase from PNG top.
        vec2 uv=(vec2(float(code%16),float(code/16))+clamp(glyph,vec2(.5/64.),vec2(1.-.5/64.)))/16.;
        float distance=textureLod(iChannel1,uv,0.).a-(.5+1./256.);
        float coverage=1.-smoothstep(-.55/size,.55/size,distance);
        color=mix(color,ink,coverage);
    }
    return color;
}

vec3 displayMap(vec3 color) {
    color=max(color,vec3(0));color=clamp((color*(2.51*color+.03))/(color*(2.43*color+.59)+.14),0.,1.);
    return pow(color,vec3(1./2.2));
}
vec3 renderScene(vec2 fragCoord) {
    ivec2 pixel=ivec2(fragCoord);if(pixel.y==0&&pixel.x<5)pixel.y=1;
    vec4 center=texelFetch(iChannel2,pixel,0);vec3 color=center.rgb;
    {
        // Four-sample reconstruction uses the same bounded 5x5 footprint.
        // Matching part, depth and normal reject many geometric boundaries.
        // Full normalized reconstruction suppresses the fixed 2x2 lobe pattern.
        // This is a spatial low-pass tradeoff, including reflected silhouettes;
        // primary guides cannot identify all secondary reflected boundaries.
        vec3 normal=unpackNormal(center.a);float depth=unpackDepth(center.a),part=unpackPart(center.a);
        vec3 total=vec3(0);float weight=0.;
        for(int y=-2;y<=2;y++)for(int x=-2;x<=2;x++) {
            ivec2 q=clamp(pixel+ivec2(x,y),ivec2(0),ivec2(iResolution.xy)-1);if(q.y==0&&q.x<5)continue;vec4 s=texelFetch(iChannel2,q,0);
            float wn=pow(max(dot(normal,unpackNormal(s.a)),0.),48.);
            float wd=1.-smoothstep(.5,1.5,abs(depth-unpackDepth(s.a)));
            float w=exp(-float(x*x+y*y)*.45)*wn*wd*(part==unpackPart(s.a)?1.:0.);
            total+=s.rgb*w;weight+=w;
        }
        color=mix(center.rgb,total/max(weight,.001),1.);
    }
    color=displayMap(color);
    vec2 v=fragCoord/iResolution.xy-.5;color*=1.-.12*dot(v,v);
    return color;
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){vec3 col=renderScene(fragCoord);col=drawHUD(col,uiPoint(fragCoord,iResolution.xy));fragColor=vec4(col,1);}

// Vignetting is an effect caused by composite lenses whereby the image appears darker around the edges.
// Despite being an artefact of lens design, it is often applied deliberately as an artistic effect to 
// frame the image and draw the eye inward toward the center. 
float Vignette(in vec2 fragCoord)
{
    #define kVignetteStrength         0.5             // The strength of the vignette effect
    #define kVignetteScale            0.6            // The scale of the vignette effect
    #define kVignetteExponent         3.0             // The rate of attenuation of the vignette effect

    vec2 uv = fragCoord / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y) + 0.5;     

    float x = 2.0 * (uv.x - 0.5);
    float y = 2.0 * (uv.y - 0.5);

    float dist = sqrt(x*x + y*y) / kRoot2;

    return mix(1.0, max(0.0, 1.0 - pow(dist * kVignetteScale, kVignetteExponent)), kVignetteStrength);
}

void mainImage( out vec4 rgba, in vec2 xy )
{
    SetGlobals(xy, iResolution.xy, iTime); 
    PCGInitialise(HashOf(uint(iFrame)));

    vec3 rgb = kZero;

    if(kApplyBloom) { rgb = SeparableBlurUp(ivec2(xy), ivec2(iResolution.xy), iChannel0); }


    // Composite
    rgb += texelFetch(iChannel1, ivec2(xy) / kScreenDownsample, 0).xyz * 0.6;     
    rgb = saturate(rgb);
    rgb = pow(rgb, vec3(0.8));
    rgb = mix(kOne * 0.1, kOne * 0.9, rgb);
    rgb *= Vignette(xy);

    rgb = saturate(rgb);

    rgba.xyz = rgb;    
    rgba.w = 1.0;
}

