vec2 Rotate( const in vec2 vPos, const in float t )
{
    float s = sin(t);
    float c = cos(t);

    return vec2( c * vPos.x + s * vPos.y, -s * vPos.x + c * vPos.y);
}

vec3 RotX( const in vec3 vPos, float t )
{
    vec3 result;
    result.x = vPos.x;
  	result.yz = Rotate( vPos.yz, t );
