ivec2 offsetVehicleWheel1 = ivec2( 7.0, 0.0 );
ivec2 offsetVehicleWheel2 = ivec2( 9.0, 0.0 );
ivec2 offsetVehicleWheel3 = ivec2( 11.0, 0.0 );

