void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   
    float val = 0.;

   	vec2 uv = vec2(fragCoord.x, iResolution.y - fragCoord.y);
   	vec2 uvT = vec2(80, 24) * FONT_SIZE * uv / iResolution.xy;
   	vec2 uvG = floor(ROWCOLS * uv / iResolution.xy);

    // Switch between 3 "programs"
    float prog = sin(iTime*0.5);
    if(prog < -0.1)
    	val = somePlasma(fragCoord.xy);
    else if(prog < 0.1)
    	val = rand(uvG * iTime) * 17.;
    else
    	val = textLines(uvG);
	fragColor = vt220Font(uvT - uvG * FONT_SIZE, val) * PHOSPHOR_COL;
}

#define PHOSPHOR_COL vec4(0.2, 1.0, 0.2, 0.)

precision highp float;

float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

//Motion blur from mu6k: https://www.shadertoy.com/view/lsyXRK

vec2 totex(vec2 p)
{
    p.x=p.x*iResolution.y/iResolution.x+0.5;
    p.y+=0.5;
    return p; 
}

vec3 sample_color(vec2 p)
{
    return texture(iChannel2, totex(p)).xyz;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
	vec2 p = (fragCoord.xy - iResolution.xy*.5) / iResolution.yy;

    if (abs(p.y)>.41) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec4 fb = texture(iChannel2, uv);

    float amp =1./fb.w*0.1;
    vec4 noise = texture(iChannel0, (fragCoord+floor(iTime*vec2(12.0,56.0)))/64.0);

   	vec3 col = vec3(0.0);
    col += sample_color(p*((noise.x+2.0)*amp+1.0));
    col += sample_color(p*((noise.y+1.0)*amp+1.0));
    col +=sample_color(p*((noise.z+0.0)*amp+1.0));
    col += sample_color(p*((noise.w-1.0)*amp+1.0));
    col += sample_color( p*((noise.x-2.0)*amp+1.0));
    col *= 0.2;
    col.y*=1.2;
    col=pow(clamp(col,0.0,1.0),vec3(0.45)); 
    col=mix(col, vec3(dot(col, vec3(0.33))), -0.5);

    fragColor = vec4(col, 1.0);
}

