void tbvPaint(inout vec3 c,vec3 ink,float d) { c=mix(c,ink,tbvCover(d)); }

// Repeated controls use arithmetic placement. There are no geometry arrays.
int tbvWhite(int i) { return int((0xcb975420u>>(uint(clamp(i,0,7))*4u))&15u); }
int tbvBlack(int i) { return int((0x000a8631u>>(uint(clamp(i,0,4))*4u))&15u); }
float tbvBlackX(int i) { return 320.0+68.0*float(i+(i>=2?1:0)); }
vec4 tbvKnob(int i) {
    if(i<6)return vec4(347.0+90.0*float(i),61,27,34);
    if(i==6)return vec4(163,211,44,48);
    if(i==7)return vec4(347,213,45,42);
    if(i==8)return vec4(530,216,44,42);
    return vec4(1045,217,46,49);
}
vec4 tbvButton(int i) {
    if(i<8)return vec4(286.0+68.0*float(i),453,12,23);
    if(i<13)return vec4(tbvBlackX(i-8),369,11,23);
    if(i>=17&&i<=20)return vec4(830.0+68.0*float(i-17),454,11,23);
    if(i==13)return vec4(68,362,23,11);
    if(i==14)return vec4(68,451,35,24);
    if(i==15)return vec4(188,362,23,11);
    if(i==16)return vec4(159,453,10,23);
    if(i==21)return vec4(1026,354,23,11);
    if(i==22)return vec4(1130,378,23,11);
    if(i==23)return vec4(1130,464,35,23);
    return vec4(1130,317,10,7);
}
int tbvNearKnob(vec2 p) {
    if(p.y<134.0)return clamp(int(floor((p.x-347.0)/90.0+.5)),0,5);
    return p.x<255.0?6:p.x<438.5?7:p.x<787.5?8:9;
}
int tbvNearButton(vec2 p) {
    if(p.y<415.0) {
        if(p.x<128.0)return 13;
        if(p.x<254.0)return 15;
        if(p.x<798.0) {
            int j=int(floor((p.x-320.0)/68.0+.5));
            if(j<0||j>5||j==2)return -1;
            return 8+j-(j>=3?1:0);
        }
        if(p.x<1076.0)return 21;
        return p.y<345.0?24:22;
    }
    if(p.x<220.0)return p.x<120.0?14:16;
    if(p.x>1076.0)return 23;
    int j=clamp(int(floor((p.x-286.0)/68.0+.5)),0,11);
    return j<8?j:j+9;
}

float tbvKnobValue(int i) {
    if(i==0)return clamp(.5+TB_TUNING/24.0,0.0,1.0);
    if(i==1)return tbvCut; if(i==2)return tbvRes;
    if(i==3)return tbvEnv; if(i==4)return tbvDecay;
    if(i==5)return tbvAccentKnob;
    if(i==6)return clamp(log2(BPM/40.0)/log2(7.5),0.0,1.0);
    if(i==7)return .16+.68*float(tbvPattern)/float(max(NUM_PATTERNS-1,1));
    if(i==8)return .67;
    return TBV_VOLUME;
}
float tbvButtonOn(int i) {
    if(i<8)return tbvPitch==tbvWhite(i)?tbvNotePulse:0.0;
    if(i<13)return tbvPitch==tbvBlack(i-8)?tbvNotePulse:0.0;
    if(i==17)return tbvGate*(1.0-float(tbvOctave))*.3;
    if(i==18)return tbvGate*float(tbvOctave);
    if(i==19)return tbvGate*tbvAccent;
    if(i==20)return tbvGate*tbvSlide;
    return 0.0;
}

struct TBVHit { float t;vec3 n;int material;int id; };
void tbvStore(float t,vec3 n,int material,int id,inout TBVHit h) {
    if(t>0.0&&t<h.t){h.t=t;h.n=n;h.material=material;h.id=id;}
}

// Three vector slab tests describe a chamfered box: axis planes and the
// pairwise +/- diagonal planes. There is no full-scene distance march.
void tbvSlab(vec3 o,vec3 d,vec3 b,out float tn,out float tf,out vec3 n) {
    vec3 inv=sign(d+1e-12)/max(abs(d),vec3(1e-9));
    vec3 a=(-b-o)*inv,c=(b-o)*inv;
    vec3 lo=min(a,c),hi=max(a,c);
    tn=max(lo.x,max(lo.y,lo.z));tf=min(hi.x,min(hi.y,hi.z));
    n=vec3(0);
    if(lo.x>=lo.y&&lo.x>=lo.z)n.x=-sign(d.x);
    else if(lo.y>=lo.z)n.y=-sign(d.y);else n.z=-sign(d.z);
}
void tbvChamferHit(vec3 o,vec3 d,vec3 b,float bevel,
                   int material,int id,mat2 turn,inout TBVHit h) {
    float tn,tf,u,v;vec3 n,m;
    tbvSlab(o,d,b,tn,tf,n);
    if(tn>h.t||tf<max(tn,0.0))return;
    tbvSlab(vec3(o.x+o.y,o.x+o.z,o.y+o.z),
            vec3(d.x+d.y,d.x+d.z,d.y+d.z),
            vec3(b.x+b.y,b.x+b.z,b.y+b.z)-bevel,u,v,m);
    tf=min(tf,v);if(u>tn){tn=u;n=vec3(m.x+m.y,m.x+m.z,m.y+m.z)*.70710678;}
    tbvSlab(vec3(o.x-o.y,o.x-o.z,o.y-o.z),
            vec3(d.x-d.y,d.x-d.z,d.y-d.z),
            vec3(b.x+b.y,b.x+b.z,b.y+b.z)-bevel,u,v,m);
    tf=min(tf,v);if(u>tn){tn=u;n=vec3(m.x+m.y,-m.x+m.z,-m.y-m.z)*.70710678;}
    if(tf>=max(tn,0.0)) { n.xy=turn*n.xy;tbvStore(tn,n,material,id,h); }
}

void tbvConeHit(vec3 o,vec3 d,float z0,float z1,float r0,float r1,
                int sideMat,int capMat,int id,inout TBVHit h) {
    float k=(r1-r0)/(z1-z0),r=r0+k*(o.z-z0);
    float a=dot(d.xy,d.xy)-k*k*d.z*d.z;
    float b=dot(o.xy,d.xy)-r*k*d.z;
    float c=dot(o.xy,o.xy)-r*r;
    float disc=b*b-a*c;
    if(disc>=0.0&&abs(a)>1e-9) {
        vec2 roots=(-b+vec2(-1,1)*sqrt(disc))/a;
        float t=min(roots.x,roots.y),z=o.z+t*d.z;
        if(t>0.0&&z>=z0&&z<=z1) {
            vec2 p=o.xy+t*d.xy;
            tbvStore(t,normalize(vec3(p,-(r0+k*(z-z0))*k)),sideMat,id,h);
        }
        t=max(roots.x,roots.y);z=o.z+t*d.z;
        if(t>0.0&&z>=z0&&z<=z1) {
            vec2 p=o.xy+t*d.xy;
            tbvStore(t,normalize(vec3(p,-(r0+k*(z-z0))*k)),sideMat,id,h);
        }
    }
    float t=(z1-o.z)/d.z;
    if(t>0.0&&dot(o.xy+t*d.xy,o.xy+t*d.xy)<=r1*r1)
        tbvStore(t,vec3(0,0,1),capMat,id,h);
}

TBVHit tbvTrace(vec3 ro,vec3 rd) {
    TBVHit h=TBVHit(1e20,vec3(0,0,1),-1,-1);
    tbvChamferHit(ro-vec3(0,0,-24),rd,vec3(600,280,24),4.0,0,-1,mat2(1),h);
    vec2 pp=ro.xy+rd.xy*((24.0-ro.z)/rd.z);
    if(abs(pp.x)>620.0||abs(pp.y)>310.0)return h;
    vec2 panel=tbvPanelPoint(pp);
    // With the bounded viewing angles, a ray can reach at most one control
    // in either layout. This is a spatial lookup, not a loop over objects.
    if(panel.y<290.0) {
        int i=tbvNearKnob(panel);vec4 k=tbvKnob(i);
        vec2 center=tbvWorldPoint(k.xy);
        if(length(pp-center)<k.z+60.0) {
            vec3 o=ro-vec3(center,0);
            tbvConeHit(o,rd,.5,3.0,k.z+3.0,k.z+3.0,5,5,i,h);
            tbvConeHit(o,rd,3.0,k.w-3.0,k.z,k.z*.81,1,2,i,h);
            tbvConeHit(o,rd,k.w-3.0,k.w,k.z*.81,k.z*.76,2,2,i,h);
            if(i==7||i==8) {
                float a=-2.35*(tbvKnobValue(i)*2.0-1.0);
                mat2 r=tbvRot(a),ir=transpose(r);
                vec3 oo=o-vec3(0,0,k.w+3.0),dd=rd;
                oo.xy=ir*oo.xy;dd.xy=ir*dd.xy;
                tbvChamferHit(oo,dd,vec3(k.z*.75,k.z*.31,8.0),3.0,6,i,r,h);
            }
        }
    } else {
        int i=tbvNearButton(panel);
        if(i>=0) {
            vec4 k=tbvButton(i);vec2 center=tbvWorldPoint(k.xy);
            if(all(lessThan(abs(pp-center),k.zw+vec2(28)))) {
                vec3 o=ro-vec3(center,4.0);
                tbvChamferHit(o,rd,vec3(k.zw+2.0,4.0),1.6,3,i,mat2(1),h);
                float push=2.7*tbvButtonOn(i);
                o=ro-vec3(center,11.0-push);
                tbvChamferHit(o,rd,vec3(k.zw,6.0),2.2,4,i,mat2(1),h);
            }
        }
    }
    return h;
}

vec3 tbvLighting(vec3 base,vec3 n,vec3 v,float rough,float metal) {
    const vec3 l=vec3(-.444444,.666667,.598352);
    const vec3 l2=vec3(.819232,.201,+.53688);
    vec3 h=normalize(l+v),h2=normalize(l2+v);
    float nd=max(dot(n,l),0.0),nd2=max(dot(n,l2),0.0);
    float f=.035+.965*pow(1.0-max(dot(n,v),0.0),5.0);
    float sh=exp2(mix(8.2,3.5,rough));
    float spec=pow(max(dot(n,h),0.0),sh);
    float spec2=pow(max(dot(n,h2),0.0),sh*.72);
    vec3 light=vec3(.25+.25*max(n.z,0.0));
    light+=vec3(1.06,1.02,.94)*nd*.58;
    light+=vec3(.72,.84,1.03)*nd2*.18;
    vec3 c=base*light;
    vec3 reflectance=mix(vec3(.18+f*.4),mix(vec3(.62),base,.32),metal);
    c+=reflectance*(vec3(1.14,1.06,.93)*spec*.78+vec3(.67,.83,1.0)*spec2*.40);
    c+=reflectance*pow(max(dot(n,normalize(vec3(.0,-.95,.4)+v)),0.0),48.0)*.14;
    return c;
}

void tbvLEDLenses(inout vec3 c,vec2 p) {
    vec2 center;float on=0.0;
    if(p.y<371.0) {
        if(p.x<250.0) {center=vec2(189,329);on=.46;}
        else if(p.x<780.0) {
            int j=int(floor((p.x-320.0)/68.0+.5));
            if(j<0||j>5||j==2)return;
            int i=j-(j>=3?1:0);
            center=vec2(tbvBlackX(i),329);on=tbvPitch==tbvBlack(i)?tbvNotePulse:0.0;
        } else {center=vec2(936,333);on=.18+.60*tbvNotePulse;}
    } else {
        if(p.x<145.0) {center=vec2(66,402);on=.65+.35*exp(-fract(tbvTime*BPM/60.0)*9.0);}
        else if(p.x<256.0) {center=vec2(227,406);on=.38;}
        else {
            int i=clamp(int(floor((p.x-286.0)/68.0+.5)),0,11);
            center=vec2(286.0+68.0*float(i),i<8?410.0:411.0);
            on=i<8?(tbvPitch==tbvWhite(i)?tbvNotePulse:0.0):tbvButtonOn(i+9);
        }
    }
    vec2 q=p-center;float d2=dot(q,q);
    if(d2>1600.0)return;
    vec3 bleed=vec3(1.0,.021,.004)*on*TBV_LED_GAIN*
               (.46*exp(-d2/57.0)+.07*exp(-d2/380.0));
    if(d2>100.0){c+=bleed;return;}
    float d=sqrt(d2);
    tbvPaint(c,vec3(.13,.135,.13),d-6.2);
    tbvPaint(c,vec3(.015,.009,.008),d-5.3);
    vec3 lens=vec3(.11,.005,.004)*(1.0+.5*max(-q.y/5.0,0.0));
    lens+=vec3(3.2,.060,.016)*on*TBV_LED_GAIN;
    lens+=vec3(.42,.26,.21)*exp(-dot(q-vec2(-1.3,-1.7),q-vec2(-1.3,-1.7))/1.9);
    tbvPaint(c,lens,d-4.1);
    c+=bleed;
}

void tbvKnobMaterial(vec3 p,inout vec3 n,int id,int material,
                     out vec3 base,out float rough,out float metal) {
    vec4 k=tbvKnob(id);vec2 q=p.xy-tbvWorldPoint(k.xy);
    float angle=atan(q.y,q.x),rad=length(q)/k.z;
    if(material==1) {
        float frequency=id<6?52.0:76.0;
        float ribFilter=exp(-.14*pow(frequency*tbvAA/max(length(q),1.0),2.0));
        float ribs=sin(angle*frequency)*ribFilter;
        vec2 tangent=vec2(-n.y,n.x);
        n=normalize(n+vec3(tangent*.12*cos(angle*frequency)*ribFilter,0));
        base=vec3(.052,.052,.043)*(.84+.22*ribs);
        base*=1.0-.24*exp(-(p.z-3.0)/4.0);
        rough=.44;metal=.1;
    } else if(material==5) {
        base=vec3(.31,.32,.30);rough=.24;metal=.85;
    } else {
        base=vec3(.225,.240,.222);rough=.31;metal=.86;
        if(material==6)base=vec3(.34,.355,.333);
        if(n.z>.9&&material!=6) {
            n=normalize(vec3(q/k.z*.28,1.0));
            float machining=sin(length(q)*1.65)*exp(-tbvAA*tbvAA*.28);
            base*=1.0+.045*machining;
            float brush=.13*cos(angle-1.0)+.18*pow(abs(sin(angle+.4)),12.0);
            base+=brush*smoothstep(.03,.55,rad);
        }
#if TBV_GRAIN
        base+=(tbvHash(floor(p.xy*2.))-.5)*.016;
#endif
        // Painted pointer, rather than an emissive strip across the whole cap.
        if(material!=6&&id!=7&&id!=8) {
            float a=2.35*(tbvKnobValue(id)*2.0-1.0);
            vec2 dir=vec2(sin(a),cos(a));
            float mark=tbvSeg(q,dir*k.z*.49,dir*k.z*.73)-1.45;
            if(n.z>.7)tbvPaint(base,vec3(.90,.915,.89),mark);
            if(rad>.755)base*=.7;
        }
    }
}

vec3 tbvFloor(vec3 p,vec3 view) {
    vec2 q=p.xy;
    float pool=exp(-dot(q/vec2(1040,680),q/vec2(1040,680)));
    vec3 c=vec3(.009,.012,.015)+vec3(.019,.022,.024)*pool;
#if TBV_GRAIN
    float n=tbvHash(floor(q*1.2))-.5;
    c+=n*.0025*pool;
#endif
    float shadow=tbvRoundBox(q-vec2(26,-40),vec2(597,272),16.0);
    c*=1.0-.74*(1.0-smoothstep(-35.,79.,shadow));
    float contact=tbvRoundBox(q-vec2(4,-5),vec2(580,258),14.0);
    c*=1.0-.67*(1.0-smoothstep(-9.,26.,contact));
    c+=vec3(.033,.024,.015)*exp(-dot((q-vec2(-635,90))/vec2(160,480),(q-vec2(-635,90))/vec2(160,480)));
    return c;
}

vec3 tbvToneMap(vec3 c) {
    c=max(c,0.0);
    c=(c*(2.51*c+.03))/(c*(2.43*c+.59)+.14);
    return pow(clamp(c,0.0,1.0),vec3(1.0/2.2));
}

float tbvDigit(vec2 p,int n) {
    uint m=n==0?63u:n==1?6u:n==2?91u:n==3?79u:n==4?102u:
           n==5?109u:n==6?125u:n==7?7u:n==8?127u:111u;
    float y=clamp(floor(p.y*2.0+.5),0.0,2.0)*.5;
    int hb=y<.25?3:y<.75?6:0;
    float dh=tbvBox2(p-vec2(.35,y),vec2(.25,.025));
    bool left=p.x<.35,top=p.y>.5;
    int vb=left?(top?5:4):(top?1:2);
    float dv=tbvBox2(p-vec2(left?.08:.62,top?.75:.25),vec2(.025,.22));
    return min(((m>>uint(hb))&1u)!=0u?dh:9.0,((m>>uint(vb))&1u)!=0u?dv:9.0);
}

vec3 tbvTransport(vec3 c,vec2 fragCoord) {
#if TBV_TRANSPORT
    float scale=min(iResolution.x/1040.,iResolution.y/610.);
    vec2 p=(fragCoord-vec2(iResolution.x*.5,iResolution.y*.085))/scale;
    if(abs(p.y)>24.0||abs(p.x)>450.0)return c;
    float oldAA=tbvAA;tbvAA=1.0/scale;
    int cell=clamp(int(floor((p.x+320.)/40.)),0,15);
    float x=-300.+40.*float(cell);
    vec2 q=p-vec2(x,0);
    int pk=PATTERNS[tbvPattern*PAT_LEN+wrap16(cell)];
    float gate=float((pk>>5)&1),accent=float((pk>>7)&1),slide=float((pk>>6)&1);
    float cursorOn=cell==tbvStep?1.0:0.0;
    float d=tbvRoundBox(q,vec2(15,3),1.4);
    if(abs(p.x)<321.0) {
        tbvPaint(c,mix(vec3(.064,.074,.076),vec3(.20,.22,.21),gate),d);
        if(cursorOn>.5) {
            tbvPaint(c,gate>.5?vec3(.83,.12,.042):vec3(.38,.41,.40),d);
            c+=vec3(.11,.009,.002)*exp(-dot(q/vec2(18,8),q/vec2(18,8)))*gate;
        }
        if(accent>.5)tbvPaint(c,vec3(.35,.13,.065),length(q-vec2(0,10))-1.25);
        if(slide>.5)tbvPaint(c,vec3(.30,.33,.30),tbvSeg(q,vec2(10,10),vec2(17,10))-.5);
    }
    // Four pattern banks to the left; tempo is printed to the right.
    if(p.x< -345.0) {
        int b=clamp(int(floor((p.x+436.)/20.)),0,3);
        vec2 z=p-vec2(-426.+20.*float(b),0);
        tbvPaint(c,b==tbvPattern?vec3(.68,.25,.10):vec3(.10,.12,.12),
                  tbvRoundBox(z,vec2(5,5),1.1));
    }
    if(p.x>351.&&p.x<414.) {
        int b=clamp(int(floor((p.x-356.)/15.)),0,2);
        int bpm=int(BPM+.5),digit=b==0?bpm/100:b==1?(bpm/10)%10:bpm%10;
        vec2 z=vec2((p.x-356.-float(b)*15.)/13.,(p.y+6.5)/13.);
        float sd=tbvDigit(z,digit)*13.;
        tbvPaint(c,vec3(.27,.31,.31),sd);
    }
    tbvAA=oldAA;
#endif
    return c;
}

void mainImage(out vec4 fragColor,in vec2 fragCoord) {
    tbvTime=max(iTime,0.0);
    tbvPattern=patternIndex(tbvTime);tbvStep=curPatStep(tbvTime);
    tbvPhase=fract(tbvTime/STEP_DUR);
    int event=PATTERNS[tbvPattern*PAT_LEN+tbvStep];
    tbvGate=float((event>>5)&1);tbvSlide=float((event>>6)&1);tbvAccent=float((event>>7)&1);
    tbvOctave=(event>>4)&1;
    int pitch=event&15;tbvPitch=(pitch%12==0&&tbvOctave>0)?12:pitch%12;
    tbvNotePulse=tbvGate*(.52+.48*exp(-tbvPhase*5.0));
    resolvePanel(tbvTime,tbvWave,tbvCut,tbvRes,tbvEnv,tbvDecay,tbvAccentKnob,tbvDist,tbvTone);

    float yaw=.024,pitchView=.39;
#if TBV_AUTO_CAMERA
    vec2 autoDrag=.42*vec2(cos(tbvTime*.315),sin(tbvTime*.315));
    yaw+=autoDrag.x*.48;
    pitchView=clamp(pitchView-autoDrag.y*.20,.20,.58);
#endif
    if(iMouse.z>0.0) {
        vec2 drag=iMouse.xy/iResolution.xy-.5;
        yaw+=clamp(drag.x,-.5,.5)*.50;
        pitchView=clamp(pitchView-drag.y*.40,.17,.64);
    }
    float distanceToCenter=2220.;
    vec3 ro=vec3(sin(yaw)*cos(pitchView),-sin(pitchView),cos(yaw)*cos(pitchView))*distanceToCenter;
    vec3 target=vec3(0,-6,0);
#if TBV_AUTO_CAMERA
    target.xy+=vec2(18.0*sin(tbvTime*.071),10.0*cos(tbvTime*.115));
#endif
    vec3 fw=normalize(target-ro),right=normalize(cross(fw,vec3(0,1,0))),up=cross(right,fw);
    float aspect=iResolution.x/iResolution.y;
    float span=max(705.0,1370.0/aspect);
    float lens=length(target-ro)/span;
    vec2 uv=(fragCoord-.5*iResolution.xy)/iResolution.y;
    uv.y+=.005;
    vec3 rd=normalize(fw*lens+right*uv.x+up*uv.y);
    tbvAA=span/iResolution.y;
    float floorT=(-55.-ro.z)/rd.z;
    vec3 floorPoint=ro+rd*floorT;
    vec3 c=tbvFloor(floorPoint,-rd);
    TBVHit hit=tbvTrace(ro,rd);
    if(hit.material>=0) {
        vec3 p=ro+rd*hit.t,n=hit.n,v=-rd;
        vec3 base=vec3(0);float rough=.5,metal=0.0,shade=1.0,matteInk=0.0;
        bool panelHit=hit.material==0&&n.z>.95;
        if(hit.material==0) {
            if(panelHit) {
                vec2 panelUV=clamp(tbvPanelPoint(p.xy)/vec2(1200,560),0.0,1.0);
                vec2 texSize=max(iChannelResolution[0].xy,vec2(5));
                panelUV=(2.0+panelUV*(texSize-4.0))/texSize;
                vec4 plate=textureLod(iChannel0,panelUV,0.0);
                base=plate.rgb;shade=plate.a;rough=.56;metal=.48;
                matteInk=1.0-smoothstep(.045,.15,min(base.r,min(base.g,base.b)));
            } else {
                base=vec3(.29,.30,.279);
                base*=1.0-.55*exp(-abs(p.z+39.0)/1.5);
                if(n.z>.2)base=vec3(.55,.56,.52);
                rough=.42;metal=.48;
                shade=.66+.34*smoothstep(-48.0,-15.0,p.z);
            }
        } else if(hit.material==1||hit.material==2||hit.material==5||hit.material==6) {
            tbvKnobMaterial(p,n,hit.id,hit.material,base,rough,metal);
        } else {
            base=hit.material==3?vec3(.026,.028,.025):vec3(.35,.36,.329);
            if(hit.material==4) {
                vec4 b=tbvButton(hit.id);vec2 q=p.xy-tbvWorldPoint(b.xy);
                base+=.03*(q.y/max(b.w,1.0));
                base+=(tbvHash(floor(p.xy*1.7))-.5)*.013;
                base+=vec3(.095,.002,0)*tbvButtonOn(hit.id)*exp(-pow((q.y-b.w+2.0)/6.0,2.0));
            }
            rough=hit.material==3?.47:.32;metal=hit.material==3?.05:.65;
        }
        // One lighting call for every material avoids four inlined BRDF copies.
        c=mix(tbvLighting(base,n,v,rough,metal),base*.92,matteInk)*shade;
        if(panelHit)tbvLEDLenses(c,tbvPanelPoint(p.xy));
    }
    c=tbvToneMap(c);
    float vig=1.0-.16*pow(length((fragCoord-.5*iResolution.xy)/iResolution.xy),1.4);
    c*=vig;
    c+=(tbvHash(fragCoord)-.5)/255.0;
    fragColor=vec4(clamp(c,0.0,1.0),1.0);
}

// Shared sequencer and panel. This snapshot matches the supplied Common tab.
#ifndef PI
#define PI 3.14159265358979323846
#endif
#ifndef TAU
#define TAU 6.28318530717958647692
#endif
#define BPM 136.0
#define ROOT_MIDI 36.0
#define TB_TUNING 0.0
#define STEPS_PER_BEAT 4.0
#define PAT_LEN 16
#define PAT_REPS 2
#define NUM_PATTERNS 4
#define STEP_DUR (60.0 / BPM / STEPS_PER_BEAT)
#define PAT_DUR (float(PAT_LEN) * STEP_DUR)
#define S(n,o,g,sl,ac) ((n)|((o)<<4)|((g)<<5)|((sl)<<6)|((ac)<<7))
const int PATTERNS[NUM_PATTERNS * PAT_LEN] = int[NUM_PATTERNS * PAT_LEN](
    S(0,0,1,0,1),S(0,0,0,0,0),S(0,0,1,0,0),S(7,0,1,0,0),
    S(0,0,1,0,1),S(0,0,0,0,0),S(5,0,1,0,0),S(0,0,1,0,0),
    S(0,0,1,0,1),S(0,0,0,0,0),S(7,0,1,1,0),S(10,0,1,0,0),
    S(0,0,1,0,1),S(5,0,1,0,0),S(3,0,1,0,0),S(0,0,0,0,0),
    S(0,0,1,0,1),S(0,0,1,1,0),S(3,0,1,0,0),S(5,0,1,1,1),
    S(7,0,1,0,1),S(0,0,0,0,0),S(7,0,1,0,0),S(10,0,1,1,0),
    S(0,1,1,0,1),S(0,0,0,0,0),S(7,0,1,0,0),S(5,0,1,1,0),
    S(3,0,1,0,1),S(0,0,1,0,0),S(5,0,1,1,0),S(7,0,1,0,0),
    S(0,0,1,0,1),S(3,0,1,1,0),S(5,0,1,0,1),S(3,0,1,1,0),
    S(5,0,1,0,1),S(7,0,1,1,0),S(5,0,1,0,0),S(3,0,1,0,1),
    S(0,0,1,0,0),S(0,1,1,1,1),S(0,1,1,1,0),S(10,0,1,0,1),
    S(7,0,1,1,0),S(5,0,1,0,1),S(3,0,1,1,0),S(0,0,1,0,0),
    S(0,0,1,0,1),S(0,0,0,0,0),S(0,0,0,0,0),S(0,0,1,0,1),
    S(0,0,1,0,0),S(0,0,0,0,0),S(7,0,1,0,1),S(0,0,0,0,0),
    S(0,0,1,0,1),S(5,0,1,1,0),S(3,0,1,0,1),S(5,0,1,1,1),
    S(7,0,1,0,1),S(0,1,1,1,0),S(10,0,1,0,1),S(7,0,1,0,0)
);
#define DEMO_MODE 1
#define DEMO_CUTOFF_LO 0.09
#define DEMO_CUTOFF_HI 0.87
#define DEMO_CUTOFF_SLOW_HZ 0.0141
#define DEMO_CUTOFF_SLOW_PH 0.52
#define DEMO_CUTOFF_RIPPLE 0.34
#define DEMO_CUTOFF_FAST_HZ 0.1130
#define DEMO_CUTOFF_FAST_PH 0.08
// demo mode knob sweeps
#define DEMO_WAVEFORM    0.40, 0.00, 0.10, 1.00, 0.25
#define DEMO_RESONANCE   0.42, 1.20, 0.08, 0.78, 0.6
#define DEMO_ENV_MOD     0.28, 0.75, 0.04, 0.93, 0.6
#define DEMO_DECAY       0.82, 0.30, 0.02, 0.55, 0.1
#define DEMO_ACCENT      0.54, 0.20, 0.06, 0.93, 0.0
#define DEMO_RAT_DISTORT 0.52, 0.28, 0.01, 0.91, 0.4
#define DEMO_RAT_FILTER  0.62,-0.30, 0.03, 0.92, 0.4

int wrap16(int i){int m=i%PAT_LEN;return m<0?m+PAT_LEN:m;}
float midiToHz(float m){return 440.0*exp2((m-69.0)/12.0);}
float triWave(float x){return 1.0-4.0*abs(fract(x)-0.5);}
float lfoWave(float t,float hz,float ph,float shape){float p=fract(t*hz+ph);return mix(sin(TAU*p),triWave(p),shape);}
float demoKnob(float t,float centre,float depth,float hz,float ph,float shape){return clamp(centre+depth*lfoWave(t,hz,ph,shape),0.0,1.0);}
void resolvePanel(float t,out float waveform,out float cutoff,out float resonance,out float envMod,out float decay,out float accent,out float ratDist,out float ratFilter){
#if DEMO_MODE
    waveform=demoKnob(t,DEMO_WAVEFORM);
    float swell=0.5+0.5*lfoWave(t,DEMO_CUTOFF_SLOW_HZ,DEMO_CUTOFF_SLOW_PH,0.3);
    float ripple=lfoWave(t,DEMO_CUTOFF_FAST_HZ,DEMO_CUTOFF_FAST_PH,0.42)*DEMO_CUTOFF_RIPPLE;
    cutoff=clamp(mix(DEMO_CUTOFF_LO,DEMO_CUTOFF_HI,swell)+ripple,0.0,1.0);
    resonance=demoKnob(t,DEMO_RESONANCE);envMod=demoKnob(t,DEMO_ENV_MOD);
    decay=demoKnob(t,DEMO_DECAY);accent=demoKnob(t,DEMO_ACCENT);
    ratDist=demoKnob(t,DEMO_RAT_DISTORT);ratFilter=demoKnob(t,DEMO_RAT_FILTER);
#else
    waveform=0.0;cutoff=0.62;resonance=0.88;envMod=0.28;
    decay=0.82;accent=0.24;ratDist=0.32;ratFilter=0.42;
#endif
}
int patternIndex(float t){return (int(floor(t/PAT_DUR))/PAT_REPS)%NUM_PATTERNS;}
int curPatStep(float t){return int(mod(t/STEP_DUR,float(PAT_LEN)));}
void getStepData(int pat,int idx,out float gate,out float slide,out float accent,out float hz){
    int pk=PATTERNS[clamp(pat,0,NUM_PATTERNS-1)*PAT_LEN+wrap16(idx)];
    gate=float((pk>>5)&1);slide=float((pk>>6)&1);accent=float((pk>>7)&1);
    hz=midiToHz(ROOT_MIDI+TB_TUNING+float((pk&15)+12*((pk>>4)&1)));
}
float stepEnv(float t,int pat,int s){
    float phase=mod(t,PAT_DUR)/STEP_DUR;float ago=mod(phase-float(s),float(PAT_LEN));
    float gate,slide,acc,hz;getStepData(pat,s,gate,slide,acc,hz);return gate*exp(-ago*3.5);
}

// TB-303 / RAT -- stateless harmonic-domain renderer.
// Requires the supplied Common tab. No channels or Buffer passes are needed.
// The nonlinear ladder is approximated by RMS harmonic balance, not replayed.
// All phase/envelope reconstruction is independent of output-sample order.

#define TB_VOLUME        0.80
#define RAT_ENABLE          1
#define RAT_LEVEL        1.05
#define RAT_MIX          0.82
#define RAT_TIGHT        0.18
#define RAT_LED_BLEND    0.10

#define TB_HARMONICS       36
#define TB_BALANCE_HARM    24
#define TB_BALANCE_PASSES   3
#define TB_SONG_STEPS (PAT_LEN * PAT_REPS * NUM_PATTERNS)

const float tbSlideTau = 0.060;
const float tbNoteTau = 0.0015; // Slews non-slide pitch changes without resetting phase.
const float tbModelDt = 1.0 / 28000.0;
const float tbPitchRatio[16] = float[16](
    1.0,1.0594630944,1.1224620483,1.1892071150,
    1.2599210499,1.3348398542,1.4142135624,1.4983070769,
    1.5874010520,1.6817928305,1.7817974363,1.8877486254,
    2.0,2.1189261887,2.2449240966,2.3784142300
);

int tbWrap(int n,int d){int r=n%d;return r<0?r+d:r;}
int tbPacked(int s){
    s=tbWrap(s,TB_SONG_STEPS);
    int pat=s/(PAT_LEN*PAT_REPS);
    return PATTERNS[pat*PAT_LEN+s%PAT_LEN];
}
float tbPitch(int p,float root){return root*tbPitchRatio[p&15]*float(1+((p>>4)&1));}
float tbGate(int p){return float((p>>5)&1);}
float tbAcc(int p){return float((p>>7)&1)*tbGate(p);}
bool tbLegato(int p,int prev){return (p&96)==96 && (prev&32)!=0;}

// Integer seconds prevent float(sample) losing adjacent samples after 2^24.
// Transport tempo is rounded to 0.01 step/minute; supplied 136 BPM is exact.
void tbClock(int sampleIndex,out int stepIndex,out float localTime){
    int sr=max(1,int(iSampleRate+0.5));
    int sec=sampleIndex/sr;
    int rate=max(1,int(BPM*STEPS_PER_BEAT*100.0+0.5));
    int n=(sec%6000)*rate;
    stepIndex=(sec/6000)*rate+n/6000;
    localTime=float(n%6000)/float(rate)+(float(sampleIndex%sr)+0.5)/iSampleRate;
    float dur=6000.0/float(rate);
    int advance=int(floor(localTime/dur));
    stepIndex+=advance;
    localTime-=float(advance)*dur;
}

float tbLoopPhase(int n,float f){
    // Reduce each product before adding; never multiply full playback time by Hz.
    return fract(float(n&255)*f+float(n>>8)*fract(256.0*f));
}
float tbPulse(float age,float tau){return exp(-max(age,0.0)/tau);}
float tbReleasePulse(float age){
    age=max(age,0.0);
    return (0.142*exp(-age/0.142)-0.070*exp(-age/0.070))/0.072;
}

struct TBVoice{float phase;float hz;float env;float rc2;float amp;float accent;};

TBVoice tbSequence(int absStep,float lt,float decay,float accentKnob){
    TBVoice v;
    int current=tbWrap(absStep,TB_SONG_STEPS);
    int loops=absStep/TB_SONG_STEPS;
    float root=midiToHz(ROOT_MIDI+TB_TUNING);
    float tau0=mix(0.090,0.300,decay),tau1=mix(0.050,0.660,decay);
    float aSlide=exp(-STEP_DUR/tbSlideTau),aNote=exp(-STEP_DUR/tbNoteTau);

    // Compose the affine pitch maps backwards. An ordinary note makes older
    // pitch contributions negligible; an all-slide cycle has an exact fixed point.
    float pitchA=1.0,pitchB=0.0;
    for(int j=0;j<TB_SONG_STEPS;++j){
        int p=tbPacked(TB_SONG_STEPS-1-j);
        int prev=tbPacked(TB_SONG_STEPS-2-j);
        if((p&32)!=0){
            float a=tbLegato(p,prev)?aSlide:aNote;
            pitchB+=pitchA*(1.0-a)*tbPitch(p,root);
            pitchA*=a;
        }
        if(pitchA<1e-8) break;
    }
    float startHz=pitchA<0.999999?pitchB/(1.0-pitchA):root;
    int previous;
    float hz=startHz,phase=0.0,localStart=hz;
    float target=hz,tau=tbNoteTau,phaseHere=0.0;
    float decaySum=0.0,decayHere=0.0;
    float onPrefix=0.0,oldPrefix=0.0;
    float onAge=1e6,oldAge=1e6,accAge=1e6,oldAccAge=1e6;
    int onPos=0,oldPos=0;
    previous=tbPacked(TB_SONG_STEPS-1);
    for(int j=0;j<TB_SONG_STEPS;++j){
        int p=tbPacked(j);
        bool gateOn=(p&32)!=0;
        bool legato=tbLegato(p,previous);
        float th=gateOn?tbPitch(p,root):hz;
        float st=legato?tbSlideTau:tbNoteTau;
        float a=gateOn?(legato?aSlide:aNote):1.0;
        if(j==current){
            localStart=hz;target=th;tau=st;
            phaseHere=phase;decayHere=decaySum;
        }
        int ago=tbWrap(current-j,TB_SONG_STEPS);
        bool available=absStep>=ago;
        bool onset=gateOn&&!legato;
        // A slide on the first audible step still starts an envelope.
        if(j==0 && absStep<TB_SONG_STEPS && (tbPacked(0)&32)!=0) onset=true;
        float age=float(ago)*STEP_DUR+lt;
        if(available&&onset){
            if(age<onAge){
                oldAge=onAge;oldPrefix=onPrefix;oldPos=onPos;
                onAge=age;onPrefix=decaySum;onPos=j;
            }else if(age<oldAge){oldAge=age;oldPrefix=decaySum;oldPos=j;}
            if((p&128)!=0){
                if(age<accAge){oldAccAge=accAge;accAge=age;}
                else if(age<oldAccAge) oldAccAge=age;
            }
        }
        float cyc=th*STEP_DUR+(hz-th)*st*(1.0-a);
        phase=fract(phase+cyc);
        hz=mix(th,hz,a);
        decaySum+=STEP_DUR/mix(tau0,tau1,tbAcc(p));
        previous=p;
    }
    int p=tbPacked(current),prev=tbPacked(current-1);
    float ag=tbAcc(p),ap=absStep>0?tbAcc(prev):0.0;
    float ac=mix(ap,ag,1.0-exp(-lt/0.0015));
    bool gateOn=(p&32)!=0;
    float pitchE=gateOn?exp(-lt/tau):1.0;
    v.hz=mix(target,localStart,pitchE);
    v.phase=fract(tbLoopPhase(loops,phase)+phaseHere+
                  target*lt+(localStart-target)*tau*(1.0-pitchE));

    // A completely tied song has only its initial trigger.
    if(onAge>1e5 && (tbPacked(0)&32)!=0){
        onAge=float(absStep)*STEP_DUR+lt;
        onPos=0;onPrefix=0.0;
    }
    float tauNow=mix(tau0,tau1,ag);
    float integral=decayHere-onPrefix+(onPos>current?decaySum:0.0)+lt/tauNow;
    float integralOld=decayHere-oldPrefix+(oldPos>current?decaySum:0.0)+lt/tauNow;
    if(onAge>float(TB_SONG_STEPS)*STEP_DUR) integral=onAge/tauNow;
    float pulse=onAge<1e5?exp(-max(integral,0.0)):0.0;
    float oldPulse=oldAge<1e5?exp(-max(integralOld,0.0)):0.0;
    float tauEffective=clamp(onAge/max(integral,1e-5),0.050,0.660);
    float shape=tauEffective/max(tauEffective-0.0019,0.001);
    v.env=max(0.0,shape*pulse+(oldPulse-shape)*exp(-onAge/0.0019));

    float accPulse=tbPulse(accAge,0.022);
    float accOld=tbPulse(oldAccAge,0.022);
    float accSmooth=(0.022/0.021)*(accPulse-exp(-accAge/0.001));
    accSmooth+=accOld*exp(-accAge/0.001);
    // Analytic 22 ms pulse into the slower accent capacitor.
    float accRC=(0.022/0.007)*(accPulse-exp(-accAge/0.015));
    accRC+=(0.022/0.007)*(accOld-exp(-oldAccAge/0.015))*exp(-accAge/0.015);
    float acRC=mix(ap,ag,1.0-exp(-lt/0.015));
    v.rc2=max(0.0,acRC*v.env+accRC);
    v.accent=ac;
    float ampNew=tbReleasePulse(onAge),ampOld=tbReleasePulse(oldAge);
    float amp=mix(ampNew,ampOld,exp(-onAge/0.0032));
    float slide=tbLegato(p,prev)?1.0:0.0;
    float prevSlide=absStep>0&&tbLegato(prev,tbPacked(current-2))?1.0:0.0;
    float held=mix(prevSlide,slide,1.0-exp(-lt/0.0032));
    v.amp=max(amp,0.62*held)*(1.0+mix(0.12,0.34,accentKnob)*ac)
          +max(0.0,accSmooth)*mix(0.02,0.10,accentKnob);
    return v;
}

vec2 tbMul(vec2 a,vec2 b){return vec2(a.x*b.x-a.y*b.y,a.x*b.y+a.y*b.x);}
vec2 tbDiv(vec2 a,vec2 b){return vec2(dot(a,b),a.y*b.x-a.x*b.y)/max(dot(b,b),1e-16);}
vec2 tbLP(vec2 q,float a){return tbDiv(vec2(1.0-a,0.0),vec2(1.0,0.0)-a*q);}
vec2 tbHP(vec2 q,float a){return tbDiv(a*(vec2(1.0,0.0)-q),vec2(1.0,0.0)-a*q);}

struct TBFilter{float b;float b1;float k;float gain;float drive;float smoothA;};
TBFilter tbFilter(float cutoff,float res,float drive,float smoothHz){
    TBFilter f;
    float x=clamp(cutoff*tbModelDt*0.70710678,0.0,0.35);
    float r=(1.0-exp(-3.0*res))/(1.0-exp(-3.0));
    f.b=(0.00045522346+6.1922189*x)/(1.0+12.358354*x+4.4156345*x*x);
    float k=x*(x*(x*(x*(x*(x+7198.6997)-5837.7917)-476.47308)+614.95611)+213.87126)+16.998792;
    f.b1=f.b*1.08;f.k=k*r;f.gain=2.0*((k/17.0-1.0)*r+1.0)*(1.0+r);
    f.drive=drive;f.smoothA=exp(-TAU*smoothHz*tbModelDt);
    return f;
}

// Exact frozen-coefficient transfer of the supplied sequential ladder update,
// with equivalent gains replacing its three memoryless saturation points.
vec2 tbResponse(vec2 q,TBFilter f,vec3 gains,out vec3 power){
    const vec2 one=vec2(1.0,0.0);
    vec2 a=(one-(1.0-2.0*f.b)*q)/f.b;
    vec2 c3=(vec2(1.0/gains.z,0.0)-(1.0-2.0*f.b)*q)/f.b;
    vec2 c2=tbMul(a,c3)-q;
    vec2 c1=tbMul(a,c2)-tbMul(q,c3);
    vec2 b=(one-gains.y*(1.0-2.0*f.b1)*q)/(2.0*f.b1);
    vec2 c0=tbMul(b,c1)-tbMul(q,c2);
    vec2 feedback=tbMul(q,tbHP(q,exp(-TAU*150.0*tbModelDt)));
    vec2 pre=tbMul(tbLP(q,f.smoothA),tbHP(q,exp(-TAU*44.486*tbModelDt)));
    vec2 h4=tbDiv(gains.x*f.drive*pre,c0+gains.x*f.k*feedback);
    vec2 hu=tbMul(h4,c0)/gains.x;
    vec2 h1=tbMul(h4,c1);
    vec2 h4pre=h4*(1.02/gains.z);
    power=vec3(dot(hu,hu),dot(h1,h1),dot(h4pre,h4pre));
    return f.gain*h4;
}

float tbHarmonic(float n,float wave){
    float odd=mod(n,2.0);
    return (-2.0*(1.0-wave)+4.0*wave*odd)/(PI*n);
}
vec3 tbSaturationGain(vec3 power){
    // Sine describing function of x*(27+x*x)/(27+9*x*x), A*A=2*RMS*RMS.
    vec3 s=sqrt(1.0+(2.0/3.0)*power);
    return 1.0/9.0+(16.0/9.0)/(s*(1.0+s));
}
vec3 tbBalance(float hz,float wave,TBFilter f){
    vec3 gains=vec3(0.94,0.963,1.019);
    vec2 rotation=vec2(cos(TAU*hz*tbModelDt),-sin(TAU*hz*tbModelDt));
    for(int pass=0;pass<TB_BALANCE_PASSES;++pass){
        vec3 p=vec3(0.0);vec2 q=rotation;
        for(int j=1;j<=TB_BALANCE_HARM;++j){
            float n=float(j),amp=tbHarmonic(n,wave);
            float band=1.0-smoothstep(10500.0,12500.0,hz*n);
            vec3 internalPower;
            tbResponse(q,f,gains,internalPower);
            p+=0.5*amp*amp*band*band*internalPower;
            q=tbMul(q,rotation);
        }
        vec3 target=tbSaturationGain(p)*vec3(1.0,1.0,1.02);
        gains=mix(gains,clamp(target,vec3(0.15),vec3(1.0,1.0,1.02)),0.6);
    }
    return gains;
}

float tbSat(float x){x=clamp(x,-3.0,3.0);return x*(27.0+x*x)/(27.0+9.0*x*x);}
float tbKnobExp(float x){return (exp(4.0*clamp(x,0.0,1.0))-1.0)/(exp(4.0)-1.0);}
float tbLogCosh(float x){float a=abs(x);return a+log(1.0+exp(-2.0*a));}
float tbTanhAA(float a,float b,float limit){
    a/=limit;b/=limit;
    float d=a-b;
    if(abs(d)<0.003) return limit*tanh(0.5*(a+b));
    return limit*(tbLogCosh(a)-tbLogCosh(b))/d;
}
float tbPedalPre(float x,float gain){
    x=tbSat(1.62*x)*gain;
    return 1.15*(2.0/PI)*atan(x*(PI/(2.0*1.15)));
}
float tbPedalAA(float a,float b){
    return mix(tbTanhAA(a,b,0.34),0.70*tbTanhAA(a,b,0.95),RAT_LED_BLEND);
}

void tbAdvance(inout vec4 sn,inout vec4 cs,vec4 s1,vec4 c1){
    vec4 old=sn;sn=sn*c1+cs*s1;cs=cs*c1-old*s1;
}

vec2 mainSound(int samp,float time){
    if(samp<0) return vec2(0.0);
    int stepIndex;float lt;tbClock(samp,stepIndex,lt);
    // Only slow panel modulation uses absolute float time; audio phase does not.
    float wf,cf,rk,ek,dk,ak,rd,rf;
    resolvePanel(time,wf,cf,rk,ek,dk,ak,rd,rf);
    TBVoice v=tbSequence(stepIndex,lt,dk,ak);
    float low=1.0-smoothstep(110.0,220.0,v.hz);
#if DEMO_MODE
    float lfoCut=lfoWave(time,0.1130,0.08,0.42)*0.80;
    float lfoRes=lfoWave(time,0.0283,0.41,0.22);
    float lfoEnv=lfoWave(time,0.0430,0.73,0.62);
#else
    float lfoCut=0.0,lfoRes=0.0,lfoEnv=0.0;
#endif
    float envMod=clamp(ek*clamp(1.0+0.35*lfoEnv,0.15,1.85),0.0001,1.15);
    float base=120.0*exp2(cf*log2(40.0)+0.055*log2(max(v.hz,1.0)/midiToHz(ROOT_MIDI+TB_TUNING+12.0))+lfoCut);
    float c=clamp(log(base/313.81528)/log(2394.41199/313.81528),0.0,1.0);
    float envScale=mix(3.77399633*envMod+0.73696559,4.19454879*envMod+0.86434490,c);
    float envOffset=0.04829293*c+0.29439120;
    float cutoff=clamp(base*exp2(ek*(envScale*(v.env-envOffset)+0.52*ak*v.rc2)),40.0,2200.0);
    float resonance=clamp(mix(0.35,0.94,sqrt(rk))+(0.015+0.035*ek)*smoothstep(0.05,1.10,v.env+0.60*v.rc2)+0.57*lfoRes,0.0,0.965);
    float drive=1.25*mix(1.0,0.92,low)*(1.0+0.18*ak*v.accent);
    TBFilter flt=tbFilter(cutoff,resonance,drive,7200.0*mix(1.0,0.84,low));
    vec3 gains=tbBalance(v.hz,wf,flt);

    float pedalGain=mix(1.6,20.0,tbKnobExp(rd));
    float toneHz=clamp(1.0/(TAU*0.0033e-6*(2500.0+100000.0*tbKnobExp(rf))),470.0,19292.0);
    // 16 exponential-weighted cells, each integrated through the diode clipper.
    // This is a finite quadrature of the tone LP, not zero-state filter replay.
    float toneDt=max(0.5/iSampleRate,1.0/(4.0*TAU*toneHz));
    float toneA=exp(-TAU*toneHz*toneDt);
    float phase=TAU*v.phase,phaseStep=TAU*v.hz*toneDt;
    vec4 p0=phase-phaseStep*vec4(0.0,1.0,2.0,3.0);
    vec4 p1=phase-phaseStep*vec4(4.0,5.0,6.0,7.0);
    vec4 p2=phase-phaseStep*vec4(8.0,9.0,10.0,11.0);
    vec4 p3=phase-phaseStep*vec4(12.0,13.0,14.0,15.0);
    vec4 p4=vec4(phase-16.0*phaseStep,phase-0.25*TAU*v.hz/iSampleRate,phase+0.25*TAU*v.hz/iSampleRate,0.0);
    vec4 s0=sin(p0),c0=cos(p0),s1=sin(p1),c1=cos(p1),s2=sin(p2),c2=cos(p2);
    vec4 s3=sin(p3),c3=cos(p3),s4=sin(p4),c4=cos(p4);
    vec4 h0s=s0,h0c=c0,h1s=s1,h1c=c1,h2s=s2,h2c=c2,h3s=s3,h3c=c3,h4s=s4,h4c=c4;
    vec4 w0=vec4(0.0),w1=w0,w2=w0,w3=w0,w4=w0;
    vec2 dry=vec2(0.0);
    vec2 rot=vec2(cos(TAU*v.hz*tbModelDt),-sin(TAU*v.hz*tbModelDt));
    // Fixed oscillator-phase quadrature removes waveshaper DC without history.
    vec4 dcP0=(TAU/32.0)*vec4(0.0,1.0,2.0,3.0);
    vec4 dcS0=sin(dcP0),dcC0=cos(dcP0);
    vec4 dcHS0=dcS0,dcHC0=dcC0,dcV0=vec4(0.0);
    vec4 dcP1=(TAU/32.0)*vec4(4.0,5.0,6.0,7.0);
    vec4 dcS1=sin(dcP1),dcC1=cos(dcP1);
    vec4 dcHS1=dcS1,dcHC1=dcC1,dcV1=vec4(0.0);
    vec4 dcP2=(TAU/32.0)*vec4(8.0,9.0,10.0,11.0);
    vec4 dcS2=sin(dcP2),dcC2=cos(dcP2);
    vec4 dcHS2=dcS2,dcHC2=dcC2,dcV2=vec4(0.0);
    vec4 dcP3=(TAU/32.0)*vec4(12.0,13.0,14.0,15.0);
    vec4 dcS3=sin(dcP3),dcC3=cos(dcP3);
    vec4 dcHS3=dcS3,dcHC3=dcC3,dcV3=vec4(0.0);
    vec4 dcP4=(TAU/32.0)*vec4(16.0,17.0,18.0,19.0);
    vec4 dcS4=sin(dcP4),dcC4=cos(dcP4);
    vec4 dcHS4=dcS4,dcHC4=dcC4,dcV4=vec4(0.0);
    vec4 dcP5=(TAU/32.0)*vec4(20.0,21.0,22.0,23.0);
    vec4 dcS5=sin(dcP5),dcC5=cos(dcP5);
    vec4 dcHS5=dcS5,dcHC5=dcC5,dcV5=vec4(0.0);
    vec4 dcP6=(TAU/32.0)*vec4(24.0,25.0,26.0,27.0);
    vec4 dcS6=sin(dcP6),dcC6=cos(dcP6);
    vec4 dcHS6=dcS6,dcHC6=dcC6,dcV6=vec4(0.0);
    vec4 dcP7=(TAU/32.0)*vec4(28.0,29.0,30.0,31.0);
    vec4 dcS7=sin(dcP7),dcC7=cos(dcP7);
    vec4 dcHS7=dcS7,dcHC7=dcC7,dcV7=vec4(0.0);
    vec2 q=rot;
    for(int j=1;j<=TB_HARMONICS;++j){
        float n=float(j),f=n*v.hz;
        float band=1.0-smoothstep(min(10500.0,0.40*iSampleRate),min(12500.0,0.47*iSampleRate),f);
        band*=1.0-smoothstep(float(TB_HARMONICS-4),float(TB_HARMONICS+1),n);
        vec3 unused;
        vec2 h=tbResponse(q,flt,gains,unused);
        // Coupling capacitors and the original post-filter phase rotation.
        h=tbMul(h,tbHP(q,exp(-TAU*24.167*tbModelDt)));
        float ap=(1.0-tan(PI*14.008*tbModelDt))/(1.0+tan(PI*14.008*tbModelDt));
        h=tbMul(h,tbDiv(q-vec2(ap,0.0),vec2(1.0,0.0)-ap*q));
        h=tbMul(h,tbLP(q,exp(-TAU*18000.0*tbModelDt)));
        h*=tbHarmonic(n,wf)*band*v.amp;
        dry+=h.x*h4s.yz+h.y*h4c.yz;
        vec2 wet=tbMul(h,tbHP(q,exp(-TAU*(10.0+RAT_TIGHT*300.0)*tbModelDt)));
        wet=tbMul(wet,tbLP(q,exp(-TAU*5000.0*tbModelDt)));
        wet=tbMul(wet,tbHP(q,exp(-TAU*10.0*tbModelDt)));
        wet=tbMul(wet,tbHP(q,exp(-TAU*7.7*tbModelDt)));
        wet*=1.0-smoothstep(0.34/toneDt,0.47/toneDt,f);
        w0+=wet.x*h0s+wet.y*h0c;w1+=wet.x*h1s+wet.y*h1c;
        w2+=wet.x*h2s+wet.y*h2c;w3+=wet.x*h3s+wet.y*h3c;
        w4.x+=wet.x*h4s.x+wet.y*h4c.x;
        dcV0+=wet.x*dcHS0+wet.y*dcHC0;
        tbAdvance(dcHS0,dcHC0,dcS0,dcC0);
        dcV1+=wet.x*dcHS1+wet.y*dcHC1;
        tbAdvance(dcHS1,dcHC1,dcS1,dcC1);
        dcV2+=wet.x*dcHS2+wet.y*dcHC2;
        tbAdvance(dcHS2,dcHC2,dcS2,dcC2);
        dcV3+=wet.x*dcHS3+wet.y*dcHC3;
        tbAdvance(dcHS3,dcHC3,dcS3,dcC3);
        dcV4+=wet.x*dcHS4+wet.y*dcHC4;
        tbAdvance(dcHS4,dcHC4,dcS4,dcC4);
        dcV5+=wet.x*dcHS5+wet.y*dcHC5;
        tbAdvance(dcHS5,dcHC5,dcS5,dcC5);
        dcV6+=wet.x*dcHS6+wet.y*dcHC6;
        tbAdvance(dcHS6,dcHC6,dcS6,dcC6);
        dcV7+=wet.x*dcHS7+wet.y*dcHC7;
        tbAdvance(dcHS7,dcHC7,dcS7,dcC7);
        tbAdvance(h0s,h0c,s0,c0);tbAdvance(h1s,h1c,s1,c1);
        tbAdvance(h2s,h2c,s2,c2);tbAdvance(h3s,h3c,s3,c3);tbAdvance(h4s,h4c,s4,c4);
        q=tbMul(q,rot);
    }
    float dryOut=tbTanhAA(1.62*dry.x,1.62*dry.y,1.0);
#if RAT_ENABLE
    float taps[17]=float[17](w0.x,w0.y,w0.z,w0.w,w1.x,w1.y,w1.z,w1.w,
                            w2.x,w2.y,w2.z,w2.w,w3.x,w3.y,w3.z,w3.w,w4.x);
    float weight=1.0,wetOut=0.0,weights=0.0;
    float prev=tbPedalPre(taps[0],pedalGain);
    for(int j=0;j<16;++j){
        float next=tbPedalPre(taps[j+1],pedalGain);
        wetOut+=weight*tbPedalAA(prev,next);weights+=weight;
        prev=next;weight*=toneA;
    }
    float dcTaps[32]=float[32](dcV0.x,dcV0.y,dcV0.z,dcV0.w,dcV1.x,dcV1.y,dcV1.z,dcV1.w,dcV2.x,dcV2.y,dcV2.z,dcV2.w,dcV3.x,dcV3.y,dcV3.z,dcV3.w,dcV4.x,dcV4.y,dcV4.z,dcV4.w,dcV5.x,dcV5.y,dcV5.z,dcV5.w,dcV6.x,dcV6.y,dcV6.z,dcV6.w,dcV7.x,dcV7.y,dcV7.z,dcV7.w);
    float dcMean=0.0;
    for(int j=0;j<32;++j){
        float dc=tbPedalPre(dcTaps[j],pedalGain);
        dcMean+=mix(0.34*tanh(dc/0.34),0.665*tanh(dc/0.95),RAT_LED_BLEND);
    }
    dcMean/=32.0;
    float signal=mix(dryOut,RAT_LEVEL*(wetOut/weights-dcMean),RAT_MIX);
#else
    float signal=dryOut;
#endif
    float outLevel=0.25*1.35*TB_VOLUME;
    return vec2(clamp(outLevel*signal,-0.98,0.98));
}

